import type { CultureArticle } from "../types";

const items: CultureArticle[] = [{"id":"oce-022","version":2,"slug":"talofa-a-greeting-built-on-alofa","contentType":"language","category":"languages","title":{"ar":"تالوفا: تحية قائمة على المحبة","de":"Talofa: Ein Gruß, der auf Liebe baut","en":"Talofa: a greeting built on alofa"},"deck":{"ar":"تحية ساموية يومية تحمل في جذورها معنى الحب والالتزام المتبادل.","de":"Ein alltäglicher samoanischer Gruß, dessen Wurzel Liebe und gegenseitige Verpflichtung bedeutet.","en":"An everyday Samoan greeting whose root means love and mutual obligation."},"teaser":{"ar":"تالوفا ليست مجرد كلمة مرحبا؛ إنها تعبير عن المحبة والكرم في الثقافة الساموية، ولها صلة بكلمة ألوفا التي تعني الحب.","de":"Talofa ist mehr als ein Hallo; es drückt Liebe und Großzügigkeit in der samoanischen Kultur aus und teilt seine Wurzel mit alofa, dem Wort für Liebe.","en":"Talofa is more than hello; it carries love and generosity in Samoan culture and shares its root with alofa, the word for love."},"readingMinutes":1,"sections":{"ar":[{"heading":"جذور المحبة في التحية","paragraphs":["تالوفا هي التحية الساموية اليومية، وتالوفا لافا صيغة أكثر دفئاً ورسمية، والرد المعتاد هو تالوفا أو مالو. تشير الحكومة الأمريكية الساموية إلى أنها اختصار لعبارة سي أو تا ألوفا أتو، أي 'أنا سعيد ومسرور لأن أمنحك حبي'.","تتشارك الكلمة جذرها مع ألوفا، أي الحب والرحمة، وهو مفهوم يسري في فآ ساموا، فكرة الالتزام المتبادل. تختلف أشكال التحية حسب السياق والمستوى، ويختلف الإملاء الساموي، ويمزج السامويون في المهجر الإنجليزية بكلامهم اليومي."]},{"heading":"كلمة سافرت عبر المحيط","paragraphs":["انتقلت الكلمة: فهي أيضاً التحية في جزيرة ليفو في كاليدونيا الجديدة، حيث حملها معلمو جمعية لندن التبشيرية السامويون منذ عام 1841. الساموية هي أكثر اللغات البولينيزية انتشاراً، بنحو 510,000 متحدث حول العالم، منهم أكثر من 100,000 في نيوزيلندا."]}],"de":[{"heading":"Die Wurzel der Liebe im Gruß","paragraphs":["Talofa ist der alltägliche samoanische Gruß, talofa lava eine wärmere formelle Form, und die übliche Antwort ist talofa oder mālō. Die Regierung von Amerikanisch-Samoa erklärt ihn als Kurzform von 'si o ta alofa atu' – 'Ich bin froh und erfreut, dir meine Liebe zu geben'.","Das Wort teilt seine Wurzel mit alofa, Liebe und Mitgefühl, das auch das faʻa Sāmoa durchzieht, die Idee gegenseitiger Verpflichtung. Grußformen hängen von Kontext und Register ab, die samoanische Orthographie variiert, und Diaspora-Samoaner mischen Englisch in ihre Alltagssprache."]},{"heading":"Ein Wort, das über den Ozean reiste","paragraphs":["Das Wort reiste: Es ist auch der Gruß auf Lifou in Neukaledonien, wohin ihn samoanische Lehrer der London Missionary Society ab 1841 brachten. Samoanisch ist die meistgesprochene polynesische Sprache mit etwa 510.000 Sprechern weltweit, darunter über 100.000 in Neuseeland."]}],"en":[{"heading":"The root of love in the greeting","paragraphs":["Talofa is the everyday Samoan greeting, talofa lava a warmer formal form, and the usual reply is talofa or mālō. The American Samoa government glosses it as short for 'si o ta alofa atu' — 'I am happy and delighted to give you my love'.","It shares its root with alofa, love and compassion, which also runs through the faʻa Sāmoa idea of mutual obligation. Greeting forms depend on context and register, Samoan orthography varies, and diaspora Samoans mix English into everyday speech."]},{"heading":"A word that travelled across the sea","paragraphs":["The word travelled: it is also the greeting on Lifou in New Caledonia, brought by Samoan London Missionary Society teachers from 1841. Samoan is the most widely spoken Polynesian language, with about 510,000 speakers worldwide, including more than 100,000 in New Zealand."]}]},"context":{"countries":["WS"],"region":"Samoa","community":"Samoan","continent":"oceania","languages":["sm","en"],"period":"contemporary"},"tags":["languages","Samoa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Talofa","de":"Talofa","en":"Talofa"},"url":"https://en.wikipedia.org/wiki/Talofa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Samoan language","de":"Samoan language","en":"Samoan language"},"url":"https://en.wikipedia.org/wiki/Samoan_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يدخل زائر إلى قاعة كنيسة فيُحيا بعبارة 'تالوفا لافا'؛ والرد المتوقع هو 'تالوفا' قبل أي أمر آخر.","de":"Ein Besucher betritt einen Kirchenraum und wird mit 'Talofa lava' begrüßt; die erwartete Antwort ist 'Talofa', bevor irgendetwas anderes beginnt.","en":"A visitor steps into a church hall and is greeted 'Talofa lava'; the expected reply is 'Talofa' before any other business begins."},"misunderstanding":{"ar":"قد يظن البعض أن تالوفا مجرد تحية عابرة، لكنها تحمل دلالة المحبة والالتزام المتبادل في الثقافة الساموية.","de":"Manche halten Talofa für einen bloßen Gruß, doch es trägt die Bedeutung von Liebe und gegenseitiger Verpflichtung in der samoanischen Kultur.","en":"Some may think talofa is just a casual hello, but it carries the meaning of love and mutual obligation in Samoan culture."},"comparison":{"ar":"مثل كلمة 'سلام' في العربية التي تحمل معنى السلام والأمان، تحمل تالوفا معنى المحبة والكرم.","de":"Wie das arabische 'salam' Frieden und Sicherheit bedeutet, so trägt Talofa die Bedeutung von Liebe und Großzügigkeit.","en":"Like the Arabic 'salam' which means peace and safety, talofa carries the meaning of love and generosity."},"expression":{"original":"Talofa lava","language":"Gagana Sāmoa","gloss":{"ar":"تحية حارة؛ حرفياً عطاء محبة، يُرد عليها بـ 'تالوفا'.","de":"Ein herzliches Hallo; wörtlich ein Geben von Liebe, beantwortet mit 'Talofa'.","en":"A warm hello; literally a giving of love, answered with 'Talofa'."},"usage":{"ar":"تُستخدم عند الدخول إلى مكان أو لقاء شخص في سياق رسمي أو دافئ.","de":"Wird beim Betreten eines Ortes oder bei formeller Begrüßung verwendet.","en":"Used when entering a place or greeting someone formally or warmly."},"transliteration":"tah-LOH-fah LAH-vah"}},{"id":"oce-023","version":2,"slug":"kilikiti-the-village-cricket-that-can-last-for-days","contentType":"detail","category":"games-and-leisure","title":{"ar":"كريكيت القرية الذي يدوم أياماً","de":"Das Dorf-Kricket, das tagelang dauert","en":"The village cricket that lasts for days"},"deck":{"ar":"في ساموا، رياضة وطنية تُلعب بفريق مفتوح العدد ومضارب منحوتة، وتمتد أحياناً لأيام.","de":"In Samoa ist eine Nationalsportart ohne feste Teamgröße, mit geschnitzten Schlägern und Spielen, die sich über Tage ziehen.","en":"In Samoa, a national sport with open teams, carved bats and games that can stretch across whole days."},"teaser":{"ar":"كريكيت كيليكيتي رياضة ساموا الوطنية: فريق من كل من حضر، ومضرب منحوت، ومباراة قد تدوم أياماً على ملاعب القرى.","de":"Kilikiti ist Samoas Nationalsport: Jede und jeder, der kommt, spielt mit, die Schläger sind geschnitzt, und ein Dorfspiel kann tagelang dauern.","en":"Kilikiti is Samoa's national sport: teams are whoever turns up, bats are carved by hand, and a village match can run for days."},"readingMinutes":1,"sections":{"ar":[{"heading":"لعبة من كل من يحضر","paragraphs":["وصل الكريكيت إلى ساموا مع المبشّرين الإنجليز في أوائل القرن التاسع عشر، ثم أُعيد تشكيله عبر بولينيزيا حتى صار كيليكيتي. لا حدّ لعدد أعضاء الفريق: الفريق هو كل من حضر، من أي عمر أو جنس، ومعظم اللاعبين يضربون ويرمون الكرة معاً.","الكرة مطاط صلب ملفوف بورق الباندان، والمضرب ثلاثي الأوجه منحوت من قطعة واحدة على غرار هراوة الحرب الساموية القديمة المسماة لابالابا."]},{"heading":"ملعب القرية وامتداد الزمن","paragraphs":["قد تستمر مباريات القرى أياماً، وتقف على الهامش أكشاك الطعام وجماعات الكنيسة وعائلات بأكملها.","تختلف القواعد من قرية إلى أخرى وهي معيارية جزئياً فقط؛ فكيليكيتي ليس مجرد «كريكيت ساموي». وتختلف الأجيال أيضاً في طريقة اللعب: كبار السن يتمسكون بإيقاع القرية الطويل، بينما يفضّل الشباب في الشتات صيغاً أقصر.","في نيوزيلندا وحّدت رابطة كيليكيتي صيغة من سبعين دقيقة، وأطلقت بطولات وطنية وكأس عالم عامي ١٩٩٩ و٢٠٠١."]}],"de":[{"heading":"Ein Team aus allen, die kommen","paragraphs":["Das Kricket kam mit englischen Missionaren im frühen neunzehnten Jahrhundert nach Samoa und wurde über Polynesien hinweg umgeformt, bis daraus Kilikiti wurde. Die Teamgröße ist unbegrenzt: Es spielt, wer auftaucht, jeden Alters und Geschlechts, und die meisten schlagen und werfen zugleich.","Der Ball ist harter Gummi, in Pandanus gewickelt; der Schläger hat drei Seiten, ist aus einem Stück geschnitzt und dem alten samoanischen Kriegskeulen-Typ lapalapa nachempfunden."]},{"heading":"Der Dorfplatz und die gedehnte Zeit","paragraphs":["Dorfspiele können tagelang laufen; am Rand stehen Essensstände, Kirchengruppen und ganze Familien.","Die Regeln unterscheiden sich von Dorf zu Dorf und sind nur teilweise vereinheitlicht; Kilikiti ist nicht einfach „samoanisches Kricket“. Auch zwischen den Generationen variiert die Spielweise: Ältere halten am langen Dorfrhythmus fest, Jüngere in der Diaspora mögen kürzere Formate.","In Neuseeland standardisierte die New Zealand Kilikiti Association ein Format von siebzig Minuten und startete 1999 und 2001 nationale Turniere und Weltmeisterschaften."]}],"en":[{"heading":"A team of whoever shows up","paragraphs":["Cricket reached Samoa with English missionaries in the early nineteenth century and was reshaped across Polynesia into kilikiti. There is no limit on team size: teams are whoever turns up, of any age or gender, and most players both bat and bowl.","The ball is hard rubber bound in pandanus, and the bat is three-sided, carved from one piece and modelled on the old Samoan war club known as the lapalapa."]},{"heading":"The village ground and stretched time","paragraphs":["Village games can run for days, with food stalls, church groups and whole families on the sideline.","Rules vary from village to village and are only partly standardised; kilikiti is not simply 'Samoan cricket'. Generations differ too: older players keep the long village rhythm, while younger players in the diaspora often prefer shorter formats.","In New Zealand the Kilikiti Association standardised a 70-minute format and began national and World Cup tournaments in 1999 and 2001."]}]},"context":{"countries":["WS","NZ"],"region":"Samoa and the Pacific diaspora","community":"Samoan","continent":"oceania","languages":["sm","en"],"period":"contemporary"},"tags":["games-and-leisure","Samoa and the Pacific diaspora"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kilikiti","de":"Kilikiti","en":"Kilikiti"},"url":"https://en.wikipedia.org/wiki/Kilikiti","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Samoa","de":"Culture of Samoa","en":"Culture of Samoa"},"url":"https://en.wikipedia.org/wiki/Culture_of_Samoa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تلعب قريتان يوم سبت: المضارب منحوتة، والكرة مطاط صلب، والمتفرجون يجلسون على الحصر بينما تجمع أكشاك الطعام تبرعات للكنيسة.","de":"Zwei Dörfer spielen an einem Samstag: Die Schläger sind geschnitzt, der Ball ist harter Gummi, und Zuschauer sitzen auf Matten, während Essensstände Geld für die Kirche sammeln.","en":"Two villages play on a Saturday: the bats are carved, the ball is hard rubber, and spectators sit on mats while food stalls raise money for the church."},"misunderstanding":{"ar":"ليس كيليكيتي مجرد نسخة محلية من الكريكيت الإنجليزي؛ فقواعده تختلف من قرية إلى أخرى، وقد لا تنتهي المباراة في يوم واحد.","de":"Kilikiti ist nicht bloß eine lokale Variante des englischen Krickets; die Regeln wechseln von Dorf zu Dorf, und ein Spiel endet nicht zwingend am selben Tag.","en":"Kilikiti is not just a local version of English cricket; its rules shift from village to village and a match need not finish the same day."},"comparison":{"ar":"حيث يعدّ الكريكيت الدولي الوقت بالدقائق والساعات، تعدّ قرى كيليكيتي بالنهار والليلة، وبعدد من حضر لا بعدد المسجلين.","de":"Wo internationales Kricket in Minuten und Stunden rechnet, rechnen Kilikiti-Dörfer in Tagen und Nächten – und zählen, wer da ist, nicht wer gemeldet ist.","en":"Where international cricket counts in minutes and hours, kilikiti villages count in days and nights, and by who is present rather than who is registered."}},{"id":"oce-024","version":2,"slug":"ava-and-kava-the-drink-that-ranks-a-room","contentType":"note","category":"traditions","title":{"ar":"الكافا: مشروب يرتب المكانة","de":"Kava: Das Getränk, das den Raum ordnet","en":"Kava: The Drink That Ranks a Room"},"deck":{"ar":"من جذور نبات الفلفل، يصنع مشروب الكافا ليصبح خريطة حية للرتب الاجتماعية في جزر المحيط الهادئ.","de":"Aus der Wurzel einer Pfefferpflanze gewonnen, ist Kava ein Getränk, das soziale Ränge sichtbar macht und Gemeinschaft stiftet.","en":"Made from the root of a pepper plant, kava is a drink that maps social hierarchy and brings people together in a circle."},"teaser":{"ar":"في بولينيزيا وفيجي، الكافا ليست مجرد مشروب؛ إنها طقس يرتب الناس حسب مكانتهم ويجمعهم في دائرة واحدة.","de":"In Polynesien und Fidschi ist Kava mehr als ein Getränk – es ist ein Ritual, das Menschen nach Rang ordnet und in einem Kreis vereint.","en":"In Polynesia and Fiji, kava is more than a drink—it's a ritual that orders people by rank and unites them in a single circle."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس التحضير والتقديم","paragraphs":["يُحضر مشروب الكافا من جذور نبات الفلفل، واسمه يعني 'مر' في التونغية والماركيزية. في ساموا يُسمى ʻava، ويحضره فريق ʻaumaga ويقدمه tautuaʻava حسب الترتيب، حيث يُخدم أعلى رئيس زائر أولاً.","في تونغا، يجلس المشاركون في دائرة غير رسمية تسمى faikava، حيث يخلط touʻa الكافا ويقدمها. التحضير نفسه جزء من الاحتفال، وترتيب التقديم هو خريطة للرتبة يقرأها كل من في الغرفة."]},{"heading":"دلالات اجتماعية واختلافات إقليمية","paragraphs":["الكافا مسكنة خفيفة وغير كحولية، تُستخدم للترحيب بالضيوف وحل الخلافات وإحياء الجنازات والأعراس وتنصيب الألقاب. في فيجي، يُشرب yaqona في أي ساعة، ويقدم الزائر جذوره كـ sevusevu إلى الرئيس.","يختلف الطقس بشكل حاد بين تونغا وساموا وفيجي وفانواتو، كما يختلف بين الأجيال؛ فشرب الكافا العابر ليس كالطقس الرسمي. هذا التباين يعكس مرونة التقاليد عبر الزمان والمكان."]}],"de":[{"heading":"Zubereitung und Servierritual","paragraphs":["Kava wird aus der Wurzel der Pfefferpflanze Piper methysticum hergestellt; der Name bedeutet in Tongaisch und Marquesanisch 'bitter'. In Samoa heißt das Getränk ʻava, wird von der ʻaumaga-Gruppe zubereitet und vom tautuaʻava in Rangordnung serviert, wobei der höchste Gast zuerst bedient wird.","In Tonga versammelt sich die informelle faikava in einem Sitzkreis, in dem der touʻa die Kava mischt und ausschenkt. Die Zubereitung ist Teil der Zeremonie, und die Reihenfolge des Servierens ist eine Rangordnungskarte, die jeder im Raum lesen kann."]},{"heading":"Soziale Bedeutung und regionale Unterschiede","paragraphs":["Kava wirkt leicht sedierend und ist alkoholfrei; sie dient der Begrüßung von Gästen, der Beilegung von Streitigkeiten und der Markierung von Begräbnissen, Hochzeiten und Titelinstallationen. In Fidschi wird yaqona zu jeder Stunde getrunken, und ein Besucher überreicht sie als sevusevu dem Häuptling.","Die Zeremonie unterscheidet sich stark zwischen Tonga, Samoa, Fidschi und Vanuatu; auch zwischen den Generationen gibt es Unterschiede, denn lockeres Kavatrinken ist nicht dasselbe wie eine formelle Zeremonie. Diese Variation zeigt die Anpassungsfähigkeit der Traditionen."]}],"en":[{"heading":"Preparation and Serving Ritual","paragraphs":["Kava is made from the root of Piper methysticum, a pepper-family plant, and its name means 'bitter' in Tongan and Marquesan. In Samoa the drink is ʻava, prepared by the ʻaumaga group and served by the tautuaʻava in rank order, with the highest visiting chief served first.","In Tonga the informal faikava is a seated circle where the touʻa mixes and serves; the preparation itself is part of the ceremony, and the order of serving is a map of rank that everyone in the room can read."]},{"heading":"Social Meaning and Regional Differences","paragraphs":["Kava is mildly sedative and non-alcoholic, used to welcome guests, settle disputes and mark funerals, weddings and title installations. In Fiji, yaqona is drunk at any hour, and a visitor presents it as sevusevu to the chief.","Ceremony differs sharply between Tonga, Samoa, Fiji and Vanuatu, and casual kava drinking is not the same as a formal ceremony; generational differences also shape how it is practiced today. This variation shows how traditions adapt across time and place."]}]},"context":{"countries":["WS","TO","FJ","VU"],"region":"Polynesia and Fiji","continent":"oceania","languages":["sm","to","fj","bi"],"period":"contemporary"},"tags":["traditions","Polynesia and Fiji"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kava culture","de":"Kava culture","en":"Kava culture"},"url":"https://en.wikipedia.org/wiki/Kava_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Kava","de":"Kava","en":"Kava"},"url":"https://en.wikipedia.org/wiki/Kava","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في faikava تونغية، يخلط touʻa الكافا في الوعاء وتدور الأكواب بالترتيب؛ الزائر الذي يعبر الدائرة يُصحح بلطف.","de":"Bei einer tongaischen faikava mischt der touʻa die Kava in der Schale, und die Becher gehen der Reihe nach herum; ein Besucher, der den Kreis durchquert, wird leise korrigiert.","en":"At a Tongan faikava the touʻa mixes kava in the bowl and cups go round in order; a visitor who walks across the circle is quietly corrected."},"misunderstanding":{"ar":"يعتقد البعض أن الكافا مشروب كحولي أو مجرد عادة اجتماعية، لكنها في الواقع غير كحولية وتحتوي على قواعد صارمة للترتيب والاحترام.","de":"Manche halten Kava für ein alkoholisches Getränk oder nur für eine gesellige Gewohnheit, doch sie ist alkoholfrei und unterliegt strengen Regeln des Rangs und Respekts.","en":"Some assume kava is alcoholic or merely a social habit, but it is non-alcoholic and governed by strict rules of rank and respect."},"comparison":{"ar":"بينما تُشرب الكافا في فيجي في أي وقت وبشكل غير رسمي، فإنها في ساموا وتونغا تخضع لبروتوكول دقيق يعكس الرتب الاجتماعية.","de":"Während Kava in Fidschi jederzeit und informell getrunken wird, folgt sie in Samoa und Tonga einem präzisen Protokoll, das die sozialen Ränge widerspiegelt.","en":"While kava in Fiji is drunk at any hour and informally, in Samoa and Tonga it follows a precise protocol that reflects social ranks."}},{"id":"oce-025","version":2,"slug":"fahu-and-the-sacred-sister-tongan-rank-between-brothers-and-sisters","contentType":"note","category":"family-and-friendship","title":{"ar":"فاهو: مكانة الأخت في تونغا","de":"Fahu: der Rang der Schwester in Tonga","en":"Fahu: the sister's rank in Tonga"},"deck":{"ar":"في نظام القرابة التونغي تتفوّق الأخت على أخيها، ويحمل أطفالها مكانة خاصة يجب أن يحترمها.","de":"In der tongaischen Verwandtschaft steht eine Schwester über ihrem Bruder, und ihre Kinder genießen als fahu einen besonderen Status.","en":"In Tongan kinship a sister outranks her brother, and her children hold a privileged status he must honour."},"teaser":{"ar":"كيف يرتّب التونغيون المكانة بين الأخ والأخت، وكيف يعيش هذا الترتيب في الجنازات والأعراس وفي المهجر.","de":"Wie Tonganer Rang zwischen Bruder und Schwester ordnen und wie dieses Ordnungsprinzip bei Begräbnissen, Hochzeiten und in der Diaspora weiterlebt.","en":"How Tongans order rank between brother and sister, and how that order is lived at funerals, weddings and in diaspora families."},"readingMinutes":1,"sections":{"ar":[{"heading":"الأخت تسبق أخاها","paragraphs":["في القرابة التونغية تتفوّق الأخت على أخيها، وأطفالها هم فاهو يحملون مكانة مميّزة يجب على الأخ أن يكرّمها. وأعلى مثال تاريخي كان التاماهَا، الابنة الكبرى لأخت التوʻي تونغا، وكانت فاهو أي «فوق القانون» حتى بالنسبة للملك نفسه.","كان للتاماهَا أعلى مكانة اجتماعية في البلاد دون سلطة سياسية، ما يُظهر كيف فُصلت المكانة عن السلطة. ولا تزال الميهيكيتانغا، وهي أكبر العمة سناً، تحتل موقعاً متقدّماً في العائلة وتُكرَّم في الأعراس والجنازات وأعياد الميلاد."]},{"heading":"ترتيب يُستدعى كل يوم","paragraphs":["يتغيّر فاهو من عائلة إلى أخرى، وقد تبدّلت ممارسته مع الهجرة والمسيحية، لكن ترتيب أطفال الأخت ما زال يُستدعى في العائلات التونغية وفي مجتمعات المهجر. ويختلف هذا الأمر أيضاً بين الأجيال والمناطق، إذ يتمسّك بعض الشيوخ بالعرف بينما يعيد الشباب في المدن تفسيره."]}],"de":[{"heading":"Die Schwester steht vor dem Bruder","paragraphs":["In der tongaischen Verwandtschaft steht eine Schwester über ihrem Bruder, und ihre Kinder – seine fahu – haben einen bevorzugten Status, den er achten muss. Das höchste historische Beispiel war die tamahā, die älteste Tochter der Schwester des Tuʻi Tonga; sie war fahu, „über dem Gesetz“, sogar gegenüber dem König selbst.","Die tamahā hatte den höchsten sozialen Rang im Land, aber keine politische Macht – ein Beleg dafür, wie Rang und Autorität getrennt wurden. Auch die mehekitanga, die älteste Tante, nimmt eine hohe Stellung in der Familiengruppe ein und wird bei Hochzeiten, Begräbnissen und Geburtstagen geehrt."]},{"heading":"Eine Ordnung, die täglich aufgerufen wird","paragraphs":["Fahu unterscheidet sich von Familie zu Familie und hat sich mit Migration und Christentum verändert, doch die Rangordnung der Kinder der Schwester wird in tongaischen Familien und in der Diaspora weiterhin beschworen. Regional und zwischen den Generationen zeigt sich das unterschiedlich: Manche Ältere halten am Brauch fest, während jüngere Städter ihn neu auslegen."]}],"en":[{"heading":"The sister comes before her brother","paragraphs":["In Tongan kinship a sister outranks her brother, and her children — his fahu — hold a privileged status that he must honour. The highest historical example was the tamahā, the eldest daughter of the Tuʻi Tonga's sister; she was fahu, “above the law”, to the king himself.","The tamahā had the highest social status in the land but no political power, which shows how rank and authority were separated. The mehekitanga, the eldest aunt, also holds a senior position in the family group and is honoured at weddings, funerals and birthdays."]},{"heading":"An order invoked every day","paragraphs":["Fahu varies by family and has changed with migration and Christianity; it is not a fixed rule that all Tongans follow today. Regional and generational differences are visible too, as some elders keep closely to custom while younger people in towns reinterpret it."]}]},"context":{"countries":["TO"],"region":"Tonga","community":"Tongan","continent":"oceania","languages":["to","en"],"period":"contemporary"},"tags":["family-and-friendship","Tonga"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tamahā","de":"Tamahā","en":"Tamahā"},"url":"https://en.wikipedia.org/wiki/Tamah%C4%81","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Women in Tonga","de":"Women in Tonga","en":"Women in Tonga"},"url":"https://en.wikipedia.org/wiki/Women_in_Tonga","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في جنازة، يأتي جانب الفاهو بالحصائر الجميلة ويجلس أولاً؛ وتسلّم عائلة الفقيد البضائع احتراماً لا أجراً.","de":"Bei einem Begräbnis bringt die fahu-Seite feine Matten mit und sitzt vorn; die Familie der Verstorbenen übergibt Güter als Respekt, nicht als Bezahlung.","en":"At a funeral the fahu side brings fine mats and is seated first; the deceased's family hands over goods as respect rather than as payment."},"misunderstanding":{"ar":"يُفهم فاهو أحياناً كأنه دفع أو مبادلة، لكنه في أصله تعبير عن الاحترام والقرابة.","de":"Fahu wird manchmal wie eine Zahlung oder ein Tausch verstanden, ist aber zuerst ein Ausdruck von Respekt und Verwandtschaft.","en":"Fahu is sometimes read as a payment or an exchange, but it is first an expression of respect and kinship."},"comparison":{"ar":"يشبه هذا الترتيب نظماً أخرى في أوقيانوسيا حيث تعلو قرابة الأخت على قرابة الأخ، لكن تفاصيله تبقى تونغية.","de":"Ähnliche Ordnungen gibt es anderswo in Ozeanien, wo die Schwesterlinie über die Bruderlinie gestellt wird, doch die Einzelheiten bleiben tongaisch.","en":"Similar orderings appear elsewhere in Oceania where the sister line outranks the brother line, yet the details remain Tongan."}},{"id":"oce-026","version":2,"slug":"the-maneaba-where-a-kiribati-village-decides-things","contentType":"note","category":"cities-and-community","title":{"ar":"المانيابا: حيث تقرر القرية أمورها","de":"Die Maneaba: wo ein Dorf in Kiribati entscheidet","en":"The maneaba: where a Kiribati village decides"},"deck":{"ar":"بيت الاجتماع في كيريباتي ليس مبنى فحسب، بل خريطة جلوس تحدد من أنت ومن يحق له الكلام.","de":"Das Versammlungshaus in Kiribati ist kein neutraler Raum: Die Sitzordnung zeigt, wer man ist und wer sprechen darf.","en":"The meeting house at the centre of Kiribati life is not a neutral hall: its seating plan states who you are and who speaks."},"teaser":{"ar":"في قلب الحياة المجتمعية في كيريباتي يقف المانيابا: سقف عالٍ من أوراق الباندانوس، ومقاعد تحدد المكانة والانتماء.","de":"Im Zentrum des Gemeinschaftslebens von Kiribati steht die Maneaba: ein hohes Pandanusdach, getragen von Korallenpfeilern, und eine Sitzordnung, die Rang und Zugehörigkeit markiert.","en":"In Kiribati, the maneaba is a high pandanus roof on coral supports, and a seating map where named sections mark clan, family and rank."},"readingMinutes":1,"sections":{"ar":[{"heading":"بيت يجتمع فيه الجميع","paragraphs":["المانيابا هو بيت الاجتماع في مركز الحياة المجتمعية في كيريباتي: سقف عالٍ مغطى بأوراق الباندانوس، مبني على خشب جوز الهند ويدعمه دعائم من المرجان.","يشارك المجتمع كله في بنائه، ولكل جزء فيه وظيفة رمزية إلى جانب وظيفته العملية.","تختلف أشكال المانيابا وبروتوكولاتها بين الجزر، ولا تحكم كل قرية عبر الشيوخ بالطريقة نفسها اليوم.","أما تخطيطه فهو خريطة جلوس، بأقسام مسمّاة (بوتي) تنتمي إلى العشائر والعائلات، فمكان جلوسك يعلن من أنت."]},{"heading":"الجلوس والكلام والقرار","paragraphs":["داخل المانيابا تُسمع نزاعات الأرض؛ يجلس الشيوخ في أقسام عشائرهم، ويتكلمون بالترتيب، ويصلون إلى قرار دون تصويت.","كثير من المانيابا الحديثة صار من الخرسانة، لكن ترتيب الجلوس والبروتوكولات في داخلها ما زالت تحدد المرتبة والانتماء.","ويحمل مبنى البرلمان الوطني اسم مانيابا ني ماونغاتابو، ويظهر الشكل نفسه في توفالو باسم مانيابا أو أهيغا."]}],"de":[{"heading":"Ein Haus, das alle bauen","paragraphs":["Die Maneaba ist das Versammlungshaus im Zentrum des Gemeinschaftslebens in Kiribati: ein hohes, mit Pandanus gedecktes Dach aus Kokosholz, das auf Korallenstützen ruht.","Die ganze Gemeinschaft beteiligt sich am Bau, und jeder Teil hat neben seiner praktischen auch eine symbolische Funktion.","Formen und Protokolle der Maneaba unterscheiden sich von Insel zu Insel, und nicht jedes Dorf wird heute noch auf dieselbe Weise von Ältesten geleitet.","Ihr Grundriss ist eine Sitzordnung: benannte Abschnitte (boti) gehören Clans und Familien, sodass der Platz aussagt, wer man ist."]},{"heading":"Sitzen, sprechen, entscheiden","paragraphs":["In der Maneaba werden Landkonflikte angehört; Älteste sitzen in ihren Clan-Abschnitten, sprechen der Reihe nach und kommen ohne Abstimmung zu einer Entscheidung.","Moderne Maneaba sind oft aus Beton, doch Sitzordnung und Protokolle im Inneren markieren weiterhin Rang und Zugehörigkeit.","Das nationale Parlamentsgebäude heißt Maneaba ni Maungatabu, und dieselbe Bauform erscheint in Tuvalu als maneapa oder ahiga."]}],"en":[{"heading":"A house the whole village builds","paragraphs":["The maneaba is the meeting house at the centre of Kiribati community life: a high, pandanus-thatched roof of coconut wood resting on coral supports.","The whole community takes part in building it, and every part has a symbolic as well as a practical function.","Maneaba forms and protocols differ between islands, and not every village still governs through elders in the same way.","Its layout is a seating map, with named sections (boti) belonging to clans and families, so where you sit states who you are."]},{"heading":"Sitting, speaking, deciding","paragraphs":["A land dispute is heard in the maneaba; elders sit in their clan sections, speak in turn, and reach a decision without a vote.","Modern maneaba are often concrete, but the seating order and the protocols inside them still mark rank and belonging.","The national parliament building is called the Maneaba ni Maungatabu, and the same building form appears in Tuvalu as the maneapa or ahiga."]}]},"context":{"countries":["KI"],"region":"Kiribati","community":"I-Kiribati","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["cities-and-community","Kiribati"],"sources":[{"organization":"Wikipedia","title":{"ar":"Maneaba","de":"Maneaba","en":"Maneaba"},"url":"https://en.wikipedia.org/wiki/Maneaba","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Kiribati","de":"Culture of Kiribati","en":"Culture of Kiribati"},"url":"https://en.wikipedia.org/wiki/Culture_of_Kiribati","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يُستمع إلى نزاع على أرض في المانيابا؛ يجلس الشيوخ في أقسام عشائرهم، ويتكلمون بالترتيب، ويصلون إلى قرار دون تصويت.","de":"Ein Landkonflikt wird in der Maneaba angehört; Älteste sitzen in ihren Clan-Abschnitten, sprechen der Reihe nach und kommen ohne Abstimmung zu einer Entscheidung.","en":"A land dispute is heard in the maneaba; elders sit in their clan sections, speak in turn, and reach a decision without a vote."},"misunderstanding":{"ar":"يُظن أحياناً أن المانيابا مجرد قاعة اجتماعات محايدة، لكن ترتيب الجلوس فيه يحدد المكانة والانتماء.","de":"Manchmal gilt die Maneaba als neutraler Versammlungsraum, doch ihre Sitzordnung bestimmt Rang und Zugehörigkeit.","en":"It is sometimes assumed the maneaba is a neutral meeting hall, yet its seating order itself marks rank and belonging."},"comparison":{"ar":"كما في كثير من المجتمعات، لا يُفصل المكان عن الصوت: من يجلس في الصف الأول يتكلم أولاً.","de":"Wie in vielen Gesellschaften ist der Platz nicht vom Wort zu trennen: Wer vorn sitzt, spricht zuerst.","en":"As in many societies, place is not separate from voice: whoever sits at the front speaks first."}},{"id":"oce-027","version":2,"slug":"kastom-custom-as-law-in-vanuatu","contentType":"note","category":"social-behaviour","title":{"ar":"الكاستوم: عرف يصير قانونًا في فانواتو","de":"Kastom: Gewohnheit als Gesetz in Vanuatu","en":"Kastom: custom as law in Vanuatu"},"deck":{"ar":"في أرخبيل يمتد على أكثر من ثمانين جزيرة وأكثر من مئة لغة، يحكم العرفُ الحياةَ اليومية إلى جانب القانون المكتوب.","de":"Auf einem Archipel mit über achtzig Inseln und mehr als hundert Sprachen regelt Kastom den Alltag neben dem geschriebenen Recht.","en":"Across more than eighty islands and over a hundred languages, kastom shapes daily life alongside written law."},"teaser":{"ar":"الكاستوم كلمة بسلاما تعني العرف، لكنها في فانواتو تشمل القانون العرفي وحيازة الأرض والطقوس والالتزام الاجتماعي في آن واحد.","de":"Kastom ist ein Bislama-Wort für Gewohnheit, doch in Vanuatu bedeutet es zugleich Gewohnheitsrecht, Landbesitz, Ritual und soziale Verpflichtung.","en":"Kastom is a Bislama word for custom, but in Vanuatu it means customary law, land tenure, ritual and social obligation at once."},"readingMinutes":1,"sections":{"ar":[{"heading":"عرف واحد بأشكال كثيرة","paragraphs":["الكاستوم كلمة من لغة بسلاما تعني العرف، وهي في فانواتو قانون عرفي وحيازة أرض وطقس والتزام اجتماعي في وقت واحد. صارت فكرة وطنية عند الاستقلال عام 1980، حين ساعدت على جمع بلد فيه أكثر من مئة لغة وأكثر من ثمانين جزيرة.","الكاستوم غير مكتوب، وينتقل بالتعليم والحكاية والاحتفال. لا توجد مدونة واحدة، لأن لكل جزيرة عرفها الخاص، ويختلف الأمر من جيل إلى جيل ومن منطقة إلى أخرى داخل البلد نفسه."]},{"heading":"الزعماء والمحاكم والحياة اليومية","paragraphs":["يطبّق الزعماء الكاستوم في محاكم القرى وفي نزاعات الأرض، وتعترف الدولة بمجالس الزعماء إلى جانب المحاكم الوطنية. لذلك يبدأ الزائر عادةً بهديّة عرفية صغيرة قبل الحديث في الأرض، ويسمع الزعيم الأمر مع الشيوخ.","يدرّب المركز الثقافي في فانواتو باحثين من السكان الأصليين لتسجيل الكاستوم في مجتمعاتهم، لأن الغرباء لا يستطيعون تعريفه. والكاستوم متنوّع ومتغيّر، وأهل الجزر يختلفون فيما يفرضه، وليس مدونة وطنية واحدة."]}],"de":[{"heading":"Ein Begriff, viele Formen","paragraphs":["Kastom ist ein Bislama-Wort für Gewohnheit und bedeutet in Vanuatu gleichzeitig Gewohnheitsrecht, Landbesitz, Ritual und soziale Verpflichtung. Zur nationalen Idee wurde es 1980 bei der Unabhängigkeit, als es half, ein Land mit über hundert Sprachen und mehr als achtzig Inseln zusammenzuhalten.","Kastom ist ungeschrieben und wird durch Lehren, Erzählen und Zeremonien weitergegeben. Es gibt keinen einheitlichen Kodex, denn jede Insel hat ihr eigenes Kastom, und je nach Region und Generation wird es unterschiedlich verstanden und gelebt."]},{"heading":"Häuptlinge, Gerichte und Alltag","paragraphs":["Häuptlinge wenden Kastom in Dorfgerichten und bei Landstreitigkeiten an, und der Staat erkennt Häuptlingsräte neben den nationalen Gerichten an. Besucher bringen daher oft ein kleines traditionelles Geschenk mit, bevor über Land gesprochen wird, und der Häuptling hört die Sache mit den Ältesten an.","Das Kulturzentrum Vanuatus bildet ni-Vanuatu-Feldmitarbeiter aus, die Kastom in ihren eigenen Gemeinschaften dokumentieren, weil Außenstehende es nicht definieren können. Kastom ist vielfältig und im Wandel, und Inselgemeinschaften sind uneinig darüber, was es verlangt; es ist kein einheitlicher nationaler Kodex."]}],"en":[{"heading":"One word, many forms","paragraphs":["Kastom is a Bislama word for custom, and in Vanuatu it means customary law, land tenure, ritual and social obligation at once. It became a national idea at independence in 1980, when it helped hold together a country of more than 100 languages and over 80 islands.","Kastom is unwritten and passed on through teaching, story and ceremony. There is no single code, because each island has its own, and understandings shift between regions and generations within the same country."]},{"heading":"Chiefs, courts and everyday life","paragraphs":["Chiefs apply kastom in village courts and land disputes, and the state recognises chiefly councils alongside the national courts. A visitor to a village often brings a small customary gift before discussing land, and the chief hears the matter with the elders under kastom.","Vanuatu's cultural centre trains ni-Vanuatu fieldworkers to record kastom in their own communities, because outsiders cannot define it. Kastom is diverse and changing, and island communities disagree about what it requires; it is not a single national code."]}]},"context":{"countries":["VU"],"region":"Vanuatu","community":"ni-Vanuatu","continent":"oceania","languages":["bi","en","fr"],"period":"contemporary"},"tags":["social-behaviour","Vanuatu"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kastom","de":"Kastom","en":"Kastom"},"url":"https://en.wikipedia.org/wiki/Kastom","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Vanuatu","de":"Culture of Vanuatu","en":"Culture of Vanuatu"},"url":"https://en.wikipedia.org/wiki/Culture_of_Vanuatu","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"زائر لقرية في فانواتو يقدّم هدية عرفية صغيرة قبل مناقشة الأرض، فيسمع الزعيم الأمر مع الشيوخ وفق الكاستوم.","de":"Ein Besucher eines Dorfes in Vanuatu bringt ein kleines traditionelles Geschenk mit, bevor über Land gesprochen wird, und der Häuptling hört die Sache mit den Ältesten nach Kastom an.","en":"A visitor to a Vanuatu village brings a small customary gift before discussing land, and the chief hears the matter with the elders under kastom."},"misunderstanding":{"ar":"خطأ شائع أن الكاستوم مدونة واحدة موحّدة لكل البلاد، والحقيقة أنه متعدد ومتغيّر ويختلف من جزيرة إلى أخرى.","de":"Häufig wird angenommen, Kastom sei ein einheitlicher nationaler Kodex; tatsächlich ist es vielfältig, wandelbar und von Insel zu Insel verschieden.","en":"A common mistake is to treat kastom as one unified national code; in fact it is plural, changing and different from island to island."},"comparison":{"ar":"يشبه الكاستوم القانون العرفي في مجتمعات أخرى، لكنه في فانواتو مرتبط بالأرض والطقوس معًا، وتختلف صيغه من جزيرة إلى أخرى.","de":"Kastom ähnelt Gewohnheitsrecht in anderen Gesellschaften, ist in Vanuatu aber eng mit Land und Ritual verbunden, und seine Formen unterscheiden sich von Insel zu Insel.","en":"Kastom resembles customary law elsewhere, but in Vanuatu it is bound up with land and ritual together, and its forms vary from island to island."}},{"id":"oce-028","version":2,"slug":"land-diving-on-pentecost-a-leap-tied-to-the-yam-harvest","contentType":"scene","category":"traditions","title":{"ar":"القفز من الأبراج في بينتكوست","de":"Landtauchen auf Pentecost","en":"Land Diving on Pentecost"},"deck":{"ar":"رجال يخاطرون بحياتهم في طقس مرتبط بحصاد اليام، حيث تقاس الحبال لتلامس أكتافهم الأرض.","de":"Männer und Jungen springen von Holztürmen, mit Lianen an den Knöcheln, um eine gute Yamsernte zu sichern.","en":"Men and boys leap from wooden towers with vines tied to their ankles, a ritual to ensure a good yam harvest."},"teaser":{"ar":"في جزيرة بينتكوست، يبني الرجال أبراجًا خشبية ويقفزون منها بحبال ليفية مربوطة بأقدامهم، في طقس يهدف إلى ضمان حصاد وفير.","de":"Auf der Insel Pentecost bauen Männer Holztürme und springen mit Lianen an den Fußknöcheln hinab – ein Ritual, das die Yamsernte segnen soll.","en":"On Pentecost Island, men build wooden towers and jump with lianas around their ankles, a ritual tied to the annual yam harvest."},"readingMinutes":1,"sections":{"ar":[{"heading":"الطقس والحصاد","paragraphs":["في جنوب جزيرة بينتكوست، يقفز الرجال والأولاد من أبراج خشبية يبلغ ارتفاعها 20 إلى 30 مترًا، وحبال ليفية مربوطة حول كواحلهم. يرتبط هذا الطقس بحصاد اليام السنوي في أبريل أو مايو أو يونيو، ويُعتقد أن القفزة الجيدة تساعد في جلب حصاد وفير.","تبني المجتمع الأبراج من الأخشاب والكروم، ويتم قياس طول الحبل بحيث تلامس أكتاف القافز الأرض. قبل استخدام البرج، يعتزل الرجال وتبتعد النساء، وتأتي القفزات الأولى من المنصات السفلية."]},{"heading":"المشاركة والتغيير","paragraphs":["يقدم القافزون خطابات قصيرة ويغنون قبل القفز. يجذب الطقس الآن السياح الذين تدعم رسومهم القرى. يختلف توقيت الطقس وتنظيمه بين القرى، كما تختلف ممارسته بين الأجيال."]}],"de":[{"heading":"Das Ritual und die Ernte","paragraphs":["Im Süden von Pentecost Island springen Männer und Jungen von Holztürmen, die etwa 20 bis 30 Meter hoch sind, mit zwei Lianen um die Knöchel. Das Ritual ist mit der jährlichen Yamsernte im April, Mai oder Juni verbunden, und ein guter Sprung soll eine reiche Ernte bringen.","Die Gemeinde baut den Turm aus Holz und Ranken, und die Länge der Liane wird so bemessen, dass die Schultern des Springers den Boden berühren. Vor der Nutzung des Turms ziehen sich die Männer zurück, die Frauen bleiben fern, und die ersten Sprünge erfolgen von den unteren Plattformen."]},{"heading":"Teilnahme und Wandel","paragraphs":["Die Springer halten kurze Reden und singen vor dem Sprung. Das Ritual zieht heute Touristen an, deren Gebühren die Dörfer unterstützen. Der Zeitpunkt und die Inszenierung des Rituals variieren je nach Dorf und Generation."]}],"en":[{"heading":"The Ritual and the Harvest","paragraphs":["On southern Pentecost Island, men and boys jump from wooden towers about 20 to 30 metres high with two lianas tied around their ankles. The ritual is tied to the annual yam harvest in April, May or June, and a good dive is believed to help bring a bountiful harvest.","The tower is built from timber and vines by the community, and the vine length is measured so the jumper's shoulders brush the ground. Before the tower is used the men seclude themselves and women stay away, and the first jumps come from the lower platforms."]},{"heading":"Participation and Change","paragraphs":["Jumpers give short speeches and sing before leaping. The ritual now attracts tourists whose fees support the villages. The timing and staging vary between villages and generations."]}]},"context":{"countries":["VU"],"region":"Pentecost Island, Vanuatu","community":"Sa people, southern Pentecost","continent":"oceania","languages":["bi","en"],"period":"contemporary"},"tags":["traditions","Pentecost Island, Vanuatu"],"sources":[{"organization":"Wikipedia","title":{"ar":"Land diving","de":"Land diving","en":"Land diving"},"url":"https://en.wikipedia.org/wiki/Land_diving","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Vanuatu","de":"Culture of Vanuatu","en":"Culture of Vanuatu"},"url":"https://en.wikipedia.org/wiki/Culture_of_Vanuatu","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في أبريل، يبني الرجال برجًا من الأخشاب والكروم؛ يقفز الأصغر سنًا أولاً، ويغني الجمهور بينما تلامس أكتاف أفضل غواص الأرض.","de":"Im April bauen die Männer einen Turm aus Holz und Ranken; die Jüngsten springen zuerst, und die Menge singt, während die Schultern des besten Tauchers die Erde berühren.","en":"In April the men build a tower of timber and vines; the youngest jump first, and the crowd sings as the best diver's shoulders brush the earth."},"misunderstanding":{"ar":"قد يعتقد البعض أن هذا الطقس مجرد عرض سياحي، لكنه في الأساس ممارسة تقليدية مرتبطة بالزراعة والحصاد.","de":"Manche halten das Ritual für eine reine Touristenattraktion, doch es ist ursprünglich eine landwirtschaftliche Tradition.","en":"Some think the ritual is just a tourist show, but it is primarily a traditional agricultural practice."},"comparison":{"ar":"يشبه هذا الطقس طقوس الخصوبة الأخرى في المحيط الهادئ، لكنه يتميز بارتفاع الأبراج ودقة قياس الحبال.","de":"Ähnliche Fruchtbarkeitsrituale gibt es im Pazifik, doch die Höhe der Türme und die präzise Lianenlänge sind einzigartig.","en":"Similar fertility rituals exist across the Pacific, but the height of the towers and the precise vine length are unique."}},{"id":"oce-029","version":2,"slug":"wantok-the-obligation-that-comes-with-a-shared-language","contentType":"note","category":"communication","title":{"ar":"وانتوك: التزام اللغة المشتركة","de":"Wantok: die Pflicht aus gemeinsamer Sprache","en":"Wantok: the obligation that comes with a shared language"},"deck":{"ar":"في بابوا غينيا الجديدة وجزر سليمان، تعني كلمة وانتوك 'حديث واحد': من يتحدث لغتك، ومن ثمَّ هو قريب لك، ولك عليه حق.","de":"In Papua-Neuguinea und den Salomonen bedeutet Wantok 'ein Gespräch': jemand, der deine Sprache spricht, und damit dein Verwandter und deine Verpflichtung.","en":"In Papua New Guinea and Solomon Islands, wantok means 'one talk': someone who speaks your language, and by extension your kin and your obligation."},"teaser":{"ar":"شبكات وانتوك توفر المسكن والوظائف، لكنها تثير جدلاً حول الفساد وسوء استخدام المال العام.","de":"Wantok-Netzwerke bieten Unterkunft und Jobs, stehen aber wegen Vetternwirtschaft und Korruption in der Kritik.","en":"Wantok networks provide housing and jobs, but they also spark debate about corruption and the misuse of public money."},"readingMinutes":1,"sections":{"ar":[{"heading":"شبكة الأمان اليومية","paragraphs":["في بلد يتجاوز عدد لغاته 800 لغة، تعمل شبكات وانتوك كرعاية اجتماعية يومية: توفير السكن والوظائف ورسوم المدارس للقادمين الجدد إلى المدينة.","يستند هذا النظام إلى مبدأ المعاملة بالمثل، حيث يُتوقع من المستفيد لاحقاً أن يرد الجميل لأفراد شبكته."]},{"heading":"الوجه الآخر للالتزام","paragraphs":["لكن الالتزام نفسه يمثل مشكلة سياسية: يصف النقاد 'الوانتوكية' بأنها عادة توجيه المال العام والوظائف إلى الأقارب وأبناء اللغة.","غالباً ما يتحول الجدل حول الفساد في بابوا غينيا الجديدة إلى نظام وانتوك، لأن الولاء المتبادل متوقع، ورفضه قد يكون مكلفاً اجتماعياً. كما تُستخدم الكلمة في بيجين جزر سليمان حيث تشكل الشبكات الحياة الحضرية والسياسة. وتختلف هذه الالتزامات بين الأجيال، إذ يجادل شباب المدن فيها أكثر من كبار السن."]}],"de":[{"heading":"Das tägliche Sozialsystem","paragraphs":["In einem Land mit über 800 Sprachen fungieren Wantok-Netzwerke als alltägliche Fürsorge: Sie vermitteln Wohnungen, Jobs und Schulgebühren für Neuankömmlinge in der Stadt.","Dieses System basiert auf Gegenseitigkeit: Wer profitiert, wird später erwartet, seinem Netzwerk zu helfen."]},{"heading":"Die Kehrseite der Verpflichtung","paragraphs":["Doch dieselbe Verpflichtung ist ein politisches Problem: Kritiker nennen 'Wantokismus' die Praxis, öffentliche Gelder und Stellen an Verwandte und Sprachgenossen zu lenken.","Die Korruptionsdebatte in Papua-Neuguinea dreht sich oft um das Wantok-System, weil reziproke Loyalität erwartet wird und ihre Verweigerung sozial teuer sein kann. Der Begriff wird auch in Solomon Islands Pijin verwendet, wo Wantok-Netzwerke das Stadtleben und die Politik prägen. Junge Stadtbewohner sehen diese Pflichten zunehmend kritischer als ältere Generationen."]}],"en":[{"heading":"The everyday safety net","paragraphs":["In a country with more than 800 languages, wantok networks work as everyday welfare, finding housing, jobs and school fees for new arrivals in town.","The system runs on reciprocity: those who receive help are later expected to give it back to their network."]},{"heading":"The political cost of loyalty","paragraphs":["But the same obligation is a political problem: critics call 'wantokism' the habit of directing public money and jobs to relatives and language-mates.","Papua New Guinea's corruption debate often turns on the wantok system, because reciprocal loyalty is expected and refusing it can be socially costly. The term is used in Solomon Islands Pijin too, where wantok networks shape urban life and politics. Younger urban Papua New Guineans contest these obligations more than older generations do."]}]},"context":{"countries":["PG","SB"],"region":"Papua New Guinea and Solomon Islands","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["communication","Papua New Guinea and Solomon Islands"],"sources":[{"organization":"Wikipedia","title":{"ar":"Papua New Guinea","de":"Papua New Guinea","en":"Papua New Guinea"},"url":"https://en.wikipedia.org/wiki/Papua_New_Guinea","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Papua New Guinea","de":"Culture of Papua New Guinea","en":"Culture of Papua New Guinea"},"url":"https://en.wikipedia.org/wiki/Culture_of_Papua_New_Guinea","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"وافد جديد إلى بورت مورسبي ينام على أرضية أصدقاء وانتوك حتى يجد عملاً؛ لاحقاً يُتوقع منه دفع رسوم مدرسية لابن عمه.","de":"Ein Neuankömmling in Port Moresby schläft auf dem Boden seiner Wantoks, bis er Arbeit findet; später wird von ihm erwartet, die Schulgebühren für einen Cousin zu zahlen.","en":"A new arrival in Port Moresby sleeps on his wantoks' floor until he finds work; later he is expected to pay school fees for a cousin."},"misunderstanding":{"ar":"الوانتوكية ليست مصطلحاً محايداً، بل نقدٌ للاستخدام السياسي للشبكات.","de":"Wantokismus ist kein neutraler Begriff, sondern eine Kritik an der politischen Nutzung der Netzwerke.","en":"Wantokism is not a neutral term; it is a criticism of how networks are used politically."},"comparison":{"ar":"في المجتمعات الغربية، تُفصل المساعدة الأسرية عن الواجب المدني، بينما تتداخل هنا.","de":"In westlichen Gesellschaften ist familiäre Hilfe oft vom bürgerlichen Pflichtgefühl getrennt, hier vermischen sie sich.","en":"In Western societies, family help is often kept separate from civic duty; here they overlap."},"expression":{"original":"Wantok","language":"Tok Pisin","gloss":{"ar":"'حديث واحد' — من يتحدث لغتي، وبالتالي حليف يُستحق المساعدة.","de":"'Ein Gespräch' — jemand, der meine Sprache spricht und daher ein Verbündeter, dem Hilfe geschuldet wird.","en":"'One talk' — someone who speaks my language, and therefore an ally owed help."},"usage":{"ar":"تُستخدم للتحية أو لتحديد هوية الشخص كقريب أو صديق ملزم بالمساعدة.","de":"Wird als Begrüßung oder zur Identifizierung einer Person als Verwandter oder verpflichteter Freund verwendet.","en":"Used as a greeting or to identify someone as kin or a friend entitled to assistance."},"transliteration":"WAN-tok"}},{"id":"oce-030","version":2,"slug":"hula-choreography-that-carries-the-words-of-a-song","contentType":"note","category":"music-and-dance","title":{"ar":"الهولا: رقصة تحمل كلمات الأغنية","de":"Hula: Choreografie, die Liedworte trägt","en":"Hula: choreography that carries the words of a song"},"deck":{"ar":"في هاواي، ليست الهولا حركة جسد فقط، بل طريقة لرواية نص الميلي بالأيدي والوركين والقدمين.","de":"Auf Hawaiʻi erzählt Hula mit Händen, Hüften und Füßen den Text eines Mele, nicht nur eine Bewegung.","en":"In Hawaiʻi, hula is not just movement; hands, hips and feet dramatise the text of a mele, line by line."},"teaser":{"ar":"رقصة هاوايية قديمة تروي كلمات الأغاني بحركات الجسد، وتُتعلَّم في مدارس لها تقاليدها الصارمة.","de":"Ein hawaiianischer Tanz, der Liedtexte mit dem Körper erzählt und in Schulen mit strengen Regeln und eigenen Ritualen gelernt wird.","en":"A Hawaiian dance that tells a song's words through the body, learned in schools with their own protocols and entrance chants."},"readingMinutes":1,"sections":{"ar":[{"heading":"الجسد يروي النص","paragraphs":["الهولا شكل من الرقص الهاوايي يُمثّل كلمات الميلي، أي الأغنية، بالأيدي والوركين والقدمين، فكل حركة تحمل معنى لغوياً.","الشكل الأقدم هو هولا كاهيكو، يُؤدّى مع الإنشاد، بينما نشأ هولا أوانا لاحقاً تحت تأثير غربي مع الأغنية والآلات.","يتدرّب الراقصون في هالاو تحت إشراف كومو هولا، وطلب الإذن بالدخول إلى المدرسة نفسه إنشاد يُؤدّى عند المدخل."]},{"heading":"من المنع إلى المهرجان","paragraphs":["دفع ضغط المبشرين الهولا إلى الخفاء في القرن التاسع عشر، ثم ساعدت رعاية الملك كالاكاوا على إحيائها، ويُكرّمها مهرجان ميري مونارك منذ 1971.","يقام المهرجان في هيلو على مدى أسبوع بعد عيد الفصح، وتتنافس فيه فرق من البر الرئيسي وخارجه في كاهيكو وأوانا.","تختلف الأساليب والتقاليد من هالاو إلى آخر، ولا يرقص كل الهاواييين، كما تختلف عروض السياحة عن رقص الطقس والمسابقة، مع فروق واضحة بين الأجيال والمناطق."]}],"de":[{"heading":"Der Körper erzählt den Text","paragraphs":["Hula ist eine hawaiianische Tanzform, die die Worte eines Mele, eines Liedes, mit Händen, Hüften und Füßen dramatisiert; jede Bewegung trägt Bedeutung.","Hula kahiko ist die ältere, von Gesang begleitete Form, während Hula ʻauana unter westlichem Einfluss mit Lied und Instrumenten entstand.","Trainiert wird in einer Hālau unter einer Kumu Hula, und die Bitte um Aufnahme in die Schule ist selbst ein Gesang am Eingang."]},{"heading":"Vom Verbot zum Festival","paragraphs":["Missionarischer Druck trieb den Hula im 19. Jahrhundert in den Untergrund; die Förderung König Kalākauas half bei der Wiederbelebung, und das Merrie Monarch Festival seit 1971 ehrt ihn.","Das Festival findet eine Woche nach Ostern in Hilo statt, Hālau vom Festland und aus dem Ausland treten in Kahiko und ʻauana an.","Stile und Protokolle unterscheiden sich je nach Hālau, nicht alle Hawaiianer tanzen, und Tourismusauftritte sind nicht dasselbe wie ritueller oder Wettbewerbs-Hula, wobei regionale und generationelle Unterschiede deutlich sind."]}],"en":[{"heading":"The body tells the text","paragraphs":["Hula is a Hawaiian dance form that dramatises the words of a mele, or song, with hands, hips and feet carrying the text, so each gesture means something.","Hula kahiko is the older, chant-accompanied form, while hula ʻauana developed under Western influence with song and instruments.","Training happens in a hālau under a kumu hula, and asking permission to enter the school is itself a chant performed at the entrance."]},{"heading":"From suppression to festival","paragraphs":["Missionary pressure drove hula underground in the nineteenth century; King Kalākaua's patronage helped restore it, and the Merrie Monarch Festival, begun in 1971, honours him.","Merrie Monarch is a week-long festival in Hilo held after Easter, with hālau from the mainland and abroad competing in kahiko and ʻauana.","Styles and protocols vary by hālau, not all Hawaiians dance, and tourism performances are not the same as ritual or competition hula, with clear regional and generational differences."]}]},"context":{"countries":["US"],"region":"Hawaiʻi","community":"Native Hawaiians","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["music-and-dance","Hawaiʻi"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hula","de":"Hula","en":"Hula"},"url":"https://en.wikipedia.org/wiki/Hula","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Merrie Monarch Festival","de":"Merrie Monarch Festival","en":"Merrie Monarch Festival"},"url":"https://en.wikipedia.org/wiki/Merrie_Monarch_Festival","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تتدرب فرقة هالاو أشهراً من أجل ميري مونارك، ويصحح الكومو شكل اليد لأن تغييره يغيّر معنى الكلمة في الميلي.","de":"Eine Hālau probt monatelang für Merrie Monarch; die Kumu korrigiert eine Handform, weil sie die Bedeutung des Wortes im Mele verändert.","en":"A hālau rehearses for Merrie Monarch for months; the kumu corrects a hand shape because it changes the meaning of the word in the mele."},"misunderstanding":{"ar":"ليس كل هاوايي راقص هولا، وعروض الفنادق السياحية ليست هي الرقص الطقسي أو التنافسي.","de":"Nicht jeder Hawaiianer tanzt Hula, und Hotelvorführungen sind nicht mit rituellem oder Wettbewerbs-Hula gleichzusetzen.","en":"Not every Hawaiian dances hula, and hotel shows are not the same as ritual or competition hula."},"comparison":{"ar":"كما تحمل الكلمة معناها في الشعر، تحمل اليد شكلها في الهولا، فتغيّر بسيط يبدّل الرسالة.","de":"Wie ein Wort im Gedicht seinen Klang trägt, trägt die Hand im Hula ihre Form; eine kleine Änderung verschiebt die Botschaft.","en":"As a word carries its sound in a poem, a hand carries its shape in hula; a small change shifts the message."}},{"id":"oce-031","version":2,"slug":"punana-leo-the-preschools-opened-illegally-to-save-hawaiian","contentType":"note","category":"work-and-education","title":{"ar":"بونانا ليو: روضات أُسست سراً لإنقاذ الهاوائية","de":"Pūnana Leo: illegal eröffnete Vorschulen retten Hawaiianisch","en":"Pūnana Leo: preschools opened illegally to save Hawaiian"},"deck":{"ar":"في عام 1984، افتُتحت أول روضة هاوايية متوسطة اللغة بشكل غير قانوني، لتمنح الأطفال لغة أجدادهم في عالم كان يمنعها.","de":"1984 öffnete die erste hawaiianischsprachige Vorschule illegal, um Kindern die Sprache ihrer Vorfahren zurückzugeben – in einer Welt, die sie verboten hatte.","en":"In 1984, the first Hawaiian-medium preschool opened illegally, giving children their ancestors' language in a world that had banned it."},"teaser":{"ar":"روضات 'عش اللغة' الهاوايية تحدت القانون لتعيد لغة كادت تندثر، وتستمر اليوم في خمس جزر.","de":"Die 'Sprachnester' trotzten dem Gesetz und hauchten dem Hawaiianischen neues Leben ein – heute gibt es sie auf fünf Inseln.","en":"The 'language nest' preschools defied the law to revive a nearly lost language—and today they thrive on five islands."},"readingMinutes":1,"sections":{"ar":[{"heading":"عش اللغة: ولادة فكرة","paragraphs":["تعني 'بونانا ليو' 'عش اللغة': روضات حيث يقضي الأطفال يومهم بالهاوايية بدل الإنجليزية. افتُتحت الأولى عام 1984 في كيكاه، كاواي، بشكل غير قانوني لأن الهاوايية كانت محظورة فعلياً في المدارس.","استلهم النموذج من مدارس هاوايية من القرن التاسع عشر ومن حركة 'كوهانغا ريو' في نيوزيلندا. تأسست 'أها بونانا ليو' عام 1983، وكان يُتوقع من الآباء تعلم الهاوايية أيضاً لتستمر في المنزل."]},{"heading":"تحدي القانون واستمرار النهضة","paragraphs":["حظر قانون الإنجليزية فقط عام 1896 استخدام الهاوايية كلغة تعليم، ولم يُسمح بها مجدداً حتى 1987، أي فجوة 91 عاماً. بحلول 2022 كان هناك إحدى عشرة روضة في خمس جزر تغذي برامج ابتدائية وثانوية بالهاوايية.","يختلف الوضع حسب المنطقة والجيل: فبعض العائلات في المناطق الحضرية تشارك بحماس، بينما تواجه عائلات أخرى صعوبة في الوصول. تبقى المدارس الانغماسية محدودة المقاعد والمعلمين الطلقاء، والنهضة هشة."]}],"de":[{"heading":"Das Sprachnest: Geburt einer Idee","paragraphs":["Pūnana Leo bedeutet 'Sprachnest': Vorschulen, in denen Kinder den Tag auf Hawaiianisch statt Englisch verbringen. Die erste öffnete 1984 in Kekaha, Kauaʻi, zunächst illegal, weil Hawaiianisch als Schulsprache noch effektiv verboten war.","Das Modell orientierte sich an hawaiianischen Schulen des 19. Jahrhunderts und an der Kōhanga-Reo-Bewegung in Neuseeland. ʻAha Pūnana Leo wurde 1983 gegründet; Eltern sollten ebenfalls Hawaiianisch lernen, damit die Sprache zu Hause weiterlebt."]},{"heading":"Gesetzesbruch und fragile Wiederbelebung","paragraphs":["Ein English-only-Gesetz von 1896 verbot Hawaiianisch als Unterrichtssprache; erst 1987 wurde es wieder erlaubt – eine Lücke von 91 Jahren. 2022 gab es elf Pūnana Leo auf fünf Inseln, die hawaiianischsprachige Grund- und Sekundarschulprogramme speisen.","Je nach Region und Generation ist die Lage unterschiedlich: Manche städtische Familien engagieren sich stark, andere haben keinen Zugang. Immersionsschulen sind durch Plätze und fließend sprechende Lehrkräfte begrenzt; die Revitalisierung bleibt fragil."]}],"en":[{"heading":"The language nest: birth of an idea","paragraphs":["Pūnana Leo means 'language nest': Hawaiian-medium preschools where children spend the day in Hawaiian rather than English. The first opened in 1984 in Kekaha, Kauaʻi, initially illegally, because Hawaiian was still effectively banned as a school language.","The model drew on nineteenth-century Hawaiian-language schools and on the kōhanga reo movement in New Zealand. ʻAha Pūnana Leo had been founded in 1983, and parents were expected to learn Hawaiian as well, so the language would continue at home."]},{"heading":"Breaking the law, sustaining the revival","paragraphs":["Hawaiian was banned as a medium of instruction by an 1896 English-only law and not allowed back until 1987, a gap of 91 years. As of 2022 there were eleven Pūnana Leo preschools on five islands, feeding Hawaiian-medium primary and secondary programmes.","The situation varies by region and generation: some urban families are deeply involved, while others lack access. Immersion schools are limited by places and fluent teachers, and not every Hawaiian family has access; revitalisation is still fragile."]}]},"context":{"countries":["US"],"region":"Hawaiʻi","community":"Native Hawaiians","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["work-and-education","Hawaiʻi"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pūnana Leo","de":"Pūnana Leo","en":"Pūnana Leo"},"url":"https://en.wikipedia.org/wiki/P%C5%ABnana_Leo","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Hawaiian language","de":"Hawaiian language","en":"Hawaiian language"},"url":"https://en.wikipedia.org/wiki/Hawaiian_language","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في روضة بونانا ليو، تطلب طفلة في الثالثة الماء بالهاوايية؛ ويحضر والدها دروساً مسائية لتستمر اللغة في المنزل.","de":"In einem Pūnana Leo bittet ein dreijähriges Mädchen auf Hawaiianisch um Wasser; ihr Vater besucht Abendkurse, damit die Sprache zu Hause weitergeht.","en":"At a Pūnana Leo a three-year-old asks for water in Hawaiian; her father attends evening classes so the language continues at home."},"misunderstanding":{"ar":"يعتقد البعض أن الروضات مجرد نوادٍ ثقافية، لكنها مدارس انغماس كامل حيث التعلم بالهاوايية طوال اليوم.","de":"Manche halten die Vorschulen für reine Kulturklubs, doch es sind vollständige Immersionsschulen, in denen den ganzen Tag Hawaiianisch gesprochen wird.","en":"Some think the preschools are just cultural clubs, but they are full immersion schools where learning happens in Hawaiian all day."},"comparison":{"ar":"تشبه تجربة بونانا ليو حركة كوهانغا ريو في نيوزيلندا، حيث أنقذ الماوريون لغتهم عبر روضات مماثلة.","de":"Pūnana Leo ähnelt der Kōhanga-Reo-Bewegung in Neuseeland, wo Māori ihre Sprache durch vergleichbare Vorschulen retteten.","en":"Pūnana Leo mirrors the kōhanga reo movement in New Zealand, where Māori revived their language through similar preschools."}},{"id":"oce-032","version":2,"slug":"bikini-atoll-exile-trust-fund-and-the-nuclear-debt","contentType":"note","category":"migration-and-identity","title":{"ar":"جزيرة بيكيني: المنفى والثقة والدين النووي","de":"Bikini-Atoll: Exil, Treuhandfonds und nukleare Schuld","en":"Bikini Atoll: exile, trust fund and nuclear debt"},"deck":{"ar":"عندما طلبت البحرية الأمريكية من 167 شخصًا مغادرة منازلهم عام 1946، قال زعيمهم إن كل شيء في يد الله. منذ ذلك الحين، يعيش شعب بيكيني في المنفى.","de":"Als die US-Marine 1946 167 Menschen bat, ihre Heimat zu verlassen, sagte ihr Anführer, alles liege in Gottes Hand. Seitdem lebt das Bikini-Volk im Exil.","en":"When the US Navy asked 167 people to leave their home in 1946, their leader said everything is in God's hands. Since then, the Bikini people have lived in exile."},"teaser":{"ar":"قصة شعب بيكيني ليست فقط عن فقدان الأرض، بل عن الصمود والاعتماد على تعويضات نووية وثقافة الذاكرة.","de":"Die Geschichte der Bikini-Leute handelt nicht nur vom Verlust des Landes, sondern von Widerstandsfähigkeit, Abhängigkeit von Entschädigungen und Erinnerungskultur.","en":"The Bikini story is not just about losing land, but about resilience, dependence on nuclear compensation and a culture of memory."},"readingMinutes":1,"sections":{"ar":[{"heading":"الترحيل الأول: رونجيريك والمجاعة","paragraphs":["في عام 1946، طلبت البحرية الأمريكية من 167 شخصًا من سكان بيكيني الانتقال 'من أجل خير البشرية وإنهاء جميع الحروب العالمية'. أجاب زعيمهم الملك يهوذا: 'MEN OTEMJEJ REJ ILO BEIN ANIJ' — كل شيء في يد الله. انتقل المجتمع إلى رونجيريك، حيث نفد الطعام وتضور الناس جوعًا.","في عام 1948، نُقلوا مرة أخرى إلى كيلي، جزيرة مساحتها 200 فدان بدون بحيرة، وسدس مساحة بيكيني. في عام 1954، لوث اختبار كاسل برافو بقوة 15 ميغاطن الحلقة المرجانية. تختلف التجارب حسب الجيل والمنطقة: بعض كبار السن يتذكرون الجوع، بينما يعرف الشباب في ماجورو القصة من الحكايات العائلية."]},{"heading":"الشتات والتعويضات","paragraphs":["فشلت محاولات إعادة التوطين، واليوم يعيش معظم شعب بيكيني في كيلي وماجورو وإيجيت، مع حوالي 1400 في الولايات المتحدة وأماكن أخرى. جعلت مدفوعات صندوق الائتمان والمطالبات النووية بعض السكان يعتمدون على المال الأمريكي، بينما تظل الحلقة المرجانية نفسها غير قابلة للاستخدام إلى حد كبير.","في الأول من مارس، يتذكر عائلات بيكيني في ماجورو وكيلي الترحيل، وتُكرر شعار العلم — 'كل شيء في يد الله'. لكن الآراء تختلف حول إعادة التوطين والتعويضات، والعلم الإشعاعي لا يزال محل نقاش. القصة ليست فقط قصة ضحية، بل أيضًا قصة مجتمع يتفاوض على مستقبله."]}],"de":[{"heading":"Erste Umsiedlung: Rongerik und der Hunger","paragraphs":["1946 bat die US-Marine 167 Bewohner von Bikini, 'zum Wohle der Menschheit und zur Beendigung aller Weltkriege' umzusiedeln. Ihr Anführer King Juda antwortete: 'MEN OTEMJEJ REJ ILO BEIN ANIJ' — alles liegt in Gottes Hand. Die Gemeinschaft zog nach Rongerik, wo die Nahrung ausging und Menschen hungerten.","1948 wurden sie erneut nach Kili gebracht, eine 200 Hektar große Insel ohne Lagune und ein Sechstel der Größe von Bikini. 1954 kontaminierte der 15-Megatonnen-Test Castle Bravo das Atoll. Die Erfahrungen variieren je nach Generation und Region: Ältere erinnern sich an den Hunger, während Jüngere in Majuro die Geschichte aus Familienerzählungen kennen."]},{"heading":"Diaspora und Entschädigung","paragraphs":["Die Wiederansiedlungsversuche scheiterten, und heute leben die meisten Bikini-Leute auf Kili, Majuro und Ejit, etwa 1.400 in den Vereinigten Staaten und anderswo. Zahlungen aus dem Treuhandfonds und nuklearen Ansprüchen machten einige Inselbewohner von US-Geld abhängig, während das Atoll selbst weitgehend unbrauchbar bleibt.","Am 1. März gedenken Bikini-Familien in Majuro und Kili der Umsiedlung, und das Motto der Flagge — 'alles liegt in Gottes Hand' — wird wiederholt. Doch die Meinungen über Wiederansiedlung und Entschädigung gehen auseinander, und die Strahlenwissenschaft bleibt umstritten. Die Geschichte ist nicht nur eine der Opfer, sondern auch eine der Selbstbestimmung."]}],"en":[{"heading":"First relocation: Rongerik and starvation","paragraphs":["In 1946, the US Navy asked 167 Bikini residents to relocate 'for the good of mankind and to end all world wars'. Their leader, King Juda, answered 'MEN OTEMJEJ REJ ILO BEIN ANIJ' — everything is in God's hands. The community moved to Rongerik, where food ran out and people starved.","In 1948 they were moved again to Kili, a 200-acre island without a lagoon and one-sixth the size of Bikini. In 1954 the 15-megaton Castle Bravo test contaminated the atoll. Experiences vary by generation and region: elders remember the hunger, while younger people in Majuro know the story from family tales."]},{"heading":"Diaspora and compensation","paragraphs":["Resettlement attempts failed, and today most Bikini people live on Kili, Majuro and Ejit, with about 1,400 in the United States and elsewhere. Trust-fund and nuclear-claims payments made some islanders dependent on US money, while the atoll itself remains largely unusable.","On 1 March, Bikini families in Majuro and Kili remember the relocation, and the flag's motto — 'everything is in God's hands' — is repeated. But Bikini people disagree about resettlement and compensation, and radiation science remains contested. The story is not only one of victimhood, but also of a community negotiating its future."]}]},"context":{"countries":["MH"],"region":"Marshall Islands","community":"Bikini islanders","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["migration-and-identity","Marshall Islands"],"sources":[{"organization":"Wikipedia","title":{"ar":"Bikini Atoll","de":"Bikini Atoll","en":"Bikini Atoll"},"url":"https://en.wikipedia.org/wiki/Bikini_Atoll","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Runit Island","de":"Runit Island","en":"Runit Island"},"url":"https://en.wikipedia.org/wiki/Runit_Island","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الأول من مارس، تتذكر عائلات بيكيني في ماجورو وكيلي الترحيل، ويُكرر شعار العلم — 'كل شيء في يد الله'.","de":"Am 1. März gedenken Bikini-Familien in Majuro und Kili der Umsiedlung, und das Motto der Flagge — 'alles liegt in Gottes Hand' — wird wiederholt.","en":"On 1 March, Bikini families in Majuro and Kili remember the relocation, and the flag's motto — 'everything is in God's hands' — is repeated."},"misunderstanding":{"ar":"الاعتقاد بأن شعب بيكيني مجرد ضحايا سلبيين يتجاهل وكالتهم في التفاوض على التعويضات والحفاظ على ثقافتهم.","de":"Die Annahme, die Bikini-Leute seien nur passive Opfer, ignoriert ihre Handlungsfähigkeit bei der Aushandlung von Entschädigungen und der Bewahrung ihrer Kultur.","en":"Assuming Bikini people are only passive victims ignores their agency in negotiating compensation and maintaining their culture."},"comparison":{"ar":"على عكس العديد من مجتمعات الشتات، يحتفظ شعب بيكيني بهوية مشتركة قوية عبر المحيط الهادئ والولايات المتحدة، مع روابط قانونية ومالية مع وطنهم الأصلي.","de":"Anders als viele Diasporagemeinschaften bewahren die Bikini-Leute eine starke gemeinsame Identität über den Pazifik und die USA hinweg, mit rechtlichen und finanziellen Bindungen an ihre Heimat.","en":"Unlike many diaspora communities, Bikini people maintain a strong shared identity across the Pacific and the US, with legal and financial ties to their homeland."}},{"id":"oce-033","version":2,"slug":"wayfinding-crossing-the-pacific-without-instruments","contentType":"note","category":"nature-and-seasons","title":{"ar":"الإبحار في المحيط بلا أدوات","de":"Über den Pazifik ohne Instrumente","en":"Crossing the Pacific Without Instruments"},"deck":{"ar":"كيف عبر البولينيزيون المحيط الهادئ بالنجوم والأمواج والطيور، وكيف عادت هذه المعرفة بعد أن كادت تُفقد.","de":"Wie Polynesier den Pazifik mit Sternen, Dünung, Vögeln und Wolken überquerten und wie dieses Wissen fast verloren ging.","en":"How Polynesians read stars, swells, birds and cloud to settle the Pacific, and how that knowledge was nearly lost and revived."},"teaser":{"ar":"استوطن البولينيزيون جزر المحيط الهادئ بقوارب مزدوجة الجسم، يقرأون النجوم والأمواج والطيور والغيوم بدل الخرائط والأدوات.","de":"Polynesier besiedelten den Pazifik mit Doppelrumpf- und Auslegerkanus und navigierten nach Sternen, Dünung, Winden, Vögeln und Wolken.","en":"Polynesians settled the Pacific in double-hulled and outrigger canoes, navigating by stars, swells, winds, birds and cloud instead of charts."},"readingMinutes":1,"sections":{"ar":[{"heading":"قراءة البحر في الظلام","paragraphs":["استوطن البولينيزيون المحيط الهادئ بقوارب مزدوجة الجسم وقوارب ذات أذرع جانبية، مستدلّين بالنجوم والأمواج والرياح والطيور والغيوم. كان الملاح يستلقي على سطح القارب ليلاً ليحسّ الموجة السائدة، ثم يتحقق من النجم الصاعد في الأفق.","تسبق علامات الأرض رؤية الأرض: طائر معيّن، أو تغيّر في الغيوم، أو نباتات عائمة، أو موجة تنحني حول جزيرة. وتختلف هذه العلامات قليلاً من أرخبيل إلى آخر، كما تتباين بين الأجيال خبرة الملاحين وتدريبهم."]},{"heading":"ذاكرة محفوظة في الأناشيد","paragraphs":["كانت المعرفة تُنقل في الأناشيد والنسب لا في خرائط مكتوبة، وكان المتدربون يحفظون مسارات النجوم ويبحرون مع المعلّمين. وعبارة «wayfinding» صاغها كيفن لينش لتصميم المدن عام 1960، ثم استُعيرت لوصف الإبحار الهادئ بلا أدوات.","بدأ الإحياء في السبعينيات، حين أعاد الملاحون من هاواي وغيرهم بناء القوارب والإبحار بلا أدوات."]}],"de":[{"heading":"Das Meer im Dunkeln lesen","paragraphs":["Polynesier besiedelten den Pazifik mit Doppelrumpf- und Auslegerkanus und navigierten nach Sternen, Dünung, Winden, Vögeln und Wolken. Nachts lag ein Navigator auf dem Deck, spürte die vorherrschende Dünung und prüfte dann den Stern, der am Horizont aufstieg.","Landzeichen kommen vor dem Land: ein bestimmter Vogel, eine Veränderung der Wolken, treibende Pflanzen oder eine Dünung, die sich um eine Insel biegt. Diese Zeichen unterscheiden sich leicht von Archipel zu Archipel, und auch zwischen den Generationen variiert die Erfahrung der Navigatoren."]},{"heading":"Wissen in Gesängen bewahrt","paragraphs":["Das Wissen wurde in Gesängen und Genealogien weitergegeben, nicht in geschriebenen Karten; Lehrlinge prägten sich Sternenwege ein und segelten mit Meistern. Der Begriff „wayfinding“ wurde 1960 von Kevin Lynch für Städtebau geprägt und später für die instrumentenlose Pazifiknavigation übernommen.","Die Wiederbelebung begann in den 1970er-Jahren, als hawaiianische und andere Seefahrer Kanus nachbauten und wieder ohne Instrumente segelten."]}],"en":[{"heading":"Reading the sea in darkness","paragraphs":["Polynesians settled the Pacific using double-hulled and outrigger canoes, navigating by stars, swells, winds, birds and cloud. A navigator can read the sea at night by lying on the deck and feeling the dominant swell, then checking the star rising on the horizon.","Land signs come before land: a particular bird, a change in cloud, floating vegetation or a swell that bends around an island. These signs vary slightly from one archipelago to the next, and navigators' experience also differs between generations."]},{"heading":"Knowledge carried in chant","paragraphs":["The knowledge was carried in chant and genealogy rather than written charts, and apprentices learned by memorising star paths and sailing with masters. The word 'wayfinding' was coined for urban design by Kevin Lynch in 1960 and later borrowed to describe Pacific navigation without instruments.","Revival began in the 1970s, when Hawaiian and other voyagers rebuilt canoes and sailed without instruments again."]}]},"context":{"countries":[],"region":"Pacific Ocean","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["nature-and-seasons","Pacific Ocean"],"sources":[{"organization":"Wikipedia","title":{"ar":"Polynesian navigation","de":"Polynesian navigation","en":"Polynesian navigation"},"url":"https://en.wikipedia.org/wiki/Polynesian_navigation","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Wayfinding","de":"Wayfinding","en":"Wayfinding"},"url":"https://en.wikipedia.org/wiki/Wayfinding","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يستلقي الملاح على سطح القارب، يحسّ الموجة ويسمّي النجم الصاعد أمامه؛ وبحلول الصباح يقرأ الطيور والغيوم بحثاً عن الجزيرة.","de":"Ein Navigator liegt auf dem Deck, spürt die Dünung und benennt den Stern voraus; am Morgen liest er Vögel und Wolken, um die Insel zu finden.","en":"A navigator lies on the deck, feels the swell and names the star rising ahead; by morning he is reading birds and cloud for the island."},"misunderstanding":{"ar":"ليس صحيحاً أن الملاحة الهادئة كانت حدساً غامضاً بلا منهج؛ فقد كانت معرفة دقيقة تُتعلّم بالحفظ والتدريب الطويل مع المعلّمين.","de":"Es stimmt nicht, dass Pazifiknavigation nur vages Bauchgefühl war; sie war präzises Wissen, das durch Auswendiglernen und lange Ausbildung bei Meistern erlernt wurde.","en":"It is not true that Pacific navigation was vague intuition; it was precise knowledge learned through memorisation and long training with masters."},"comparison":{"ar":"في مقابل الاعتماد الحديث على الخرائط والأقمار الصناعية، كان الملاح الهادئ يجمع إشارات متعددة من السماء والبحر معاً.","de":"Anders als die moderne Orientierung mit Karten und Satelliten verband der pazifische Navigator mehrere Zeichen von Himmel und Meer zugleich.","en":"Unlike modern reliance on charts and satellites, the Pacific navigator combined several signs from sky and sea at once."}},{"id":"oce-034","version":2,"slug":"tuvalu-and-the-falepili-union-staying-moving-and-sovereignty","contentType":"note","category":"migration-and-identity","title":{"ar":"توفالو: البقاء والهجرة في اتحاد فالبيلي","de":"Tuvalu: Bleiben und Gehen im Falepili-Pakt","en":"Tuvalu: Staying and Moving in the Falepili Union"},"deck":{"ar":"كيف توازن دولة جزرية صغيرة بين البقاء في أرضها والانتقال منها، مع الحفاظ على سيادتها وهويتها.","de":"Wie ein kleiner Inselstaat zwischen dem Verbleib auf seinem Land und dem Wegzug abwägt und dabei seine Souveränität wahrt.","en":"How a small island nation weighs staying on its land against moving away, while holding on to its sovereignty and identity."},"teaser":{"ar":"في توفالو، حيث ترتفع الأرض بضعة أمتار فقط، تتخذ العائلات قرارات الهجرة في Maneapa، بينما تواجه البلاد ارتفاع مستوى البحر وتغير المناخ.","de":"In Tuvalu, wo das Land nur wenige Meter über dem Meer liegt, entscheiden Familien in der Maneapa über Migration, während das Land mit Meeresspiegelanstieg und Klimawandel kämpft.","en":"In Tuvalu, where land rises only a few metres above the sea, families discuss migration in the maneapa while facing sea-level rise and climate change."},"readingMinutes":1,"sections":{"ar":[{"heading":"أرض ضيقة ومستقبل غامض","paragraphs":["توفالو تسع جزر — ثلاث جزر مرجانية وست جزر حلقية — يبلغ عدد سكانها حوالي 10,600 نسمة، وأعلى نقطة فيها لا تتجاوز بضعة أمتار فوق سطح البحر. يهدد ارتفاع مستوى البحر وتسرب المياه المالحة والجفاف والأعاصير حفر البولاكا وحدائق التارو التي تشكل أساس الحياة الغذائية.","لطالما ناضلت توفالو لعقود في محادثات المناخ، مؤكدة أن الأمة يمكن أن تفقد حتى لو لم تغمر أرضها بالكامل. هذا الموقف يعكس إصرارًا على البقاء وعدم الاستسلام للظروف."]},{"heading":"الهجرة بين العائلة والسيادة","paragraphs":["في نوفمبر 2023، وقعت توفالو اتحاد فالبيلي مع أستراليا، الذي يوفر مسارًا للتنقل المناخي مع تأكيد دولة توفالو وسيادتها. الهجرة موجودة بالفعل عبر شبكات العائلة إلى نيوزيلندا وأستراليا وفيجي، والتحويلات المالية تشكل الحياة اليومية.","تُناقش قرارات من يتقدم للهجرة في المانيبا، حيث تجتمع مجالس الجزر. يختلف التأثير بين الجزر، وتختلف الرؤى بين الأجيال: بعض الشباب يرى في الهجرة فرصة، بينما يتمسك كبار السن بالبقاء."]}],"de":[{"heading":"Enges Land, ungewisse Zukunft","paragraphs":["Tuvalu besteht aus neun Inseln – drei Riffinseln und sechs Atollen – mit etwa 10.600 Einwohnern und einem höchsten Punkt nur wenige Meter über dem Meer. Meeresspiegelanstieg, Salzwassereintritt, Dürren und Zyklone bedrohen die Pulaka-Gruben und Taro-Gärten, die die Ernährung sichern.","Seit Jahrzehnten kämpft Tuvalu auf Klimakonferenzen und argumentiert, dass eine Nation verloren gehen kann, ohne dass ihr Land vollständig überflutet wird. Dieser Einsatz zeigt den Willen, nicht aufzugeben."]},{"heading":"Migration zwischen Familie und Souveränität","paragraphs":["Im November 2023 unterzeichnete Tuvalu den Falepili-Pakt mit Australien, der einen Klimamobilitätspfad bietet und gleichzeitig Tuvalus Staatlichkeit und Souveränität bekräftigt. Migration läuft bereits über familiäre Netzwerke nach Neuseeland, Australien und Fidschi, und Rücküberweisungen prägen den Alltag.","Entscheidungen darüber, wer einen Migrationsantrag stellt, werden in der Maneapa diskutiert, wo die Inselräte zusammenkommen. Die Auswirkungen unterscheiden sich je nach Insel, und die Ansichten variieren zwischen den Generationen: Manche Jüngere sehen Migration als Chance, während Ältere am Bleiben festhalten."]}],"en":[{"heading":"Narrow Land, Uncertain Future","paragraphs":["Tuvalu is nine islands — three reef islands and six atolls — with a population of about 10,600 and a highest point only a few metres above the sea. Sea-level rise, saltwater intrusion, drought and cyclones threaten the pulaka pits and taro gardens that anchor food life.","Tuvalu has campaigned for decades at climate talks, arguing that a nation can be lost without its land ever being fully submerged. This stance reflects a determination not to give up."]},{"heading":"Migration Between Family and Sovereignty","paragraphs":["In November 2023 Tuvalu signed the Falepili Union with Australia, which offers a climate mobility pathway while affirming Tuvalu's statehood and sovereignty. Migration already runs through family networks to New Zealand, Australia and Fiji, and remittances shape daily life.","Decisions about who applies to migrate are discussed in the maneapa, where island councils still meet. Impacts differ between islands, and views vary across generations: some younger people see migration as an opportunity, while elders hold on to staying."]}]},"context":{"countries":["TV"],"region":"Tuvalu","community":"Tuvaluan","continent":"oceania","languages":["en"],"period":"contemporary"},"tags":["migration-and-identity","Tuvalu"],"sources":[{"organization":"Wikipedia","title":{"ar":"Climate change in Tuvalu","de":"Climate change in Tuvalu","en":"Climate change in Tuvalu"},"url":"https://en.wikipedia.org/wiki/Climate_change_in_Tuvalu","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Tuvalu","de":"Tuvalu","en":"Tuvalu"},"url":"https://en.wikipedia.org/wiki/Tuvalu","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في فونافوتي، تعتني العائلات بحفر البولاكا وخزانات مياه الأمطار، ويجتمع مجلس الجزيرة في المانيبا لمناقشة قرعة الهجرة والمد العالي القادم.","de":"Auf Funafuti pflegen Familien Pulaka-Gruben und Regenwassertanks, und der Inselrat trifft sich in der Maneapa, um über die Migrationslotterie und die nächste Springflut zu beraten.","en":"On Funafuti families tend pulaka pits and rain tanks, and the island council meets in the maneapa to discuss the migration ballot and the next king tide."},"misunderstanding":{"ar":"يُفترض أحيانًا أن سكان توفالو ضحايا سلبيون، لكنهم في الواقع يطالبون بالبقاء ويشاركون في نقاشات الهجرة.","de":"Manchmal wird angenommen, Tuvaluer seien passive Opfer, doch sie setzen sich für das Bleiben ein und diskutieren Migration aktiv.","en":"Tuvaluans are sometimes assumed to be passive victims, but they actively advocate for staying and debate migration."},"comparison":{"ar":"بينما توفر اتفاقية فالبيلي خيارًا، فإنها تختلف عن اتفاقات الهجرة التقليدية بتأكيدها على السيادة وعدم فقدان الدولة.","de":"Der Falepili-Pakt bietet eine Option, unterscheidet sich aber von traditionellen Migrationsabkommen durch die Betonung von Souveränität und Staatlichkeit.","en":"The Falepili Union offers an option but differs from traditional migration agreements by emphasising sovereignty and statehood."}},{"id":"oce-035","version":2,"slug":"kanak-and-the-noumea-accord-land-custom-and-a-vote-on-independence","contentType":"note","category":"migration-and-identity","title":{"ar":"شعب الكاناك بين الأرض والتصويت","de":"Kanak zwischen Land und Unabhängigkeitsvotum","en":"Kanak between land and the independence vote"},"deck":{"ar":"في كاليدونيا الجديدة، الكاناك يربطون الهوية بالأرض والعشيرة، بينما يبقى سؤال الاستقلال مفتوحاً بعد عقود من الاتفاقات والاضطرابات.","de":"In Neukaledonien verbinden die Kanak Identität mit Land und Sippe, während die Frage der Unabhängigkeit nach Jahrzehnten der Abkommen offen bleibt.","en":"In New Caledonia, Kanak identity is bound to land and clan, while the question of independence remains open after decades of accords and unrest."},"teaser":{"ar":"من الاتفاق إلى الاحتجاج: كيف يعيش شعب الكاناك سؤال الهوية والاستقلال في كاليدونيا الجديدة اليوم؟","de":"Vom Abkommen zum Aufstand: Wie lebt die Kanak-Bevölkerung Neukaledoniens die Frage nach Identität und Unabhängigkeit heute?","en":"From accord to uprising: how the Kanak people of New Caledonia live the question of identity and independence today."},"readingMinutes":1,"sections":{"ar":[{"heading":"الأرض أساس الهوية","paragraphs":["يشكّل الكاناك الشعبَ الميلانيزي الأصلي في كاليدونيا الجديدة، وكانوا 41% من السكان في 2019، ويتحدثون فرعاً من اللغات الأسترونيزية.","الأرض جوهر هويتهم: العشائر تحتفظ بأراضٍ عرفية، ويبقى البيت التقليدي واليام محورين في المراسم.","يختلف هذا الإرث من منطقة إلى أخرى ومن جيل إلى جيل، إذ يقيم بعض الشباب في نوميا بينما تبقى العشائر في القرى حيّة."]},{"heading":"مسار الاستقلال","paragraphs":["تأسست حركة الاستقلال فلنكس في 1984 بعد فشل ثورة 1967 واضطرابات الثمانينيات.","أنشأ اتفاق نوميا 1998 جنسية كاليدونية جديدة ونقل صلاحيات على مدى عشرين عاماً، مع ما يصل إلى ثلاثة استفتاءات.","صوّت الناخبون في 2018 و2020 للبقاء فرنسيين، بينما قاطع الاستقلاليون استفتاء ديسمبر 2021. وفي مايو 2024 أشعلت خطة فرنسية لتوسيع القائمة الانتخابية أسوأ اضطرابات منذ عقود."]}],"de":[{"heading":"Das Land als Kern der Identität","paragraphs":["Die Kanak sind die indigene melanesische Bevölkerung Neukaledoniens; 2019 stellten sie 41 Prozent der Bevölkerung und sprechen einen Zweig der austronesischen Sprachen.","Land ist der Kern ihrer Identität: Sippen halten Gewohnheitsland, und das traditionelle Haus sowie die Yamswurzel bleiben zentral für Zeremonien.","Dieses Erbe unterscheidet sich je nach Region und Generation, denn manche Jugendliche leben in Nouméa, während die Sippen in den Dörfern bestehen bleiben."]},{"heading":"Der Weg zur Unabhängigkeit","paragraphs":["Die Unabhängigkeitsbewegung FLNKS wurde 1984 gegründet, nach dem gescheiterten Aufstand von 1967 und den Unruhen der 1980er Jahre.","Das Abkommen von Nouméa 1998 schuf eine neukaledonische Staatsbürgerschaft und eine zwanzigjährige Machtübertragung mit bis zu drei Unabhängigkeitsreferenden.","2018 und 2020 stimmten die Wähler für den Verbleib bei Frankreich, während die Unabhängigkeitsbewegung das Referendum im Dezember 2021 boykottierte. Im Mai 2024 löste ein französischer Plan zur Erweiterung der Wählerliste die schwersten Unruhen seit Jahrzehnten aus."]}],"en":[{"heading":"Land at the core of identity","paragraphs":["Kanak are the Indigenous Melanesian people of New Caledonia, 41% of the population in 2019, and speakers of the New Caledonian branch of Austronesian languages.","Land is the core of Kanak identity: clans hold customary land, and the case and the yam remain central to ceremony.","This inheritance varies by region and generation, as some young people live in Nouméa while clans remain rooted in villages."]},{"heading":"The road to independence","paragraphs":["The independence movement FLNKS was founded in 1984, after the failed revolt of 1967 and the unrest of the 1980s.","The Nouméa Accord of 1998 created a New Caledonian citizenship and a twenty-year transfer of powers, with up to three independence referendums.","Referendums in 2018 and 2020 voted to stay French, while the December 2021 vote was boycotted by the independence movement. In May 2024 a French plan to widen the electoral roll sparked the worst unrest in decades."]}]},"context":{"countries":["NC"],"region":"New Caledonia","community":"Kanak","continent":"oceania","languages":["fr"],"period":"contemporary"},"tags":["migration-and-identity","New Caledonia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Kanak people","de":"Kanak people","en":"Kanak people"},"url":"https://en.wikipedia.org/wiki/Kanak_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Nouméa Accord","de":"Nouméa Accord","en":"Nouméa Accord"},"url":"https://en.wikipedia.org/wiki/Noum%C3%A9a_Accord","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في قرية كاناك يقدّم الزائر هدية عرفية للعشيرة قبل الترحيب به؛ وفي نوميا يجادل الشخص نفسه حول استفتاء الاستقلال.","de":"In einem Kanak-Dorf überreicht ein Besucher der Sippe vor der Begrüßung ein traditionelles Geschenk; in Nouméa streitet dieselbe Person über das Unabhängigkeitsvotum.","en":"In a Kanak village a visitor presents a customary gift to the clan before being welcomed; in Nouméa the same person argues about the independence vote."},"misunderstanding":{"ar":"الكاناك ليسوا أمة واحدة؛ تختلف العشائر واللغات، وسؤال الاستقلال ما زال معلقاً، ولا يصح استخدام اسمهم كتصنيف لنمط حياة.","de":"Die Kanak sind keine einheitliche Nation; Sippen und Sprachen unterscheiden sich, die Unabhängigkeitsfrage ist ungelöst, und „Kanak“ taugt nicht als Lebensstil-Etikett.","en":"Kanak is not a single nation — clans and languages differ, and the independence question remains unresolved; 'Kanak' should not be used as a lifestyle label."},"comparison":{"ar":"بينما يرى البعض في الاتفاق تسوية تاريخية، يعتبره آخرون محطة غير مكتملة، ويختلف الموقف نفسه بين الأجيال والمناطق.","de":"Während manche das Abkommen als historischen Kompromiss sehen, gilt es anderen als unvollendete Etappe; die Haltung variiert zwischen Generationen und Regionen.","en":"Where some see the accord as a historic settlement, others regard it as an unfinished stage, and the stance differs across generations and regions."}},{"id":"soc-084","version":2,"slug":"pulaaku-the-fulani-code-of-reserve-and-dignity","contentType":"note","category":"social-behaviour","title":{"ar":"بولاكو: كود التحفظ والكرامة عند الفولاني","de":"Pulaaku: Der Fulani-Kodex von Zurückhaltung und Würde","en":"Pulaaku: the Fulani code of reserve and dignity"},"deck":{"ar":"كيف ينظّم نظام سلوكي عريق حياة شعب رعوي منتشر في الساحل وغرب أفريقيا.","de":"Wie ein überlieferter Verhaltenskodex das Leben eines pastoralen Volkes in der Sahelzone und Westafrika prägt.","en":"How an inherited code of conduct shapes the everyday life of a pastoral people across the Sahel and West Africa."},"teaser":{"ar":"بولاكو ليس قانوناً مكتوباً، بل كود سلوك يومي يربط مجتمعات الفولاني المتباعدة عبر الحدود.","de":"Pulaaku ist kein geschriebenes Gesetz, sondern ein Alltagskodex, der weit verstreute Fulani-Gemeinschaften über Grenzen hinweg verbindet.","en":"Pulaaku is not a written law but an everyday code that links widely scattered Fulani communities across borders."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما معنى بولاكو؟","paragraphs":["بولاكو هو الكود العرفي للسلوك عند الفولاني (فولɓي)، وهم شعب رعوي ينتشر في الساحل وغرب أفريقيا. يقوم على قيم أربع: سمتيندي أي الحياء والخجل، ومُنْيال أي الصبر وضبط النفس، وحكِّلِّه أي التبصر والتفكير في العواقب، ونغورغو أي الشجاعة.","هذه القيم لا تبقى في الكتب، بل تظهر في الكلام المتحفظ، وحسن الضيافة، وتجنب إذلال الناس علناً، وتحمل المشقة بصمت."]},{"heading":"كود يعبر الحدود","paragraphs":["مجتمعات الفولاني متفرقة جغرافياً، وبولاكو أحد العلامات الثقافية التي تصل بينها عبر البلدان. وقد تكيّف معه الفولاني المستقرون ومجتمعات المهجر، ويتقاطع في كثير من جوانب مع القيم الإسلامية.","لكن المجتمع الفولاني متنوع، وليس كل فرد يمارس بولاكو بالطريقة نفسها؛ فمعناه يتغير بحسب المنطقة وسبل العيش والجيل، ولا ينبغي للغريب أن يعامله كنص ثابت."]}],"de":[{"heading":"Was bedeutet Pulaaku?","paragraphs":["Pulaaku ist der gewohnheitsrechtliche Verhaltenskodex der Fulani (Fulɓe), eines pastoralen Volkes, das in der Sahelzone und in Westafrika verbreitet ist. Er betont vier Werte: semteende, also Bescheidenheit und Scham, munyal, also Geduld und Selbstbeherrschung, hakkille, also Vorausschau, und ngorgu, also Mut.","Diese Werte bleiben nicht auf dem Papier, sondern zeigen sich im zurückhaltenden Sprechen, in Gastfreundschaft, im Vermeiden öffentlicher Demütigung und im stillen Ertragen von Härten."]},{"heading":"Ein Kodex über Grenzen hinweg","paragraphs":["Fulani-Gemeinschaften leben weit verstreut, und Pulaaku ist eines der kulturellen Merkmale, die sie über Ländergrenzen hinweg verbinden. Sesshaft gewordene Fulani und Diaspora-Gemeinschaften haben den Kodex angepasst, und in vielen Bereichen überschneidet er sich mit islamischen Werten.","Doch die Fulani-Gesellschaft ist vielfältig, und nicht alle befolgen Pulaaku auf dieselbe Weise; seine Bedeutung variiert nach Region, Lebensweise und Generation, und Außenstehende sollten ihn nicht als festes Drehbuch verstehen."]}],"en":[{"heading":"What does pulaaku mean?","paragraphs":["Pulaaku is the customary code of conduct of the Fulani (Fulɓe), a pastoralist people spread across the Sahel and West Africa. It emphasises four values: semteende, modesty and shame; munyal, patience and self-control; hakkille, forethought; and ngorgu, courage.","These values do not stay on paper. They show up in restrained speech, hospitality, the avoidance of public humiliation, and the quiet endurance of hardship."]},{"heading":"A code that crosses borders","paragraphs":["Fulani communities are widely dispersed, and pulaaku is one of the cultural markers that connects them across borders. Sedentary Fulani and diaspora communities have adapted the code, and in many areas it overlaps with Islamic values.","Yet Fulani society is diverse, and not all Fulani follow pulaaku in the same way; its meaning varies by region, livelihood and generation, and outsiders should not treat it as a fixed script."]}]},"context":{"countries":[],"region":"Sahel and West Africa","community":"Fulani (Fulɓe)","continent":"africa","languages":["ff","fr","en"],"period":"contemporary"},"tags":["social-behaviour","Sahel and West Africa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Fula people","de":"Fula people","en":"Fula people"},"url":"https://en.wikipedia.org/wiki/Fula_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Fulani proverbs","de":"Fulani proverbs","en":"Fulani proverbs"},"url":"https://en.wikipedia.org/wiki/Fulani_proverbs","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"شاب فولاني يتحمل تأخيراً طويلاً دون شكوى، لأن مُنْيال، الصبر الذي يطلبه بولاكو، جزء من صورته أمام الآخرين.","de":"Ein junger Fulani-Mann erträgt eine lange Verzögerung ohne Klage, weil munyal, die von Pulaaku verlangte Geduld, zu seinem Auftreten gehört.","en":"A young Fulani man endures a long delay without complaint because munyal, the patience required by pulaaku, is part of how he presents himself."},"misunderstanding":{"ar":"من السهل أن يُقرأ التحفظ الفولاني كبرود أو رفض للتواصل، مع أنه في الغالب احترام للذات وللآخر في الوقت نفسه.","de":"Fulani-Zurückhaltung wird leicht als Kälte oder Abweisung gelesen, obwohl sie meist zugleich Respekt vor sich selbst und vor anderen ausdrückt.","en":"Fulani reserve is easily read as coldness or rejection, although it usually expresses respect for oneself and for others at the same time."},"comparison":{"ar":"يشبه بولاكو في وظيفته أعراف الشرف والكرم لدى جماعات رعوية أخرى، لكنه يظل مرتبطاً بتاريخ الفولاني وبيئتهم الممتدة.","de":"In seiner Funktion ähnelt Pulaaku den Ehre- und Gastfreundschaftsnormen anderer pastoraler Gruppen, bleibt aber an die Geschichte und die weite Lebenswelt der Fulani gebunden.","en":"In its function, pulaaku resembles the honour and hospitality norms of other pastoral groups, but it remains tied to Fulani history and their wide-ranging way of life."}},{"id":"soc-085","version":2,"slug":"overseas-filipino-workers-families-split-across-economies","contentType":"note","category":"migration-and-identity","title":{"ar":"العمال الفلبينيون في الخارج: أسر ممزقة بين الاقتصادات","de":"Philippinische Arbeitsmigranten: Familien über Wirtschaften verteilt","en":"Overseas Filipino Workers: families split across economies"},"deck":{"ar":"يعمل نحو 1.77 مليون فلبيني في الخارج، مما يجعل التحويلات المالية عمودًا فقريًا للاقتصاد، لكنه يفرض فصلًا طويلًا على العائلات.","de":"Rund 1,77 Millionen Filipinos arbeiten im Ausland. Ihre Überweisungen stützen die Wirtschaft, doch die Familien zahlen einen hohen Preis.","en":"About 1.77 million Filipinos work abroad, sending remittances that bolster the economy but often separating families for years."},"teaser":{"ar":"العمال الفلبينيون في الخارج (OFW) هم أبطال الاقتصاد الحديث، لكن قصتهم تحمل ثمنًا عائليًا باهظًا.","de":"Overseas Filipino Workers (OFW) gelten als Helden der Wirtschaft, doch ihre Geschichte erzählt von Trennung und prekärer Arbeit.","en":"Overseas Filipino Workers are celebrated as modern heroes, yet their story reveals the social costs of separation and precarious work."},"readingMinutes":1,"sections":{"ar":[{"heading":"اقتصاد قائم على التحويلات","paragraphs":["العامل الفلبيني في الخارج (OFW) هو المصطلح الرسمي للفلبينيين الذين يعملون abroad لفترة محددة. بين أبريل وسبتمبر 2020، تم إحصاء حوالي 1.77 مليون عامل. تتركز وظائفهم في العمل المنزلي والرعاية الصحية والبناء والملاحة البحرية والخدمات، مع مجتمعات كبيرة في الخليج وهونغ كونغ وسنغافورة واليابان والولايات المتحدة.","تشكل تحويلات هؤلاء العمال جزءًا رئيسيًا من الاقتصاد الفلبيني. على الصعيد العالمي، التحويلات المالية أكبر بثلاث مرات من إجمالي المساعدات الخارجية. هذا الاعتماد الاقتصادي يجعل الهجرة خيارًا اضطراريًا لكثير من الأسر."]},{"heading":"حياة أسرية عبر الشاشات","paragraphs":["تعيش العائلات منفصلة لسنوات، وتربي الأطفال عبر مكالمات الفيديو وترسل صناديق باليكبايان إلى الوطن. يصفهم الدولة بأنهم 'أبطال جدد' (bagong bayani)، بينما يشير النقاد إلى التكاليف الاجتماعية للفصل والعمل غير المستقر. تختلف التجارب بشكل واسع حسب المهنة والوجهة والوضع القانوني، فليس كل مهاجر موثقًا أو يحول المال بانتظام، ويمكن أن تخفي رواية البطولة انتهاكات العمل."]}],"de":[{"heading":"Wirtschaft durch Überweisungen","paragraphs":["Overseas Filipino Worker (OFW) ist der offizielle Begriff für Filipinos, die befristet im Ausland arbeiten. Zwischen April und September 2020 wurden etwa 1,77 Millionen gezählt. Sie arbeiten vor allem in der häuslichen Pflege, im Gesundheitswesen, im Baugewerbe, in der Seefahrt und im Dienstleistungssektor, mit großen Gemeinschaften am Golf, in Hongkong, Singapur, Japan und den USA.","Die Rücküberweisungen der OFWs sind ein wichtiger Teil der philippinischen Wirtschaft. Weltweit sind Überweisungen mehr als dreimal so groß wie die gesamte globale Entwicklungshilfe. Diese wirtschaftliche Abhängigkeit macht Migration für viele Familien zu einer Notwendigkeit."]},{"heading":"Familienleben über Bildschirme","paragraphs":["Familien leben oft jahrelang getrennt, erziehen Kinder per Videoanruf und schicken Balikbayan-Boxen nach Hause. Der Staat feiert sie als bagong bayani (neue Helden), während Kritiker auf die sozialen Kosten der Trennung und die prekäre Arbeit hinweisen. Die Erfahrungen variieren stark je nach Beruf, Zielort und legalem Status; nicht jeder Migrant ist dokumentiert oder überweist regelmäßig Geld, und die Heldennarrative kann Arbeitsausbeutung verdecken."]}],"en":[{"heading":"An economy built on remittances","paragraphs":["Overseas Filipino Worker (OFW) is the official term for Filipinos who work abroad for a limited period. About 1.77 million were counted between April and September 2020. They are concentrated in domestic work, healthcare, construction, seafaring and service jobs, with large communities in the Gulf, Hong Kong, Singapore, Japan and the United States.","Remittances from OFWs are a major part of the Philippine economy. Worldwide, remittances are more than three times larger than total global foreign aid. This economic reliance makes migration a necessity for many families."]},{"heading":"Family life across screens","paragraphs":["Families often live apart for years, raising children through video calls and sending balikbayan boxes home. The state celebrates OFWs as bagong bayani (modern heroes), while critics point to the social costs of separation and precarious work. Experiences vary widely by occupation, destination and legal status; not every migrant is documented or remits regularly, and the hero narrative can hide labour abuses."]}]},"context":{"countries":[],"region":"Southeast Asia and the Gulf","community":"Overseas Filipinos","continent":"asia","languages":["tl","en"],"period":"contemporary"},"tags":["migration-and-identity","Southeast Asia and the Gulf"],"sources":[{"organization":"Wikipedia","title":{"ar":"Overseas Filipino Worker","de":"Overseas Filipino Worker","en":"Overseas Filipino Worker"},"url":"https://en.wikipedia.org/wiki/Overseas_Filipino_Worker","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Remittance","de":"Remittance","en":"Remittance"},"url":"https://en.wikipedia.org/wiki/Remittance","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"ممرضة فلبينية في دبي ترسل جزءًا من راتبها إلى الوطن، وتتصل بأطفالها بالفيديو قبل يومهم الدراسي، وتخطط لزيارة كل عامين.","de":"Eine philippinische Krankenschwester in Dubai schickt einen Teil ihres Gehalts nach Hause, video-telefoniert mit ihren Kindern vor dem Schultag und plant alle zwei Jahre einen Besuch.","en":"A Filipina nurse in Dubai sends part of each pay cheque home, video-calls her children before their school day, and plans a visit every two years."},"misunderstanding":{"ar":"الاعتقاد بأن جميع العمال الفلبينيين في الخارج يحولون المال بانتظام وأن حياتهم خالية من المشاكل.","de":"Die Annahme, dass alle OFWs regelmäßig Geld überweisen und ihre Situation problemlos ist.","en":"The assumption that all OFWs remit regularly and that their lives are free from hardship."},"comparison":{"ar":"بينما يحتفل بهم كأبطال، يسلط النقاد الضوء على التكاليف الاجتماعية للفصل والعمل غير المستقر.","de":"Während sie als Helden gefeiert werden, betonen Kritiker die sozialen Kosten der Trennung und die prekäre Arbeit.","en":"While celebrated as heroes, critics highlight the social costs of separation and precarious work."}},{"id":"tra-001","version":2,"slug":"three-glasses-one-guest-morocco-s-mint-tea-ritual","contentType":"note","category":"food-and-hospitality","title":{"ar":"ثلاثة كؤوس وضيف واحد: شاي النعناع المغربي","de":"Drei Gläser, ein Gast: Marokkos Minztee-Ritual","en":"Three glasses, one guest: Morocco's mint-tea ritual"},"deck":{"ar":"طقس الضيافة في المغرب حيث يُسكب الشاي من علو ليرتفع رغوته ويُكرَّم الضيف بثلاثة كؤوس.","de":"Gastfreundschaft in Marokko: Tee wird aus der Höhe eingeschenkt, damit sich die Krone bildet und der Gast geehrt wird.","en":"In Morocco, pouring tea from a height is a visible sign of skill and care for the guest, served in three glasses."},"teaser":{"ar":"في المغرب، الشاي بالنعناع ليس مجرد مشروب، بل لغة ضيافة تُروى بثلاثة كؤوس وسكب من علو.","de":"In Marokko ist Minztee kein Getränk, sondern eine Sprache der Gastfreundschaft – mit drei Gläsern und hohem Einschenken.","en":"In Morocco, mint tea is not just a drink but a language of hospitality, told through three glasses and a high pour."},"readingMinutes":1,"sections":{"ar":[{"heading":"فن السكب والتاج","paragraphs":["شاي النعناع المغربي، المعروف بـ«أتاي»، هو شاي أخضر بارودي يُنقع مع حفنة من النعناع الطازج والسكر، ويُقدَّم طوال اليوم في البيوت والمتاجر والمكاتب.","يسكب المضيف الشاي من ارتفاع 30-50 سم لتهوية الشاي ورفع رغوة تُسمى «التاج»، وهي علامة مرئية على المهارة والاهتمام بالضيف."]},{"heading":"ثلاثة كؤوس وحكمة الحياة","paragraphs":["يقول مثل شائع إن الكؤوس الثلاثة تُشبه الحياة: مُرّة كالحياة، قوية كالحب، لطيفة كالموت، وتكرره العائلات دون أن تعتبره قاعدة صارمة.","رفض كأس قد يُفسَّر كرفض للضيافة، بينما طلب كأس ثالثة وسيلة لتكريم المضيف. يختلف المثل ومستوى السكر وأسلوب السكب حسب العائلة والمنطقة، ونسخة الصحراء أحلى بشكل ملحوظ من الساحلية."]}],"de":[{"heading":"Die Kunst des Einschenkens","paragraphs":["Marokkanischer Minztee, Atay genannt, ist grüner Gunpowder-Tee, der mit einer Handvoll frischer Minze und Zucker aufgegossen wird und den ganzen Tag in Häusern, Läden und Büros serviert wird.","Der Gastgeber schenkt aus 30–50 cm Höhe ein, um den Tee zu belüften und einen Schaum namens Krone zu erzeugen – ein sichtbares Zeichen von Können und Fürsorge für den Gast."]},{"heading":"Drei Gläser und die Weisheit des Lebens","paragraphs":["Ein verbreiteter Spruch beschreibt die drei Gläser als bitter wie das Leben, stark wie die Liebe und sanft wie der Tod; Familien wiederholen ihn, ohne ihn als Regel zu behandeln.","Die Ablehnung eines Glases kann als Ablehnung der Gastfreundschaft gelesen werden, während ein drittes Glas den Gastgeber ehrt. Der Spruch, die Zuckermenge und der Einschenkstil variieren je nach Haushalt und Region, und die Sahara-Version ist deutlich süßer als die an der Küste."]}],"en":[{"heading":"The art of pouring and the crown","paragraphs":["Moroccan mint tea, atay, is gunpowder green tea steeped with a fistful of fresh spearmint and sugar; it is served all day, in homes, shops and offices.","The host pours from a height of 30-50 cm to aerate the tea and raise a foam called the crown, a visible mark of skill and care for the guest."]},{"heading":"Three glasses and the wisdom of life","paragraphs":["A common saying describes the three glasses served as bitter like life, strong like love and gentle like death; families repeat it without treating it as a rule.","Refusing a glass can read as refusing hospitality, while asking for a third is a way of honouring the host. The saying, sugar level and pouring style vary by household and region, and the Sahara version is noticeably sweeter than the coastal one."]}]},"context":{"countries":["MA"],"region":"Maghreb","continent":"africa","languages":["ar"],"period":"contemporary"},"tags":["food-and-hospitality","Maghreb"],"sources":[{"organization":"Wikipedia","title":{"ar":"Maghrebi mint tea","de":"Maghrebi mint tea","en":"Maghrebi mint tea"},"url":"https://en.wikipedia.org/wiki/Maghrebi_mint_tea","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Moroccan tea culture","de":"Moroccan tea culture","en":"Moroccan tea culture"},"url":"https://en.wikipedia.org/wiki/Moroccan_tea_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بائع في فاس يسكب الكأس الأولى من ارتفاع الخصر، يناولها للزبون قبل أن يسكب لنفسه، ثم يعيد ملء الإبريق لجولة ثانية أخف.","de":"Ein Ladenbesitzer in Fes schenkt das erste Glas aus Hüfthöhe ein, reicht es dem Kunden, bevor er sich selbst einschenkt, und füllt die Kanne für eine zweite, schwächere Runde nach.","en":"A shopkeeper in Fez pours the first glass from waist height, hands it to the customer before pouring his own, and refills the pot for a second, weaker round."},"misunderstanding":{"ar":"قد يظن الزائر أن رفض الكأس مجرد أدب، لكنه قد يُقرأ كرفض للضيافة نفسها.","de":"Besucher könnten glauben, ein Glas abzulehnen sei nur Höflichkeit, doch es kann als Ablehnung der Gastfreundschaft selbst verstanden werden.","en":"A visitor might think refusing a glass is just politeness, but it can be read as refusing hospitality itself."},"comparison":{"ar":"بينما يُقدَّم الشاي في المدن الساحلية أقل حلاوة، يميل أهل الصحراء إلى تحليته بشكل واضح.","de":"Während Tee in Küstenstädten weniger süß serviert wird, neigen Menschen in der Sahara zu deutlich mehr Zucker.","en":"While tea in coastal cities is served less sweet, people in the Sahara tend to sweeten it noticeably more."}},{"id":"tra-002","version":2,"slug":"lanterns-after-iftar-ramadan-nights-in-cairo","contentType":"scene","category":"traditions","title":{"ar":"فوانيس رمضان في القاهرة","de":"Laternen nach dem Iftar: Ramadan-Nächte in Kairo","en":"Lanterns after iftar: Ramadan nights in Cairo"},"deck":{"ar":"تقاليد رمضانية تضيء الشوارع والمقاهي بعد الإفطار، حيث تتحول المدينة إلى حياة ليلية.","de":"Ramadan-Traditionen erhellen nach Sonnenuntergang die Straßen und Cafés, während die Stadt zum Nachtleben erwacht.","en":"Ramadan traditions light up streets and cafés after sunset, as the city awakens to a vibrant nightlife."},"teaser":{"ar":"تتزين البلكونات والمحلات بالفوانيس الملونة، ويحمل الأطفال فوانيسهم الصغيرة مرددين أغاني رمضان.","de":"Balkone und Schaufenster schmücken sich mit bunten Laternen, und Kinder ziehen mit kleinen Fanous durch die Gassen, Ramadan-Lieder singend.","en":"Balconies and shopfronts glow with colorful lanterns, and children carry small fanous through the streets singing Ramadan songs."},"readingMinutes":1,"sections":{"ar":[{"heading":"فوانيس تروي حكاية","paragraphs":["خلال رمضان، تعلق البلكونات وواجهات المحلات في القاهرة الفوانيس المصنوعة من الزجاج الملون والتنك، فتتوهج أنماطها بعد غروب الشمس. ويروي الكثيرون أن العادة تعود إلى العصر الفاطمي، حيث استقبل السكان الخليفة بالفوانيس احتفالاً ببداية الشهر.","تقليدياً، كان الأطفال يحملون فوانيس صغيرة في الشوارع ويغنون أغاني رمضان مثل 'وهاوي يا وهاوي' طلباً للحلوى والنقود. ولا يزال الحدادون في أحياء مثل درب الأحمر يصنعون الفوانيس يدوياً، رغم أن النسخ الكهربائية المستوردة الأرخص سيطرت على جزء كبير من السوق."]},{"heading":"ليالٍ تعيد ترتيب الوقت","paragraphs":["يقلب رمضان ساعة المدينة: تمتلئ الشوارع بعد الإفطار، وتبقى المحلات مفتوحة حتى وقت متأخر، وتظل المخابز مشغولة بالوجبة السحورية حتى أذان الفجر. وتختلف هذه العادات بين الأجيال؛ فبعض الشباب يفضلون التجمع في المقاهي، بينما تحافظ العائلات على تقاليد الزيارات المنزلية."]}],"de":[{"heading":"Laternen erzählen Geschichte","paragraphs":["Während des Ramadan hängen an Balkonen und Ladenfronten in Kairo Fanous – Laternen aus buntem Glas und Blech –, deren Muster nach Sonnenuntergang leuchten. Der Brauch wird oft auf die Fatimidenzeit zurückgeführt, als die Bewohner den Kalifen zum Monatsbeginn mit Laternen begrüßten.","Traditionell trugen Kinder kleine Laternen durch die Straßen und sangen Ramadan-Lieder wie 'Wahawi ya Wahawi', um Süßigkeiten und Münzen zu erhalten. In Vierteln wie Darb al-Ahmar stellen Metallhandwerker die Laternen noch von Hand her, doch billigere importierte Elektroversionen haben einen Großteil des Marktes erobert."]},{"heading":"Nächte, die den Tag umkehren","paragraphs":["Der Ramadan stellt die Uhr der Stadt auf den Kopf: Nach dem Iftar füllen sich die Straßen, Geschäfte bleiben lange offen, und Bäckereien sind bis zum Gebetsruf mit der Suhur-Mahlzeit beschäftigt. Diese Bräuche variieren je nach Generation – manche Jugendliche treffen sich lieber in Cafés, während Familien an traditionellen Hausbesuchen festhalten."]}],"en":[{"heading":"Lanterns that tell a story","paragraphs":["During Ramadan, balconies and shopfronts across Cairo are hung with fanous, lanterns of colored glass and tin whose patterns glow after sunset. The custom is popularly traced to the Fatimid period, when residents are said to have greeted the caliph with lanterns at the start of the month.","Traditionally, children carried small lanterns through the streets and sang Ramadan songs such as 'Wahawi ya Wahawi' for sweets and coins. Metalworkers in neighborhoods like Darb al-Ahmar still make lanterns by hand, though cheaper imported electric versions have taken much of the market."]},{"heading":"Nights that flip the clock","paragraphs":["Ramadan reverses the city's clock: streets fill after iftar, shops stay open late, and bakeries remain busy with the pre-dawn meal until the call to prayer. These customs vary across generations—some youth prefer gathering in cafés, while families keep traditional home visits."]}]},"context":{"countries":["EG"],"region":"Cairo and the Nile Delta","continent":"africa","languages":["ar"],"period":"contemporary"},"tags":["traditions","Cairo and the Nile Delta"],"sources":[{"organization":"Wikipedia","title":{"ar":"Ramadan","de":"Ramadan","en":"Ramadan"},"url":"https://en.wikipedia.org/wiki/Ramadan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Fanous","de":"Fanous","en":"Fanous"},"url":"https://en.wikipedia.org/wiki/Fanous","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تعلق أسرة فانوساً جديداً من التنك فوق المدخل قبل المغرب؛ ويأخذ الأطفال فانوساً أصغر إلى الفناء ليغنوا للجيران.","de":"Eine Familie hängt vor dem Maghrib eine neue Blechlaterne über den Eingang; die Kinder nehmen eine kleinere mit in den Hof, um für die Nachbarn zu singen.","en":"A family hangs a new tin lantern above the entrance before maghrib; the children take a smaller one to the courtyard to sing for neighbors."},"misunderstanding":{"ar":"قصة الأصل الفاطمي شائعة وليست تاريخاً مؤكداً، كما تختلف أنماط الفوانيس وعادات الشارع بين القاهرة والإسكندرية والريف.","de":"Die fatimidische Ursprungsgeschichte ist eher volkstümlich als historisch gesichert, und Laternenstile sowie Straßenbräuche unterscheiden sich zwischen Kairo, Alexandria und dem ländlichen Raum.","en":"The Fatimid origin story is popular rather than firmly settled history, and lantern styles and street customs differ between Cairo, Alexandria, and the countryside."},"comparison":{"ar":"بينما تنتشر الفوانيس المستوردة الرخيصة، لا يزال الحرفيون في درب الأحمر يحافظون على صناعة الفوانيس اليدوية، مما يعكس صراعاً بين التقليد والحداثة.","de":"Während billige importierte Laternen den Markt dominieren, bewahren Handwerker in Darb al-Ahmar die handwerkliche Herstellung, was den Konflikt zwischen Tradition und Moderne widerspiegelt.","en":"While cheap imported lanterns dominate the market, artisans in Darb al-Ahmar preserve the handmade craft, reflecting a tension between tradition and modernity."}},{"id":"tra-003","version":2,"slug":"roasting-beans-in-the-front-room-ethiopia-s-coffee-ceremony","contentType":"note","category":"food-and-hospitality","title":{"ar":"تحميص البن في الصالة: طقس القهوة الإثيوبي","de":"Bohnen im Wohnzimmer rösten: Äthiopiens Kaffeeceremonie","en":"Roasting beans in the front room: Ethiopia's coffee ceremony"},"deck":{"ar":"طقس القهوة في المرتفعات الإثيوبية: تحميص البن أمام الضيوف، وثلاث جولات من القهوة، وساعة من الكرم.","de":"Die Kaffeeceremonie im äthiopischen Hochland: Rösten vor den Gästen, drei Runden Kaffee und eine Stunde Gastfreundschaft.","en":"The coffee ceremony in the Ethiopian highlands: roasting before guests, three rounds of coffee and an hour of hospitality."},"teaser":{"ar":"في المرتفعات الإثيوبية، تُحمّص حبوب البن أمام الضيوف وتُقدَّم القهوة في ثلاث جولات، في طقس يستغرق ساعة أو أكثر لتكريم الزائر.","de":"Im äthiopischen Hochland werden grüne Bohnen vor den Gästen geröstet und Kaffee in drei Runden serviert – eine Stunde oder mehr, um Besucher zu ehren.","en":"In the Ethiopian highlands, green beans are roasted before guests and coffee is served in three rounds—an hour or more to honour visitors."},"readingMinutes":1,"sections":{"ar":[{"heading":"التحميص والرائحة","paragraphs":["تقود امرأة من الأسرة طقس القهوة: تحمّص حبوب البن الخضراء على مقلاة مسطحة فوق الجمر، ثم تطوف بالمقلاة المدخنة حول الغرفة ليشم الضيوف الرائحة.","يُفرش العشب الطازج على الأرض ويُحرق البخور، وقد يستغرق الطقس بأكمله ساعة أو أكثر. وهو وسيلة لتكريم الزوار وليس مجرد شرب سريع.","يختلف الطقس حسب المنطقة والجيل: ففي المدن قد يُختصر، بينما تحافظ بعض العائلات على شكله الكامل، وتشترك إريتريا في طقس مشابه مع اختلافات محلية."]},{"heading":"الجولات الثلاث","paragraphs":["تُدق الحبوب في هاون وتُخمَّر في جرة طينية ضيقة تُسمى الجبينة، ثم تُسكب في أكواب صغيرة على ثلاث جولات: أبول، وتونا، وباراكا، والأخيرة هي البركة.","المغادرة قبل الجولة الثالثة تعتبر قلة أدب، ويُستخدم الطقس للأحاديث العائلية والمصالحات واجتماعات المجتمع بالإضافة إلى الضيوف.","يُعتبر الموطن الأصلي للبن عادة في المرتفعات الإثيوبية، رغم أن قصة الراعي كالدي هي أسطورة وليست سجلاً تاريخياً."]}],"de":[{"heading":"Rösten und Duft","paragraphs":["Eine Frau des Haushalts leitet die Zeremonie: Sie röstet grüne Bohnen auf einer flachen Pfanne über Kohlen und trägt die rauchende Pfanne durch den Raum, damit die Gäste den Duft riechen.","Frisches Gras wird auf dem Boden ausgebreitet und Weihrauch verbrannt; die ganze Abfolge kann eine Stunde oder länger dauern und ist eine Ehrung der Besucher, kein schneller Drink.","Je nach Region und Generation variiert die Zeremonie: In Städten wird sie oft verkürzt, manche Familien nutzen elektrische Mühlen, und Eritrea teilt ein eng verwandtes Ritual mit lokalen Unterschieden."]},{"heading":"Die drei Runden","paragraphs":["Die Bohnen werden im Mörser zerstoßen und in einem schmalen Tonkrug, der Jebena, gebrüht, dann in kleine Tassen in drei Runden gegossen: Abol, Tona und Baraka, wobei die letzte der Segen ist.","Vor der dritten Runde zu gehen gilt als unhöflich; die Zeremonie dient Familiengesprächen, Versöhnungen und Gemeinschaftstreffen ebenso wie Gästen.","Die Heimat des Kaffees wird meist im äthiopischen Hochland vermutet, obwohl die bekannteste Ursprungsgeschichte um den Ziegenhirten Kaldi Legende und nicht Überlieferung ist."]}],"en":[{"heading":"Roasting and aroma","paragraphs":["A woman of the household leads the ceremony: she roasts green beans on a flat pan over coals and walks the smoking pan around the room so guests can smell it.","Fresh grass is spread on the floor and incense burned; the whole sequence can take an hour or more and is a way of honouring visitors rather than a quick drink.","The ritual varies by region and generation: urban offices often shorten it, some families use electric grinders, and Eritrea shares a closely related ritual with local variations."]},{"heading":"The three rounds","paragraphs":["The beans are pounded in a mortar and brewed in a narrow clay pot, the jebena, then poured into small cups in three rounds known as abol, tona and baraka, the last being the blessing.","Leaving before the third round is impolite, and the ceremony is used for family talks, reconciliations and community meetings as well as for guests.","Coffee's birthplace is usually placed in the Ethiopian highlands, although the best-known origin story about the goatherd Kaldi is legend rather than record."]}]},"context":{"countries":["ET"],"region":"Ethiopian highlands","continent":"africa","languages":["am"],"period":"contemporary"},"tags":["food-and-hospitality","Ethiopian highlands"],"sources":[{"organization":"Wikipedia","title":{"ar":"Coffee ceremony","de":"Coffee ceremony","en":"Coffee ceremony"},"url":"https://en.wikipedia.org/wiki/Coffee_ceremony","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Ethiopia","de":"Culture of Ethiopia","en":"Culture of Ethiopia"},"url":"https://en.wikipedia.org/wiki/Culture_of_Ethiopia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يصل زائر دون موعد مسبق في أديس أبابا؛ خلال عشرين دقيقة تخرج المقلاة، وتمتلئ الغرفة برائحة البن المحمص، ويُمرَّر أول فنجان صغير على صينية.","de":"Ein Gast kommt unangekündigt in Addis Abeba an; innerhalb von zwanzig Minuten steht die Pfanne bereit, das Zimmer riecht nach Röstkaffee, und die erste kleine Tasse wird auf einem Tablett herumgereicht.","en":"A visitor arrives unannounced in Addis Ababa; within twenty minutes the pan is out, the room smells of roasting coffee and the first small cup is passed on a tray."},"misunderstanding":{"ar":"قد يظن الزائر أن الطقس مجرد استراحة قصيرة لتناول القهوة، لكنه في الواقع مناسبة كاملة للكرم وقد يستغرق ساعة أو أكثر.","de":"Manche halten die Zeremonie für eine kurze Kaffeepause, doch sie ist ein voller Akt der Gastfreundschaft und kann eine Stunde oder länger dauern.","en":"Some visitors think the ceremony is just a quick coffee break, but it is a full act of hospitality that can take an hour or more."},"comparison":{"ar":"بينما تُقدَّم القهوة سريعاً في كثير من الثقافات، فإن الطقس الإثيوبي يبطئ الإيقاع ويجعل من التحميص والرائحة والجولات الثلاث جزءاً من الضيافة.","de":"Während Kaffee in vielen Kulturen schnell serviert wird, verlangsamt die äthiopische Zeremonie das Tempo und macht Rösten, Duft und drei Runden zum Teil der Gastlichkeit.","en":"While coffee is served quickly in many cultures, the Ethiopian ceremony slows the pace and makes roasting, aroma and three rounds part of the welcome."}},{"id":"tra-004","version":2,"slug":"your-birthday-is-part-of-your-name-akan-day-names","contentType":"note","category":"family-and-friendship","title":{"ar":"اسمك يحمل يوم ميلادك عند الأكان","de":"Dein Geburtstag steckt in deinem Namen","en":"Your birthday lives inside your name"},"deck":{"ar":"في غانا، يمنح اسم اليوم الطفل هوية تربطه بيوم ولادته وبقوة حياته.","de":"Bei den Akan in Ghana bestimmt der Wochentag der Geburt den Rufnamen und verweist zugleich auf die Lebenskraft.","en":"Among the Akan in Ghana, the weekday of birth becomes a lifelong name used in everyday address."},"teaser":{"ar":"عند الأكان في غانا، يُطلق على الطفل اسم اليوم الذي وُلد فيه، فيصبح الاسم علامة على التاريخ وعلى الشخصية معًا.","de":"Akan-Kinder in Ghana erhalten einen Tagesnamen, der an den Wochentag der Geburt erinnert und im Alltag wie eine kurze Lebensgeschichte wirkt.","en":"Akan children in Ghana receive a day name that recalls the weekday of birth and shapes how neighbours, relatives and colleagues greet them."},"readingMinutes":1,"sections":{"ar":[{"heading":"اسم اليوم في الحياة اليومية","paragraphs":["يحمل معظم أطفال الأكان اسمًا من أيام الأسبوع يُعرف بـ«كرادين»، فالصبي المولود يوم السبت يُدعى كوامي، والفتاة المولودة في اليوم نفسه تُدعى أما، ومن وُلد يوم الأربعاء يُسمى كواكو.","يُستخدم هذا الاسم في النداء اليومي داخل الأسرة والحي، ويرتبط في المعتقد الأكاني بروح الطفل «كرا» وبصفات يُتوقع أن تظهر عليه.","تختلف صيغ الأسماء بين تقاليد أسانتي وفانتي وأكوابيم، فقد يحمل يوم الأربعاء نفسه أكثر من شكل حسب الجماعة، كما تتباين العادات بين الأجيال والمناطق."]},{"heading":"الاحتفال والتسمية أمام الشهود","paragraphs":["تحتفل كثير من العائلات الأكانية في اليوم الثامن بعد الولادة بطقس «إخراج الطفل»، حيث يُخرج للمرة الأولى ويُسمّى أمام الشهود ويُذاق الماء وغيره من المذاقات الرمزية.","يحمل معظم الغانيين أيضًا اسمًا مسيحيًا أو إسلاميًا، فيجمع الاسم الكامل بين اسم أوروبي واسم يوم واسم عائلة.","هذا النظام خاص بالجماعات الناطقة بالأكانية وليس عادة غانية وطنية، فمجتمعات غانية أخرى تتبع قواعد تسمية مختلفة."]}],"de":[{"heading":"Der Tagesname im Alltag","paragraphs":["Die meisten Akan-Kinder tragen einen Wochentagsnamen, den kradin: Ein am Samstag geborener Junge heißt Kwame, ein am Samstag geborenes Mädchen Ama, ein Mittwochskind Kwaku.","Dieser Name wird täglich in der Familie und im Viertel benutzt und ist im Akan-Glauben mit der kra, der Lebenskraft des Kindes, und mit erwarteten Charakterzügen verbunden.","Die Namensformen unterscheiden sich zwischen Asante-, Fante- und Akuapem-Traditionen; derselbe Wochentag hat je nach Gruppe andere Gestalt, und auch zwischen Generationen und Regionen zeigen sich Unterschiede."]},{"heading":"Namensgebung vor Zeugen","paragraphs":["Viele Akan-Familien feiern am achten Tag nach der Geburt ein Outdooring, bei dem das Kind erstmals hinausgebracht, vor Zeugen benannt und mit Wasser und anderen symbolischen Kostproben bedacht wird.","Die meisten Ghanaer tragen zusätzlich einen christlichen oder muslimischen Vornamen, sodass ein vollständiger Name einen europäischen Namen, einen Tagesnamen und einen Familiennamen verbinden kann.","Das Tagesnamensystem gehört den Akan-sprachigen Gruppen und ist kein ghanaischer Nationalbrauch; andere ghanaische Gemeinschaften folgen eigenen Namensregeln."]}],"en":[{"heading":"The day name in daily life","paragraphs":["Most Akan children receive a weekday name, the kradin: a boy born on Saturday is Kwame, a girl born on Saturday is Ama, and a Wednesday child is Kwaku.","The name is used in everyday address within the family and neighbourhood, and in Akan belief it is tied to the child's kra, the life force or soul, and to expected character traits.","Name forms vary between Asante, Fante and Akuapem traditions, so the same weekday takes different shapes across groups, and customs also shift between generations and regions."]},{"heading":"Naming before witnesses","paragraphs":["Many Akan families hold an outdooring ceremony on the eighth day after birth, when the child is brought outside for the first time, named before witnesses and given water and other symbolic tastes.","Most Ghanaians also carry a Christian or Muslim given name, so a full name may combine a European name, a day name and a family name.","The day-name system belongs to Akan-speaking groups and is not a national Ghanaian custom; other Ghanaian communities follow different naming rules."]}]},"context":{"countries":["GH"],"region":"Ashanti and southern Ghana","community":"Akan","continent":"africa","languages":["ak","en"],"period":"contemporary"},"tags":["family-and-friendship","Ashanti and southern Ghana"],"sources":[{"organization":"Wikipedia","title":{"ar":"Akan names","de":"Akan names","en":"Akan names"},"url":"https://en.wikipedia.org/wiki/Akan_names","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Akan people","de":"Akan people","en":"Akan people"},"url":"https://en.wikipedia.org/wiki/Akan_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"زميل جديد يقدّم نفسه باسم كوابينا، فيعرف الجميع فورًا أنه وُلد يوم الثلاثاء ويمكنهم تحيته بالمثل المناسب.","de":"Ein neuer Kollege stellt sich als Kwabena vor, und alle im Büro wissen sofort, dass er an einem Dienstag geboren wurde, und können ihn mit dem passenden Sprichwort begrüßen.","en":"A new colleague introduces himself as Kwabena, and everyone in the office instantly knows he was born on a Tuesday and can greet him with the matching proverb."},"misunderstanding":{"ar":"يظن بعض الزوار أن اسم اليوم مجرد لقب عائلي، لكنه في الحقيقة يشير إلى يوم الولادة ويرتبط بفكرة الروح والطبع.","de":"Manche Besucher halten den Tagesnamen für einen Familiennamen, doch er bezeichnet den Geburtstag und verweist auf Vorstellungen von Seele und Wesen.","en":"Some visitors assume the day name is a surname, but it marks the weekday of birth and connects to ideas about soul and temperament."},"comparison":{"ar":"يشبه هذا العرف المجتمعات التي تربط الاسم بتاريخ الميلاد، لكنه هنا نظام متكامل يمتد إلى المعتقد والتحية اليومية.","de":"Ähnlich wie Kulturen, die den Namen an das Geburtsdatum knüpfen, verbindet das Akan-System Name, Glauben und tägliche Begrüßung.","en":"Like cultures that tie names to birth dates, the Akan system links name, belief and everyday greeting into one habit."}},{"id":"tra-005","version":2,"slug":"know-me-know-you-how-a-yoruba-marriage-is-negotiated","contentType":"note","category":"family-and-friendship","title":{"ar":"كيف يُعقد الزواج عند اليوروبا","de":"Wie eine Yoruba-Hochzeit ausgehandelt wird","en":"Know me, know you: a Yoruba marriage"},"deck":{"ar":"قبل أن يُقال نعم، تتحقق عائلتان من أخلاق إحداهما والأخرى، ثم تُقدَّم الهدايا الرمزية ويُبارَك الاتحاد.","de":"Bevor ein Ja fällt, prüfen zwei Familien den Charakter der jeweils anderen, dann werden symbolische Gaben übergeben und gesegnet.","en":"Before anyone says yes, two families check each other's character, then symbolic goods are laid out and blessed."},"teaser":{"ar":"في بلاد اليوروبا بجنوب غرب نيجيريا، يمر الزواج بمراحل تُعرف فيها العائلتان إحداهما الأخرى قبل أن يعرف العروسان بعضهما.","de":"Im Yorubaland im Südwesten Nigerias durchläuft eine Hochzeit Stufen, in denen sich die Familien kennenlernen, bevor das Paar einander näherkommt.","en":"In Yorubaland, south-west Nigeria, a marriage moves through stages where the families get to know each other before the couple do."},"readingMinutes":1,"sections":{"ar":[{"heading":"من التعارف إلى الإيدانا","paragraphs":["يبدأ الزواج التقليدي عند اليوروبا بمرحلة التعارف، حين تلتقي العائلتان وتعلنان نيّتهما. ثم تأتي مرحلة الإيدانا، أي الخطوبة، حين تقبل عائلة العروس العريس رسميًا.","بين المرحلتين تتحرى العائلتان أخلاق الطرف الآخر وصحته وسمعته وأصله، وهو ما يُختصر في عبارة: اعرف العائلة قبل أن تتزوج الشخص.","تختلف التسلسل والهدايا وحجم الاحتفال بين المجموعات الفرعية اليوروبية، وبين العائلات المسلمة والمسيحية، وبين بيوت الريف والمدينة."]},{"heading":"هدايا رمزية وصلوات","paragraphs":["في الخطوبة تحضر عائلة العريس مواد رمزية قد تشمل جوز الكولا والكولا المرة والعسل والملح والسمك وكتابًا مقدسًا، وتُعرض لتفحصها عائلة العروس وتباركها.","يسجد العريس وأصدقاؤه أمام والدي العروس، وتقدّم عائلة العروس الصلوات والنصائح، وغالبًا ما يرتدي العروسان أزو إبي، وهو قماش موحّد تختاره كل عائلة.","تُقام مراسم الكنيسة أو المسجد وتسجيل الزواج عادة في مناسبات منفصلة، لذا يحتفل كثير من الأزواج بمناسبتين أو ثلاث في أيام مختلفة."]}],"de":[{"heading":"Von der Vorstellung zur idana","paragraphs":["Traditionell beginnt eine Yoruba-Hochzeit mit der Vorstellung, bei der beide Familien zusammenkommen und ihre Absichten erklären. Danach folgt die Verlobung, idana, bei der die Familie der Braut den Bräutigam förmlich annimmt.","Zwischen diesen Stufen prüfen beide Familien Charakter, Gesundheit, Ruf und Herkunft der anderen Seite – oft zusammengefasst als: erst die Familie kennen, dann die Person heiraten.","Ablauf, Gaben und Größe des Festes unterscheiden sich je nach Yoruba-Untergruppe, zwischen muslimischen und christlichen Familien sowie zwischen ländlichen und städtischen Haushalten."]},{"heading":"Symbolische Gaben und Gebete","paragraphs":["Bei der Verlobung bringt die Familie des Bräutigams symbolische Gaben mit, darunter Kolanuss, Bitterkola, Honig, Salz, Fisch und ein heiliges Buch, die zur Prüfung und zum Segen ausgelegt werden.","Der Bräutigam und seine Freunde werfen sich vor den Eltern der Braut nieder, die Familie der Braut spendet Gebete und Ratschläge; oft tragen beide aso ebi, einen von jeder Familie gewählten Stoff.","Kirchliche oder moscheeische Trauung und Standesamt finden meist getrennt statt, sodass viele Paare an verschiedenen Tagen zwei oder drei Feste feiern."]}],"en":[{"heading":"From introduction to idana","paragraphs":["A Yoruba marriage traditionally begins with the introduction, when both families meet and state their intentions. Then comes the engagement, idana, when the bride's family formally accepts the groom.","Between those stages the two families investigate each other's character, health, reputation and background, a process often summarised as knowing the family before marrying the person.","The sequence, the goods and the scale of the event differ between Yoruba subgroups, Muslim and Christian families, and rural and city households."]},{"heading":"Symbolic goods and prayers","paragraphs":["At the engagement the groom's family brings symbolic goods that may include kola nut, bitter kola, honey, salt, fish and a holy book, laid out for the bride's family to inspect and bless.","The groom and his friends prostrate before the bride's parents, who offer prayers and advice; the couple often wear aso ebi, matching cloth chosen by each family.","Church or mosque solemnisation and a registry ceremony are usually held separately, so many couples celebrate two or three events on different days."]}]},"context":{"countries":["NG"],"region":"Yorubaland, south-west Nigeria","community":"Yoruba","continent":"africa","languages":["yo","en"],"period":"contemporary"},"tags":["family-and-friendship","Yorubaland, south-west Nigeria"],"sources":[{"organization":"Wikipedia","title":{"ar":"Yoruba culture","de":"Yoruba culture","en":"Yoruba culture"},"url":"https://en.wikipedia.org/wiki/Yoruba_culture","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Marriage in Nigeria","de":"Marriage in Nigeria","en":"Marriage in Nigeria"},"url":"https://en.wikipedia.org/wiki/Marriage_in_Nigeria","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في حفل خطوبة في إبادان، يجثو أبناء عمومة العريس حاملين صواني الكولا والعسل بينما تتحقق عمة من القائمة ويمنح والد العروس البركة الأخيرة.","de":"Bei einer Verlobung in Ibadan knien die Cousins des Bräutigams mit Tabletts voller Kola und Honig, während eine Tante die Liste prüft und der Vater der Braut den letzten Segen gibt.","en":"At an engagement in Ibadan, the groom's cousins kneel with trays of kola and honey while an aunt checks the list and the bride's father gives the final blessing."},"misunderstanding":{"ar":"يظن بعض من لم يعتاد هذه العادات أن التحقق من العائلة تدخّل أو شك، لكنه في السياق اليوروبي عناية تُبنى عليها الثقة بين العائلتين.","de":"Wer die Sitte nicht kennt, hält das Prüfen der Familie für Misstrauen oder Einmischung; im Yoruba-Kontext ist es Fürsorge, auf der das Vertrauen zwischen beiden Familien ruht.","en":"Outsiders sometimes read the checking of family as suspicion or interference, but here it is care on which the trust between two families is built."},"comparison":{"ar":"يشبه هذا التدرّج ما يحدث في مجتمعات أخرى حين يسبق الزواج لقاء العائلتين، لكن ما يميزه هنا أن الهدايا الرمزية تُعرض وتُبارَك علنًا قبل إعلان القبول.","de":"Ähnlich wie in anderen Gesellschaften geht auch hier der Hochzeit ein Treffen der Familien voraus, doch die offene Prüfung und der Segen der symbolischen Gaben sind besonders.","en":"Other societies also bring families together before a wedding, but the open inspection and blessing of symbolic goods give this negotiation its own shape."}},{"id":"tra-006","version":2,"slug":"harambee-who-pays-when-a-kenyan-community-has-a-need","contentType":"note","category":"cities-and-community","title":{"ar":"هارامبي: من يدفع عندما تحتاج جماعة كينية","de":"Harambee: Wer zahlt, wenn eine kenianische Gemeinde Hilfe braucht","en":"Harambee: who pays when a Kenyan community has a need"},"deck":{"ar":"في كينيا، يجتمع الناس لتمويل رسوم مدرسية أو جنازات أو مشاريع ماء، ويُعلَن اسم كل متبرع ومبلغه أمام الجميع.","de":"In Kenia kommen Menschen zusammen, um Schulgeld, Beerdigungen oder Wasserprojekte zu finanzieren – jeder Name und Betrag wird öffentlich verkündet.","en":"In Kenya people gather to fund school fees, funerals or water projects, and each donor's name and amount is announced in public."},"teaser":{"ar":"هارامبي نداء سواحيلي يعني «لنجرّ جميعاً معاً»، ويسمّي العمل الجماعي ولقاءات جمع المال التي تسدّ حاجة المجتمع.","de":"Harambee ist ein Swahili-Ruf und bedeutet „alle ziehen zusammen“; er bezeichnet Gemeinschaftsarbeit und die Spendentreffen, die eine Notlage bezahlen.","en":"Harambee is a Swahili call meaning 'all pull together', naming both communal work and the fundraising meetings that pay for a need."},"readingMinutes":1,"sections":{"ar":[{"heading":"نداء يجمع الناس","paragraphs":["هارامبي تعبير سواحيلي يعني «لنجرّ جميعاً معاً»، ويسمّي العمل الجماعي ولقاءات جمع المال التي تدفع ثمن حاجة. من الأسباب الشائعة الرسوم المدرسية والجنازات وفواتير المستشفى وبناء الكنائس ومشاريع الماء؛ ويحدّد المنظمون هدفاً ويدعون الأقارب والزملاء والجيران.","في لقاء هارامبي ينادي مقدم الحفل المتبرعين بأسمائهم ويعلن كل مبلغ، فينشأ سجل علني وحافز اجتماعي قوي للعطاء. وقد روج جومو كينياتا لهذه الممارسة بعد الاستقلال عام 1963 كأخلاق لبناء الأمة، وهي جزء من الشعار الوطني الكيني."]},{"heading":"بين التضامن والضغط","paragraphs":["يلاحظ الباحثون والصحافيون أن التعهد العلني قد يضع ضغطاً على الأسر الأفقر، وأن السياسيين يستخدمون هارامبي أحياناً لبناء شبكات المصالح. وتختلف الممارسة اختلافاً كبيراً بين جماعات المساعدة الذاتية الريفية والمكاتب الحضرية والتجمعات السياسية، وليس كل كيني يؤيد نموذج التعهد العلني."]}],"de":[{"heading":"Ein Ruf, der Menschen versammelt","paragraphs":["Harambee ist ein Swahili-Ruf und bedeutet „alle ziehen zusammen“; er bezeichnet sowohl Gemeinschaftsarbeit als auch die Spendentreffen, die eine Notlage bezahlen. Häufige Anlässe sind Schulgeld, Beerdigungen, Krankenhausrechnungen, Kirchenbau und Wasserprojekte; die Organisatoren setzen ein Ziel und laden Verwandte, Kollegen und Nachbarn ein.","Bei einem Harambee ruft ein Moderator die Spender beim Namen auf und verkündet jeden Betrag, wodurch ein öffentliches Verzeichnis und ein starker sozialer Anreiz zum Geben entstehen. Jomo Kenyatta förderte die Praxis nach der Unabhängigkeit 1963 als Ethik des Nation-Buildings, und „harambee“ gehört zum kenianischen Wahlspruch."]},{"heading":"Zwischen Solidarität und Druck","paragraphs":["Wissenschaftler und Journalisten merken an, dass öffentliches Zusagen Druck auf ärmere Haushalte erzeugen kann und Politiker Harambee manchmal zum Aufbau von Patronage nutzen. Die Praxis unterscheidet sich stark zwischen ländlichen Selbsthilfegruppen, städtischen Büros und politischen Kundgebungen, und nicht jeder Kenianer unterstützt das Modell der öffentlichen Zusage."]}],"en":[{"heading":"A call that gathers people","paragraphs":["Harambee is a Swahili call meaning 'all pull together', and it names both communal work and the fundraising meetings that pay for a need. Common causes are school fees, funerals, hospital bills, church building and water projects; organisers set a target and invite relatives, colleagues and neighbours.","At a harambee, an MC calls donors by name and announces each amount, producing a public record and a strong social incentive to give. Jomo Kenyatta promoted the practice after independence in 1963 as a nation-building ethic, and 'harambee' is part of Kenya's national motto."]},{"heading":"Between solidarity and pressure","paragraphs":["Scholars and journalists note that public pledging can create pressure on poorer households, and politicians sometimes use harambee to build patronage. The practice takes very different forms in rural self-help groups, urban offices and political rallies, and not every Kenyan supports the public-pledge model."]}]},"context":{"countries":["KE"],"region":"Kenya","continent":"africa","languages":["sw","en"],"period":"contemporary"},"tags":["cities-and-community","Kenya"],"sources":[{"organization":"Wikipedia","title":{"ar":"Harambee","de":"Harambee","en":"Harambee"},"url":"https://en.wikipedia.org/wiki/Harambee","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Kenya","de":"Culture of Kenya","en":"Culture of Kenya"},"url":"https://en.wikipedia.org/wiki/Culture_of_Kenya","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يتوفى والد زميل، فتنشر مجموعة واتساب المكتب موعد هارامبي؛ ويوم السبت يجتمع الناس في قاعة، ويقرأ مقدم الحفل الأسماء في ميكروفون، ثم يُعلن المجموع في النهاية.","de":"Der Vater eines Kollegen stirbt, und die WhatsApp-Gruppe des Büros nennt einen Harambee-Termin; am Samstag versammeln sich die Leute in einer Halle, ein Moderator liest Namen ins Mikrofon, und am Ende wird die Gesamtsumme verkündet.","en":"A colleague's father dies and the office WhatsApp group posts a harambee date; on Saturday people gather in a hall, an MC reads names into a microphone and the total is announced at the end."},"misunderstanding":{"ar":"الانطباع بأن الجميع يشاركون بحماس متساوٍ مضلل؛ فبعض الناس يجدون في الإعلان العلني للمبالغ ضغطاً ثقيلاً على ميزانيتهم.","de":"Die Annahme, alle beteiligten sich mit gleicher Begeisterung, täuscht; manche empfinden die öffentliche Nennung der Beträge als schweren Druck auf ihr Budget.","en":"It is misleading to assume everyone takes part with equal enthusiasm; some experience the public announcement of amounts as heavy pressure on their budget."},"comparison":{"ar":"يشبه هارامبي جمعيات المساعدة المتبادلة في أماكن أخرى، لكن ما يميزه هو الإعلان العلني للمبلغ والاسم أمام الحاضرين.","de":"Harambee ähnelt Nachbarschaftskassen anderswo, doch besonders ist die öffentliche Verkündung von Name und Betrag vor allen Anwesenden.","en":"Harambee resembles mutual-aid pots elsewhere, but what stands out is the public announcement of name and amount in front of everyone present."}},{"id":"tra-007","version":2,"slug":"umuganda-the-last-saturday-morning-in-rwanda","contentType":"note","category":"cities-and-community","title":{"ar":"أوموغاندا: صباح السبت الأخير في رواندا","de":"Umuganda: Der letzte Samstagmorgen in Ruanda","en":"Umuganda: The Last Saturday Morning in Rwanda"},"deck":{"ar":"يوم عمل مجتمعي يُنظَّم رسميًا من الثامنة إلى الحادية عشرة، يجمع الجيران لتنظيف الطرق وبناء المنازل وزراعة الأشجار.","de":"Ein gemeinschaftlicher Arbeitstag, offiziell von 8 bis 11 Uhr, an dem Nachbarn Straßen reinigen, Häuser bauen oder Bäume pflanzen.","en":"A community work day held officially from 8 to 11 a.m., when residents clean roads, build houses, or plant trees together."},"teaser":{"ar":"في كل سبت أخير من الشهر، تتحول الأحياء الرواندية إلى ورشة عمل جماعية، تليها جلسة حوار حول مشكلات الحي.","de":"Jeden letzten Samstag im Monat verwandeln sich ruandische Viertel in eine gemeinsame Werkstatt, gefolgt von einer kurzen Bürgerversammlung.","en":"On the last Saturday of each month, Rwandan neighbourhoods turn into shared worksites, followed by a short meeting on local problems."},"readingMinutes":1,"sections":{"ar":[{"heading":"عمل مشترك صباح السبت","paragraphs":["أوموغاندا هو يوم عمل مجتمعي يُعقد في السبت الأخير من كل شهر، رسميًا من الثامنة إلى الحادية عشرة صباحًا. خلاله ينظف السكان الطرق، ويبنون المنازل، أو يزرعون الأشجار. تتولى السلطات المحلية تنظيم المهام، والمشاركة إلزامية رسميًا؛ ويمكن معاقبة الغياب من قبل المسؤولين المحليين أو إثارته عند طلب السكان لبعض الخدمات.","بعد العمل، يعقد الجيران اجتماعًا قصيرًا تقدم فيه السلطات معلومات وتطرح فيه المشاكل المحلية. الكلمة تعني التجمع من أجل هدف مشترك؛ والممارسة مستمدة من تقاليد عمل جماعي أقدم ولكنها أُضفيت عليها صفة السياسة الوطنية في العقد الأول من الألفية."]},{"heading":"بين السياسة والمجتمع","paragraphs":["يُروَّج لأوموغاندا كأحد الحلول المحلية الرواندية للنظافة والبنية التحتية والتماسك الاجتماعي، ويُستخدم أيضًا لتعبئة الدعم للبرامج الحكومية. تختلف المشاركة حسب المنطقة والجيل؛ ففي المناطق الحضرية يشارك الشباب بحماس أكبر، بينما في الريف تُدمج الممارسة مع أنشطة زراعية موسمية."]}],"de":[{"heading":"Gemeinsame Arbeit am Samstagmorgen","paragraphs":["Umuganda ist ein gemeinschaftlicher Arbeitstag, der am letzten Samstag jedes Monats stattfindet, offiziell von 8 bis 11 Uhr morgens. Die Bewohner reinigen Straßen, bauen Häuser oder pflanzen Bäume. Die lokalen Behörden organisieren die Aufgaben, und die Teilnahme ist offiziell verpflichtend; Fernbleiben kann von lokalen Beamten sanktioniert oder bei der Beantragung bestimmter Dienstleistungen zur Sprache gebracht werden.","Nach der Arbeit halten die Nachbarn eine kurze Versammlung ab, bei der Beamte Informationen geben und Anwohner lokale Probleme ansprechen. Das Wort bedeutet, für einen gemeinsamen Zweck zusammenzukommen; die Praxis stützt sich auf ältere gemeinschaftliche Arbeitstraditionen, wurde aber in den 2000er Jahren als nationale Politik formalisiert."]},{"heading":"Zwischen Politik und Gesellschaft","paragraphs":["Umuganda wird als eine der einheimischen Lösungen Ruandas für Sauberkeit, Infrastruktur und sozialen Zusammenhalt beworben und auch genutzt, um Unterstützung für Regierungsprogramme zu mobilisieren. Die Teilnahme variiert regional und generationell; in städtischen Gebieten engagieren sich junge Menschen oft stärker, während in ländlichen Gebieten die Praxis mit saisonaler Landarbeit verbunden wird."]}],"en":[{"heading":"Working Together on Saturday Morning","paragraphs":["Umuganda is a community work day held on the last Saturday of each month, officially from 8 to 11 in the morning, when residents clean roads, build houses or plant trees. Local authorities organise the tasks and participation is officially mandatory; non-attendance can be sanctioned by local officials or raised when residents request certain services.","After the work, neighbours hold a short meeting where officials give information and residents raise local problems. The word means coming together for a common purpose; the practice draws on older communal work traditions but was formalised as national policy in the 2000s."]},{"heading":"Between Policy and Community","paragraphs":["It is promoted as one of Rwanda's homegrown solutions for cleanliness, infrastructure and social cohesion, and it is also used to mobilise support for government programmes. Participation varies by region and generation; in urban areas young people often join more actively, while in rural areas the practice blends with seasonal farming activities."]}]},"context":{"countries":["RW"],"region":"Rwanda","continent":"africa","languages":["rw","fr","en"],"period":"contemporary"},"tags":["cities-and-community","Rwanda"],"sources":[{"organization":"Wikipedia","title":{"ar":"Umuganda","de":"Umuganda","en":"Umuganda"},"url":"https://en.wikipedia.org/wiki/Umuganda","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Rwanda","de":"Culture of Rwanda","en":"Culture of Rwanda"},"url":"https://en.wikipedia.org/wiki/Culture_of_Rwanda","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في السبت الأخير من الشهر، يقوم حي في كيغالي بتنظيف قناة تصريف معًا، ثم يجلسون على كراسي بلاستيكية لاجتماع حول نقطة مياه معطلة.","de":"Am letzten Samstag des Monats reinigt eine Nachbarschaft in Kigali gemeinsam einen Entwässerungskanal und setzt sich dann auf Plastikstühle zu einer Besprechung über eine defekte Wasserstelle.","en":"On the last Saturday of the month, a Kigali neighbourhood clears a drainage channel together, then sits on plastic chairs for a meeting about a broken water point."},"misunderstanding":{"ar":"المشاركة ليست طوعية بالكامل، وقد انتقدت منظمات حقوق الإنسان تطبيقها، لذا ينبغي وصفها بأنها سياسة رسمية وممارسة اجتماعية في آن واحد.","de":"Die Teilnahme ist nicht rein freiwillig, und Menschenrechtsorganisationen haben die Durchsetzung kritisiert; daher sollte sie sowohl als offizielle Politik als auch als soziale Praxis beschrieben werden.","en":"Participation is not purely voluntary, and human-rights organisations have criticised enforcement, so it should be described as official policy as well as a social practice."},"comparison":{"ar":"على غرار أيام العمل التطوعي في بعض الدول، لكن أوموغاندا يتميز بطابع إلزامي رسمي وربط بين العمل والاجتماع المحلي.","de":"Ähnlich wie Freiwilligentage in anderen Ländern, doch Umuganda zeichnet sich durch offizielle Verpflichtung und die Verbindung von Arbeit und lokaler Versammlung aus.","en":"Similar to volunteer work days in other countries, but Umuganda stands out for its official mandatory nature and the link between work and local meetings."}},{"id":"tra-008","version":2,"slug":"famadihana-when-highland-malagasy-families-rewrap-their-dead","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"فاماديهانا: حين يعيد سكان المرتفعات لفّ موتاهم","de":"Famadihana: Wenn Hochlandfamilien ihre Toten neu wickeln","en":"Famadihana: When Highland Malagasy Families Rewrap Their Dead"},"deck":{"ar":"طقس ميرينا وبيتسيلو حيث تُفتح المقابر ويُعاد لفّ الأسلاف في ثوب جديد، وسط رقص وموسيقى وولائم.","de":"Ein Merina- und Betsileo-Ritual, bei dem Gräber geöffnet und Vorfahren in neuen Stoff gehüllt werden – mit Tanz, Musik und Festmahl.","en":"A Merina and Betsileo ritual where tombs are opened and ancestors are rewrapped in fresh cloth, with dancing, music and a shared meal."},"teaser":{"ar":"في مرتفعات مدغشقر، تفتح بعض العائلات قبور أسلافها كل خمس إلى سبع سنوات، وتعید لفّ رفاتهم في ثوب حريري جديد، احتفاءً بهم.","de":"Im Hochland von Madagaskar öffnen manche Familien alle fünf bis sieben Jahre die Gräber ihrer Vorfahren, wickeln die Gebeine in frische Seide und feiern sie.","en":"In the highlands of Madagascar, some families open their ancestors' tombs every five to seven years, rewrap the remains in fresh silk and celebrate them."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس التحويل والاحتفال","paragraphs":["فاماديهانا، أو 'تحويل العظام'، هو طقس في مرتفعات مدغشقر حيث تفتح الأسرة القبر، وتخرج رفات الأسلاف، وتعيد لفّها في قماش لامبا جديد. يُقام عادةً كل خمس إلى سبع سنوات في موسم الجفاف من يوليو إلى سبتمبر، ولكن بسبب تكلفته العالية قد تؤجل بعض العائلات إقامته لسنوات.","تُحمل الرفات الملفوفة ويُرقص بها على أنغام الموسيقى الحية، وتشارك الأسرة في شرب الروم وتناول وجبة كبيرة. وكثيرًا ما تكون الأجواء مفعمة بالفرح بدلًا من الحزن."]},{"heading":"إشراك الأسلاف في حياة الأحياء","paragraphs":["يعبّر الطقس عن الاعتقاد بأن الأسلاف، 'رازانا'، يظلون مشاركين في حياة الأحياء ويجب تكريمهم وإبقاؤهم على علم بأخبار الأسرة. بعض الكنائس المسيحية والسلطات الصحية شجعت على التخلي عن هذه الممارسة، واليوم يمارسها بعض عائلات ميرينا وبيتسيلو وليس جميع المالغاشيين. وتختلف الممارسة أيضًا بين الأجيال، فبعض الشباب يشارك بحماس بينما يبتعد آخرون."]}],"de":[{"heading":"Das Ritual des Wendens und Feierns","paragraphs":["Famadihana, die „Wendung der Knochen“, ist eine Zeremonie im Hochland von Madagaskar, bei der eine Familie das Grab öffnet, die Gebeine der Vorfahren herausnimmt und sie in frischen Lamba-Stoff wickelt. Sie findet meist alle fünf bis sieben Jahre in der Trockenzeit von Juli bis September statt, doch wegen der hohen Kosten verschieben manche Familien sie um Jahre.","Die gewickelten Überreste werden getragen und zu Live-Musik mit ihnen getanzt, die Familie teilt Rum und ein großes Essen. Die Stimmung ist oft fröhlich statt traurig."]},{"heading":"Die Vorfahren am Leben beteiligen","paragraphs":["Der Ritus drückt den Glauben aus, dass die Vorfahren, razana, am Leben der Lebenden beteiligt bleiben und geehrt sowie informiert werden müssen. Einige christliche Kirchen und Gesundheitsbehörden haben die Praxis abgelehnt, und heute wird sie von manchen Merina- und Betsileo-Familien gepflegt, nicht von allen Madagassen. Auch zwischen den Generationen gibt es Unterschiede: Manche Jüngere machen begeistert mit, andere distanzieren sich."]}],"en":[{"heading":"The Rite of Turning and Celebrating","paragraphs":["Famadihana, the turning over of the bones, is a highland ceremony in which a family opens the tomb, lifts out ancestors' remains and rewraps them in fresh lamba cloth. It is usually held every five to seven years in the dry season from July to September, and because it is expensive families may postpone it for years.","The wrapped remains are carried and danced with to live music, and the family shares rum and a large meal; the mood is often joyful rather than mournful."]},{"heading":"Keeping Ancestors Involved","paragraphs":["The rite expresses the belief that ancestors, razana, remain involved in the lives of the living and must be honoured and kept informed. Some Christian churches and health authorities have discouraged the practice, and today it is kept by some Merina and Betsileo families rather than by all Malagasy people. Practice also varies by generation: some younger people join enthusiastically, while others distance themselves."]}]},"context":{"countries":["MG"],"region":"Madagascar highlands","community":"Merina and Betsileo families","continent":"africa","languages":["mg","fr"],"period":"contemporary"},"tags":["beliefs-and-folklore","Madagascar highlands"],"sources":[{"organization":"Wikipedia","title":{"ar":"Famadihana","de":"Famadihana","en":"Famadihana"},"url":"https://en.wikipedia.org/wiki/Famadihana","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Madagascar","de":"Culture of Madagascar","en":"Culture of Madagascar"},"url":"https://en.wikipedia.org/wiki/Culture_of_Madagascar","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في قرية بمرتفعات مدغشقر، تفتح أسرة القبر عند الفجر، وتفرش ثوب لامبا حريري جديد، وتعيد لفّ رفات الجد، وترقص معه على أنغام فرقة نحاسية قبل إعادته إلى القبر.","de":"In einem Hochlanddorf öffnet eine Familie im Morgengrauen das Grab, legt neuen Seiden-Lamba bereit, wickelt die Überreste des Großvaters neu und tanzt mit ihm zu einer Blaskapelle, bevor er ins Grab zurückkehrt.","en":"In a highland village, a family opens the tomb at dawn, lays out new silk lamba, rewraps a grandfather's remains and dances with him to a brass band before returning him to the tomb."},"misunderstanding":{"ar":"يُفهم هذا الطقس أحيانًا خطأً على أنه عبادة للموتى أو انعدام احترام لهم، لكنه في جوهره تعبير عن الصلة المستمرة بالأسلاف وتكريمهم.","de":"Manchmal wird der Brauch fälschlich als Totenkult oder Respektlosigkeit verstanden, doch er ist ein Ausdruck fortbestehender Verbundenheit und Ehrung der Vorfahren.","en":"The custom is sometimes mistaken for ancestor worship or disrespect, but it is an expression of ongoing connection and honour toward ancestors."},"comparison":{"ar":"يشبه هذا الطقس في بعض جوانبه طقوس إحياء ذكرى الأسلاف في ثقافات أخرى، حيث يجتمع الأحياء لتكريم الموتى وتجديد الروابط الأسرية.","de":"Ähnliche Züge finden sich in anderen Kulturen, die ihrer Vorfahren gedenken, indem Lebende zusammenkommen, um die Toten zu ehren und Familienbande zu erneuern.","en":"It shares features with ancestor remembrance in other cultures, where the living gather to honour the dead and renew family bonds."}},{"id":"tra-009","version":2,"slug":"teranga-what-a-senegalese-host-owes-a-stranger","contentType":"note","category":"food-and-hospitality","title":{"ar":"تيرانغا: واجب المضيف السنغالي نحو الغريب","de":"Teranga: was ein senegalesischer Gastgeber einem Fremden schuldet","en":"Teranga: what a Senegalese host owes a stranger"},"deck":{"ar":"كيف تُترجم كرم الضيافة السنغالي إلى أفعال يومية مع الغرباء.","de":"Wie senegalesische Gastfreundschaft im Alltag mit Fremden gelebt wird.","en":"How Senegalese hospitality translates into everyday actions with strangers."},"teaser":{"ar":"في السنغال، الضيف ليس مقاطعة بل شرف. تيرانغا، من الولوف، تحدد كيف يُستقبل الغريب ويُطعم ويُصاحب.","de":"In Senegal ist ein Gast keine Unterbrechung, sondern eine Ehre. Teranga, aus dem Wolof, bestimmt, wie Fremde willkommen geheißen und bewirtet werden.","en":"In Senegal, a guest is not an interruption but an honour. Teranga, from Wolof, defines how a stranger is welcomed, fed and accompanied."},"readingMinutes":1,"sections":{"ar":[{"heading":"تيرانغا: شرف الضيف","paragraphs":["تيرانغا، من اللغة الولوفية، هي المثل السنغالي الواسع الانتشار للضيافة: يُرحب بالضيف ويُطعم ويُعامل كشرف لا كمقاطعة. في الممارسة، يُعرض على الزائر الماء أو الأتاية، الشاي الأخضر القوي الحلو الذي يُخمر ثلاث مرات في أكواب صغيرة ويُقدم في جولات تنظم الحديث.","يقول مثل شائع إن الكؤوس الثلاثة مرة كالموت، حلوة كالحياة، ولطيفة كالحب، وهو مثل يتردد في الساحل مع اختلافات محلية. تمتد القيمة إلى ما هو أبعد من الأصدقاء: قد يُرافق الغرباء الذين يسألون عن الاتجاهات إلى وجهتهم، ويُتوقع مشاركة وجبة مع زائر حتى في الأسر المتواضعة."]},{"heading":"بين المثالية والواقع","paragraphs":["تيرانغا أيضًا علامة وطنية، تُستخدم في حملات السياحة وفي لقب المنتخب الوطني لكرة القدم، أسود تيرانغا. لكنها مثالية معيارية وليست وصفًا لكل لقاء، فالضغط الاقتصادي وحياة المدينة وتسويق السياحة كلها تمدد الممارسة. وتختلف الممارسة بين المناطق والأجيال، ففي المدن الكبرى قد تكون الوتيرة أسرع، بينما في الريف تظل التقاليد راسخة."]}],"de":[{"heading":"Teranga: die Ehre des Gastes","paragraphs":["Teranga, aus dem Wolof, ist das weit verbreitete senegalesische Ideal der Gastfreundschaft: Ein Gast wird willkommen geheißen, bewirtet und als Ehre behandelt, nicht als Störung. In der Praxis wird dem Besucher Wasser oder Ataya angeboten, der starke, süße grüne Tee, der dreimal in kleinen Gläsern gebrüht und in Runden serviert wird, die das Gespräch strukturieren.","Ein verbreitetes Sprichwort gibt die drei Gläser als bitter wie der Tod, süß wie das Leben und sanft wie die Liebe, ein Sprichwort, das im Sahel mit lokalen Varianten wiederholt wird. Der Wert reicht über Freunde hinaus: Fremde, die nach dem Weg fragen, werden möglicherweise zu ihrem Ziel gebracht, und eine Mahlzeit mit einem Besucher zu teilen wird selbst in bescheidenen Haushalten erwartet."]},{"heading":"Zwischen Ideal und Wirklichkeit","paragraphs":["Teranga ist auch eine nationale Marke, verwendet in Tourismuskampagnen und im Spitznamen der Fußballnationalmannschaft, der Löwen der Teranga. Doch sie ist ein normatives Ideal, keine Beschreibung jeder Begegnung; wirtschaftlicher Druck, Stadtleben und Tourismusmarketing dehnen die Praxis. Die Praxis variiert regional und generationell: In Großstädten ist das Tempo oft schneller, während auf dem Land die Traditionen fest verankert bleiben."]}],"en":[{"heading":"Teranga: the guest as honour","paragraphs":["Teranga, from Wolof, is the widely shared ideal of Senegalese hospitality: a guest is welcomed, fed and treated as an honour rather than an interruption. In practice a visitor is offered water or ataya, the strong sweet green tea brewed three times in small glasses and served in rounds that structure conversation.","A common saying gives the three glasses as bitter like death, sweet like life and gentle like love, a proverb repeated across the Sahel with local variations. The value extends beyond friends: strangers asking directions may be walked to their destination, and sharing a meal with a visitor is expected even in modest households."]},{"heading":"Between ideal and reality","paragraphs":["Teranga is also a national brand, used in tourism campaigns and in the nickname of the national football team, the Lions of Teranga. But it is a normative ideal rather than a description of every encounter; economic strain, city life and tourism marketing all stretch the practice. The practice varies regionally and generationally: in big cities the pace may be faster, while in rural areas traditions remain firmly rooted."]}]},"context":{"countries":["SN"],"region":"Senegal","continent":"africa","languages":["wo","fr"],"period":"contemporary"},"tags":["food-and-hospitality","Senegal"],"sources":[{"organization":"Wikipedia","title":{"ar":"Teranga","de":"Teranga","en":"Teranga"},"url":"https://en.wikipedia.org/wiki/Teranga","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Senegal","de":"Culture of Senegal","en":"Culture of Senegal"},"url":"https://en.wikipedia.org/wiki/Culture_of_Senegal","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يسأل غريب عن عنوان في داكار؛ يشير صاحب متجر، ثم يمشي معه شارعين، وعندما يصلان تصر الأسرة على أن يجلس لكأس أتاية.","de":"Ein Fremder fragt in Dakar nach einer Adresse; ein Ladenbesitzer zeigt, dann geht er zwei Straßen mit, und als sie ankommen, besteht die Familie darauf, dass er sich für ein Glas Ataya setzt.","en":"A stranger asks for an address in Dakar; a shopkeeper points, then walks him two streets, and when they arrive the family insists he sit for a glass of ataya."},"misunderstanding":{"ar":"يُفهم أحيانًا أن تيرانغا واجب مطلق، لكنها في الواقع مثالية معيارية تتأثر بالظروف الاقتصادية والحضرية.","de":"Manchmal wird Teranga als absolute Pflicht verstanden, doch tatsächlich ist sie ein normatives Ideal, das von wirtschaftlichen und städtischen Bedingungen beeinflusst wird.","en":"Teranga is sometimes understood as an absolute duty, but it is actually a normative ideal influenced by economic and urban conditions."},"comparison":{"ar":"مثل الضيافة العربية، تيرانغا تضع الضيف في مركز الاهتمام، لكنها ترتبط ارتباطًا وثيقًا بالشاي الأخضر والأتاية.","de":"Wie arabische Gastfreundschaft stellt Teranga den Gast in den Mittelpunkt, ist aber eng mit grünem Tee und Ataya verbunden.","en":"Like Arab hospitality, Teranga puts the guest at the centre, but it is closely tied to green tea and ataya."}},{"id":"tra-010","version":2,"slug":"the-hammam-as-a-weekly-appointment","contentType":"note","category":"everyday-life","title":{"ar":"الحمّام موعد أسبوعي في تونس","de":"Der Hammam als wöchentlicher Termin","en":"The hammam as a weekly appointment"},"deck":{"ar":"بيوت حمّام في الأحياء تجمع الجيران في تسلسل من الغرف الباردة والدافئة والساخنة، وتظل موعدًا أسبوعيًا لكثير من الرجال والنساء.","de":"Nachbarschaftsbäder mit kalten, warmen und heißen Räumen bleiben in Tunesien für viele Männer und Frauen ein fester Wochenrhythmus.","en":"Neighbourhood bathhouses with cool, warm and hot rooms remain a weekly rhythm for many men and women across Tunisia."},"teaser":{"ar":"في تونس يُقصد الحمّام أسبوعيًا، غالبًا قبل صلاة الجمعة أو عرس، حيث يصبح الغسل مناسبة اجتماعية لا مجرد نظافة.","de":"In Tunesien geht man wöchentlich in den Hammam, oft vor dem Freitagsgebet oder einer Hochzeit, wo Waschen zum geselligen Ritual wird.","en":"In Tunisia people visit the hammam weekly, often before Friday prayers or a wedding, where washing becomes a social ritual rather than mere hygiene."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس الغسل والكيس","paragraphs":["الحمّام فضاء حيّ في الحي، يمرّ فيه الناس من الغرفة الباردة إلى الدافئة ثم الساخنة، ويستعمل كثيرون الصابون الأسود بزيت الزيتون وقفاز الكيس الخشن على البلاطة الرخامية.","أحيانًا يتولى عامل الحمّام تقشير الجلد، فيصير الغسل حوارًا وأخبارًا ونصائح تتبادلها النساء أو الرجال في يومهم المختار.","قبل العيد أو العرس تحجز العائلات الغرفة الساخنة لساعات، ويختلف التوقيت والسعر بحسب المدينة والعائلة، ويبقى هذا الإيقاع الأسبوعي عادة لا قاعدة شاملة."]},{"heading":"ذاكرة المكان وضغط الحياة","paragraphs":["كثير من الحمّامات القديمة وُقفت كمؤسسات خيرية مرتبطة بالمساجد، ولهذا تقف بعض أقدمها في المدينة العتيقة قرب المباني الدينية.","غير أن الحمّامات المائية المنزلية وكلفة الغاز وشحّ الماء أغلقت كثيرًا منها، وتعمل جمعيات تراثية الآن على إبقاء ما تبقّى مفتوحًا."]}],"de":[{"heading":"Der Ritus des Schrubbens","paragraphs":["Der Hammam ist ein lebendiger Nachbarschaftsort: Man geht von kalten über warme zu heißen Räumen, und viele nutzen schwarze Olivenölseife und den rauen Kessa-Handschuh auf der Marmorplatte.","Manchmal übernimmt eine Badefrau oder ein Bademeister das Peeling, und das Waschen wird zum Gespräch über Neuigkeiten, Ratschläge und Vorbereitungen.","Vor dem Eid oder einer Hochzeit buchen Familien den heißen Raum für Stunden; Zeitpunkt und Preis unterscheiden sich je nach Stadt und Familie, und der Wochenrhythmus ist Norm, keine allgemeine Regel."]},{"heading":"Erbe und Alltagsdruck","paragraphs":["Viele historische Hammams wurden als fromme Stiftungen an Moscheen gegründet, deshalb stehen einige der ältesten in der Medina neben religiösen Gebäuden.","Doch Hausbäder, Gaskosten und Wasserknappheit haben viele geschlossen, und Denkmalgruppen setzen sich dafür ein, die verbliebenen offen zu halten."]}],"en":[{"heading":"The scrub as social ritual","paragraphs":["A hammam is a living neighbourhood space where people move from cool to warm to hot rooms, using black olive-oil soap and a rough kessa glove on a marble slab.","Sometimes an attendant does the exfoliation, and the wash becomes a conversation about news, advice and preparations.","Before Eid or a wedding, families book the hot room for hours; timing and pricing vary by town and family, and the weekly rhythm is a norm rather than a universal habit."]},{"heading":"Heritage under everyday pressure","paragraphs":["Many historic hammams were endowed as charitable foundations attached to mosques, which is why some of the oldest stand in the medina next to religious buildings.","But home bathrooms, gas costs and water scarcity have closed many, and heritage groups now campaign to keep the remaining ones open."]}]},"context":{"countries":["TN"],"region":"Tunisia","continent":"africa","languages":["ar","fr"],"period":"contemporary"},"tags":["everyday-life","Tunisia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hammam","de":"Hammam","en":"Hammam"},"url":"https://en.wikipedia.org/wiki/Hammam","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Tunisia","de":"Culture of Tunisia","en":"Culture of Tunisia"},"url":"https://en.wikipedia.org/wiki/Culture_of_Tunisia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17"},{"id":"tra-011","version":2,"slug":"xeer-somali-custom-before-there-was-a-state","contentType":"note","category":"social-behaviour","title":{"ar":"الخير: العرف الصومالي قبل الدولة","de":"Xeer: somalisches Gewohnheitsrecht vor dem Staat","en":"Xeer: Somali custom before there was a state"},"deck":{"ar":"نظام قانوني عرفي يقوم على اتفاقيات بين العشائر وسلطة مجالس الشيوخ.","de":"Ein gewohnheitsrechtliches System, das auf Vereinbarungen zwischen Clan-Gruppen und der Autorität von Ältestenräten beruht.","en":"A customary legal system built on agreements between clan groups and the authority of elders' councils."},"teaser":{"ar":"في الصومال، يحل الخير النزاعات عبر شيوخ يسمعون ويقررون التعويض، ويعتمد على الضغط العشائري والسمعة.","de":"In Somalia regelt Xeer Konflikte durch Älteste, die anhören und Entschädigungen festlegen, gestützt auf Clan-Druck und Reputation.","en":"In Somalia, Xeer resolves disputes through elders who hear cases and set compensation, backed by clan pressure and reputation."},"readingMinutes":1,"sections":{"ar":[{"heading":"مجالس الشيوخ والمسؤولية الجماعية","paragraphs":["الخير نظام قانوني عرفي مبني على اتفاقيات بين مجموعات العشائر وعلى سلطة مجالس الشيوخ الذين يستمعون إلى النزاعات ويستشهدون بالسوابق. المسؤولية فيه جماعية: فالتعويض عن الإصابة أو الوفاة يدفعه عادةً مجموعة الجاني إلى مجموعة الضحية، وأشهر صوره الإبل والماشية.","يتوسط الشيوخ بدلاً من أن يحكموا، وتُنفَّذ قراراتهم عبر الضغط العشائري والسمعة وخطر المطالبات المتبادلة. ويختلف تطبيق الخير بين العشائر والمناطق، كما يتفاوت بين الأجيال وفي المدن."]},{"heading":"الاستمرارية والانتقادات","paragraphs":["يسبق الخير الدولة الحديثة بزمن طويل، وقد استمر في العمل بعد انهيار الحكومة المركزية عام 1991، إلى جانب المحاكم الشرعية وفي الشمال حكم محلي رسمي. ويغطي حقوق الرعي والمياه والزواج والإصابة والقتل، لكن منتقديه يقولون إنه قد يضر بالنساء والأقليات الذين يفتقرون إلى مكانة متساوية في مجالس العشائر."]}],"de":[{"heading":"Ältestenräte und kollektive Verantwortung","paragraphs":["Xeer ist ein gewohnheitsrechtliches System, das auf Vereinbarungen zwischen Clan-Gruppen und der Autorität von Ältestenräten aufbaut, die Streitigkeiten anhören und Präzedenzfälle zitieren. Die Verantwortung ist kollektiv: Entschädigung für Verletzung oder Tod zahlt meist die Clan-Gruppe des Täters an die des Opfers, am bekanntesten in Kamelen und Vieh.","Älteste vermitteln, statt zu richten, und Entscheidungen werden durch Clan-Druck, Reputation und die Drohung wechselseitiger Ansprüche durchgesetzt. Je nach Clan und Region wird Xeer unterschiedlich gehandhabt, und auch zwischen Generationen und in Städten gibt es Unterschiede."]},{"heading":"Fortbestand und Kritik","paragraphs":["Das System ist viel älter als der moderne Staat und funktionierte nach dem Zusammenbruch der Zentralregierung 1991 weiter, neben Scharia-Gerichten und im Norden einer formalen lokalen Verwaltung. Es umfasst Weide- und Wasserrechte, Ehe, Verletzung und Totschlag, doch Kritiker sagen, es könne Frauen und Minderheiten benachteiligen, die in den Clan-Räten keine gleichberechtigte Stellung haben."]}],"en":[{"heading":"Elders' councils and collective responsibility","paragraphs":["Xeer is a customary legal system built on agreements between clan groups and on the authority of councils of elders, who hear disputes and cite precedent. Responsibility is collective: compensation for injury or death is usually paid by the offender's clan group to the victim's, most famously in camels and livestock.","Elders mediate rather than judge, and decisions are enforced through clan pressure, reputation and the threat of reciprocal claims. Xeer varies by clan and region, and it works differently in cities and across generations."]},{"heading":"Continuity and criticism","paragraphs":["The system long predates the modern state and kept functioning after the central government collapsed in 1991, alongside sharia courts and, in the north, formal local government. It covers grazing and water rights, marriage, injury and homicide, but critics say it can disadvantage women and minority groups who lack equal standing in clan councils."]}]},"context":{"countries":["SO"],"region":"Somalia and the Horn of Africa","community":"Somali pastoralist communities","continent":"africa","languages":["so"],"period":"contemporary"},"tags":["social-behaviour","Somalia and the Horn of Africa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Xeer","de":"Xeer","en":"Xeer"},"url":"https://en.wikipedia.org/wiki/Xeer","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Somali people","de":"Somali people","en":"Somali people"},"url":"https://en.wikipedia.org/wiki/Somali_people","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"يتنازع راعيان من عشيرتين مختلفتين على بئر؛ فيلتقي شيوخ من الجانبين تحت شجرة، ويسمعون الشهود ويتفقون على تعويض يُسلَّم من الماشية.","de":"Zwei Hirten aus verschiedenen Clans streiten über einen Brunnen; Älteste beider Seiten treffen sich unter einem Baum, hören Zeugen und einigen sich auf eine Entschädigung in Vieh.","en":"Two herders from different clans quarrel over a well; elders from both sides meet under a tree, hear witnesses and agree on compensation to be delivered in livestock."},"misunderstanding":{"ar":"الخير ليس مدونة مكتوبة واحدة: فهو يتباين حسب العشيرة والمنطقة، ويعمل بشكل مختلف في المدن، وينبغي وصفه إلى جانب الشريعة لا باعتباره القانون الصومالي الوحيد.","de":"Xeer ist kein einheitliches geschriebenes Gesetzbuch: Es variiert je nach Clan und Region, funktioniert in Städten anders und sollte neben der Scharia beschrieben werden, nicht als das einzige somalische Recht.","en":"Xeer is not a single written code: it varies by clan and region and works differently in cities, and it should be described alongside sharia rather than as the only Somali law."},"comparison":{"ar":"يشبه الخير إلى حد ما أنظمة العدالة التصالحية التي تعطي الأولوية للوساطة والتعويض على العقاب، لكنه يختلف في اعتماده على الانتماء العشائري والمسؤولية الجماعية.","de":"Xeer ähnelt in gewisser Weise restaurativen Justizsystemen, die Vermittlung und Entschädigung über Bestrafung stellen, unterscheidet sich aber durch die Bindung an Clan-Zugehörigkeit und kollektive Haftung.","en":"Xeer is somewhat like restorative justice systems that prioritise mediation and compensation over punishment, but it differs in its reliance on clan membership and collective liability."}},{"id":"tra-012","version":2,"slug":"ubuntu-a-person-is-a-person-through-others","contentType":"note","category":"social-behaviour","title":{"ar":"أوبونتو: الإنسان إنسانٌ بالآخرين","de":"Ubuntu: Ein Mensch ist Mensch durch andere","en":"Ubuntu: a person through other people"},"deck":{"ar":"فكرة إنسانية من لغات نغوني تجعل الشخصية علاقةً بالجماعة لا استقلالًا فرديًا وحده.","de":"Ein humanistisches Konzept aus Nguni-Sprachen versteht Personsein als Beziehung zur Gemeinschaft, nicht nur als individuelle Autonomie.","en":"A humanist idea from Nguni languages treats personhood as relational, built through community rather than individual autonomy alone."},"teaser":{"ar":"في جنوب أفريقيا، تُختصر فكرة أوبونتو في أن الإنسان يصير إنسانًا عبر الآخرين، عبر الجماعة والكرم والاعتراف المتبادل.","de":"In Südafrika fasst Ubuntu den Gedanken, dass ein Mensch erst durch andere Mensch wird – durch Gemeinschaft, Großzügigkeit und gegenseitige Anerkennung.","en":"In South Africa, ubuntu holds that a person becomes a person through others: through community, generosity and mutual recognition in daily life."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما تعنيه الكلمة","paragraphs":["أوبونتو فكرة إنسانية من لغات نغوني، تُختصر عادةً في العبارة: الإنسان إنسانٌ بالآخرين. الجذر -ntu يعني شخصًا، والسابقة u- تشير إلى الإنسانية أو الكينونة، وتظهر أفكار قريبة في لغات البانتو الأخرى مثل botho في السوتو.","تصف الفكرة الشخصية بوصفها علاقةً تُبنى عبر الجماعة والكرم والاعتراف المتبادل، لا عبر الاستقلال الفردي وحده. وتختلف طريقة عيش هذه القيم بين الأجيال والمناطق، إذ يتمسك الشباب في المدن بها بأساليب جديدة."]},{"heading":"من المبدأ إلى الحياة العامة","paragraphs":["بعد الفصل العنصري صارت أوبونتو قيمةً عامة، استدعى الأسقف ديزموند توتو معناها في لجنة الحقيقة والمصالحة، ثم ظهرت في أحكام المحكمة الدستورية حول الإخلاء والكرامة.","لكن الفكرة تُستخدم أيضًا تجاريًا وسياسيًا، ويحذّر ناقدون من تسويقها ومن فجوة بين المثل وأجواء كراهية الأجانب اليومية في جنوب أفريقيا."]}],"de":[{"heading":"Was das Wort meint","paragraphs":["Ubuntu ist eine humanistische Idee aus Nguni-Sprachen, meist zusammengefasst in der Maxime: Ein Mensch ist ein Mensch durch andere Menschen. Die Wurzel -ntu bedeutet Person, das Präfix u- signalisiert Menschlichkeit oder Sein; verwandte Vorstellungen gibt es in anderen Bantu-Sprachen, etwa botho im Sotho.","Das Konzept beschreibt Personsein als relational, erreicht durch Gemeinschaft, Großzügigkeit und gegenseitige Anerkennung statt allein durch individuelle Autonomie. Wie diese Werte gelebt werden, variiert regional und zwischen Generationen; junge Menschen in Städten deuten sie auf neue Weise."]},{"heading":"Vom Prinzip zum öffentlichen Wert","paragraphs":["Nach der Apartheid wurde Ubuntu ein öffentlicher Wert: Erzbischof Desmond Tutu berief sich in der Wahrheits- und Versöhnungskommission darauf, später auch Urteile des Verfassungsgerichts zu Räumung und Würde.","Zugleich wird der Begriff kommerziell und politisch genutzt. Kritiker warnen vor Ubuntu-Branding und vor einer Lücke zwischen Ideal und alltäglicher Fremdenfeindlichkeit in Südafrika."]}],"en":[{"heading":"What the word carries","paragraphs":["Ubuntu is a humanist idea from Nguni languages, usually summarised in the maxim: a person is a person through other people. The root -ntu means person and the prefix u- signals humanness or being; related ideas appear across Bantu languages, such as botho in Sotho.","It describes personhood as relational, achieved through community, generosity and mutual recognition rather than individual autonomy alone. How these values are lived varies by region and generation; young people in cities often interpret them in new ways."]},{"heading":"From principle to public value","paragraphs":["After apartheid, ubuntu became a public value, invoked by Archbishop Desmond Tutu in the Truth and Reconciliation Commission and later in Constitutional Court judgments on eviction and dignity.","It is also used commercially and politically, and critics warn of ubuntu branding and a gap between the ideal and everyday xenophobia in South Africa."]}]},"context":{"countries":["ZA"],"region":"South Africa","continent":"africa","languages":["zu","xh","en"],"period":"contemporary"},"tags":["social-behaviour","South Africa"],"sources":[{"organization":"Wikipedia","title":{"ar":"Ubuntu philosophy","de":"Ubuntu philosophy","en":"Ubuntu philosophy"},"url":"https://en.wikipedia.org/wiki/Ubuntu_philosophy","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of South Africa","de":"Culture of South Africa","en":"Culture of South Africa"},"url":"https://en.wikipedia.org/wiki/Culture_of_South_Africa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"اجتماع سكاني يقرر مساعدة أسرة على إعادة بناء بيتها بعد حريق، لا كصدقة بل كواجب على الجيران الذين يشتركون في الإنسانية نفسها.","de":"Eine Gemeindeversammlung beschließt, einer Familie nach einem Brand beim Wiederaufbau zu helfen – nicht als Wohltätigkeit, sondern als Pflicht der Nachbarn, die dieselbe Menschlichkeit teilen.","en":"A community meeting decides to help a family rebuild after a fire, not as charity but as an obligation owed by neighbours who are part of the same personhood."},"misunderstanding":{"ar":"يُفهم أوبونتو أحيانًا كذوبان الفرد في الجماعة، لكنه في جوهره اعتراف متبادل لا إلغاء للشخص.","de":"Manchmal wird Ubuntu so verstanden, als verschwinde das Individuum in der Gruppe; gemeint ist jedoch gegenseitige Anerkennung, nicht Auflösung der Person.","en":"Ubuntu is sometimes read as the individual dissolving into the group, but it is about mutual recognition, not the erasure of the person."},"comparison":{"ar":"يشبه أوبونتو إلى حدٍّ ما فكرة التكافل في مجتمعات أخرى، لكنه يربطها بفهم للشخصية نفسها لا بالمساعدة وحدها.","de":"Ubuntu ähnelt Solidaritätsideen anderer Gesellschaften, verknüpft sie aber mit einem Verständnis von Personsein selbst, nicht nur mit Hilfe.","en":"Ubuntu resembles solidarity ideas elsewhere, yet it ties them to an understanding of personhood itself, not to helping alone."}},{"id":"tra-013","version":2,"slug":"the-first-shrine-visit-how-japan-starts-the-year","contentType":"note","category":"traditions","title":{"ar":"زيارة الضريح الأولى: كيف تبدأ اليابان عامها","de":"Der erste Schreinbesuch: Wie Japan das Jahr beginnt","en":"The first shrine visit: how Japan starts the year"},"deck":{"ar":"في الأيام الثلاثة الأولى من يناير، تتجه العائلات اليابانية إلى المعابد والأضرحة لأداء هاتسومودي، أول زيارة في العام الجديد.","de":"In den ersten drei Januartagen pilgern japanische Familien zu Schreinen und Tempeln für Hatsumōde, den ersten Besuch des neuen Jahres.","en":"In the first three days of January, Japanese families head to shrines and temples for Hatsumōde, the year's first visit."},"teaser":{"ar":"طقوس رأس السنة في اليابان: من زيارات الأضرحة إلى بطاقات نينغاجو، كيف تحيي العائلات بداية العام.","de":"Neujahrsrituale in Japan: von Schreinbesuchen bis zu Neujahrskarten – wie Familien den Jahresanfang gestalten.","en":"New Year rituals in Japan: from shrine visits to nengajō cards, how families mark the start of the year."},"readingMinutes":1,"sections":{"ar":[{"heading":"هاتسومودي: أول زيارة للعام","paragraphs":["في اليابان، يُعد عيد رأس السنة (أوشوغاتسو) أهم مناسبة سنوية، حيث تغلق كثير من الأعمال أبوابها في الأيام الأولى من يناير وتجتمع العائلات حول وجبات خاصة.","هاتسومودي هي أول زيارة للضريح أو المعبد في العام، وعادة ما تتم خلال الأيام الثلاثة الأولى من يناير. تستقبل الأضرحة الكبرى مثل ميجي جينغو في طوكيو ملايين الزوار في تلك الفترة."]},{"heading":"عادات وتقاليد رأس السنة","paragraphs":["يسحب الزوار أوراق الحظ (أوميكوجي)، ويشترون التمائم (أوماموري)، ويرمون العملات في صندوق التبرعات. وفي ليلة رأس السنة، تقرع المعابد البوذية الجرس 108 مرات (جويا نو كاني) لإزالة الرغبات الدنيوية الـ108.","طعام رأس السنة رمزي: أوسيتشي ريوري في صناديق لاكيه متراصة، وحساء أوزوني مع الموتشي، والفاصوليا السوداء للصحة. ويتلقى الأطفال نقودًا في مظاريف أوتوشيداما من البالغين."]}],"de":[{"heading":"Hatsumōde: Der erste Besuch des Jahres","paragraphs":["In Japan ist Oshōgatsu, der Neujahrsfeiertag, das wichtigste jährliche Fest; viele Geschäfte schließen an den ersten Januartagen, und Familien versammeln sich zu besonderen Mahlzeiten.","Hatsumōde ist der erste Schrein- oder Tempelbesuch des Jahres, üblicherweise innerhalb der ersten drei Januartage. Große Schreine wie der Meiji Jingū in Tokio empfangen in diesem Zeitraum Millionen von Besuchern."]},{"heading":"Bräuche und Traditionen zum Neujahr","paragraphs":["Besucher ziehen Omikuji-Wahrsagelose, kaufen Omamori-Amuerte und werfen Münzen in den Opferstock; in der Silvesternacht läuten buddhistische Tempel die Glocke 108 Mal (Joya no Kane), um die 108 irdischen Begierden zu vertreiben.","Das Neujahrsessen ist symbolisch: Osechi Ryōri in gestapelten Lackschachteln, Ozōni-Suppe mit Mochi und schwarze Bohnen für die Gesundheit; Kinder erhalten Geld in Otoshidama-Umschlägen von Erwachsenen."]}],"en":[{"heading":"Hatsumōde: The first visit of the year","paragraphs":["In Japan, Oshōgatsu, the New Year holiday, is the most important annual festival; many businesses close for the first days of January and families gather around special meals.","Hatsumōde is the first shrine or temple visit of the year, usually made within the first three days of January. Major shrines such as Meiji Jingū in Tokyo receive millions of visitors in that window."]},{"heading":"Customs and traditions of New Year","paragraphs":["Visitors draw omikuji fortune slips, buy omamori amulets and throw coins into the offering box; on New Year's Eve Buddhist temples ring the bell 108 times, the joya no kane, to remove the 108 earthly desires.","New Year food is symbolic: osechi ryōri in stacked lacquered boxes, ozōni soup with mochi, and black beans for health; children receive money in otoshidama envelopes from adults."]}]},"context":{"countries":["JP"],"region":"Japan (nationwide)","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["traditions","Japan (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Japanese New Year","de":"Japanese New Year","en":"Japanese New Year"},"url":"https://en.wikipedia.org/wiki/Japanese_New_Year","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Hatsumōde","de":"Hatsumōde","en":"Hatsumōde"},"url":"https://en.wikipedia.org/wiki/Hatsum%C5%8Dde","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في 2 يناير، تصطف عائلة في طابور عند ضريح الحي، تشتري ورقة حظ تقول 'حظ صغير'، تربطها بغصن صنوبر وتأكل موتشي مشويًا من كشك.","de":"Am 2. Januar steht eine Familie am Nachbarschaftsschrein an, zieht ein Los mit der Aufschrift „kleines Glück“, bindet es an einen Kiefernzweig und isst gegrilltes Mochi von einem Stand.","en":"On 2 January a family queues at a neighbourhood shrine, buys a fortune slip that says 'small luck', ties it to a pine branch and eats grilled mochi from a stall."},"misunderstanding":{"ar":"يعتقد البعض أن هاتسومودي واجب ديني صارم، لكنه في الواقع مناسبة اجتماعية وعائلية، وكثيرون يزورون الأضرحة دون التزام ديني عميق.","de":"Manche halten Hatsumōde für eine strenge religiöse Pflicht, doch es ist vor allem ein soziales und familiäres Ereignis; viele besuchen Schreine ohne tiefe religiöse Bindung.","en":"Some assume Hatsumōde is a strict religious duty, but it is largely a social and family occasion; many visit shrines without deep religious commitment."},"comparison":{"ar":"على عكس الاحتفالات الغربية برأس السنة التي تركز على الحفلات، يركز هاتسومودي على التجديد الروحي والاجتماعي مع العائلة.","de":"Anders als westliche Neujahrsfeiern mit Partys betont Hatsumōde die spirituelle und soziale Erneuerung im Familienkreis.","en":"Unlike Western New Year celebrations focused on parties, Hatsumōde emphasises spiritual and social renewal with family."}},{"id":"tra-014","version":2,"slug":"obon-the-week-the-ancestors-come-home","contentType":"scene","category":"traditions","title":{"ar":"أوبون: عودة الأسلاف إلى البيت","de":"Obon: Wenn die Ahnen heimkehren","en":"Obon: the week the ancestors come home"},"deck":{"ar":"موسم بوذي يجمع الأحياء بالأموات في منتصف أغسطس، وتعود فيه العائلات إلى بلداتها الأصلية.","de":"Eine buddhistische Gedenkzeit Mitte August, in der Familien in ihre Herkunftsorte zurückreisen und Gräber pflegen.","en":"A Buddhist memorial season in mid-August, when families travel back to ancestral towns and tend the graves."},"teaser":{"ar":"أسبوع يزور فيه الأسلاف بيوتهم، فتُنظَّف القبور وتُشعل نيران الترحيب وترقص الأحياء في الشوارع.","de":"Eine Woche, in der die Ahnen nach Hause kommen: Gräber werden geputzt, Willkommensfeuer entzündet und auf Straßen wird getanzt.","en":"For a few days the ancestors are believed to return: graves are cleaned, welcome fires lit, and streets fill with dancers."},"readingMinutes":1,"sections":{"ar":[{"heading":"نيران الترحيب والوداع","paragraphs":["في منتصف أغسطس تعيش معظم اليابان موسم أوبون البوذي، حيث تعتقد العائلات أن أرواح الأسلاف تعود إلى البيت. لذلك ينظف الناس القبور، ويشعلون نيراناً صغيرة للترحيب تسمى موكايبي، ثم نيران وداع ترسل الأرواح. في كيوتو تشتعل نيران غوزان نو أوكوريبي على خمسة جبال في السادس عشر من أغسطس.","تختلف المواعيد بحسب المنطقة والمذهب البوذي، فبعض المناطق تحتفظ بتاريخ منتصف يوليو تبعاً للتقويم القمري، كما تتباين عادات القبور من مكان إلى آخر."]},{"heading":"رقص الشوارع وعودة الأبناء","paragraphs":["تُقام رقصات بون أودوري في الشوارع والحدائق حول منصة خشبية، ويرقص المشاركون خطوات شعبية إقليمية في يوكاتا قطنية.","ويستغل كثيرون العطلة للسفر إلى بلدات أسلافهم، ما يجعل أوبون من أثقل فترات السفر الداخلي في البلاد.","يمتزج الموسم بالممارسة البوذية والعادات العائلية بدل عقيدة واحدة، وبعض العائلات التي لا تملك قبوراً أو صلة بمعبد تحتفل به قليلاً جداً، ويختلف ذلك أيضاً بين الأجيال والمناطق."]}],"de":[{"heading":"Willkommens- und Abschiedsfeuer","paragraphs":["Mitte August begeht der größte Teil Japans die buddhistische Gedenkzeit Obon. Familien glauben, dass die Geister der Ahnen heimkehren, deshalb reinigen sie Gräber und entzünden kleine Willkommensfeuer, mukaebi genannt, später Abschiedsfeuer. In Kyoto brennen am 16. August die Feuer von Gozan no Okuribi auf fünf Bergen.","Datum und Grabbräuche unterscheiden sich je nach Region und buddhistischer Schule; manche Gegenden halten nach dem Mondkalender am Datum Mitte Juli fest."]},{"heading":"Tanz im Hof und Reise nach Hause","paragraphs":["Bon-odori-Tänze finden auf Straßen und in Parks rund um ein Holzgerüst statt, die Teilnehmenden tanzen regionale Volkstänze in Baumwoll-Yukata.","Viele nutzen die Zeit für die Reise in die Heimatorte ihrer Vorfahren, Obon ist eine der verkehrsreichsten Reisezeiten des Landes.","Die Zeit verbindet buddhistische Praxis mit Familienbrauch statt einer einzigen Lehre; Familien ohne Gräber oder Tempelbindung begehen sie kaum, und auch zwischen Generationen und Regionen gibt es Unterschiede."]}],"en":[{"heading":"Welcome fires and farewell fires","paragraphs":["In mid-August most of Japan observes Obon, a Buddhist memorial season. Families believe ancestral spirits come home, so they clean graves, light small welcome fires called mukaebi and later send the spirits off with farewell fires. In Kyoto, Gozan no Okuribi lights bonfires on five mountains on 16 August.","Dates and grave customs vary by region and Buddhist school; some areas keep a mid-July date based on the lunar calendar."]},{"heading":"Dancing in the yard, travelling home","paragraphs":["Bon odori dances are held in streets and parks around a wooden scaffold, participants dancing regional folk steps in cotton yukata.","Many people travel back to ancestral hometowns, making Obon one of the country's heaviest domestic travel periods.","The season mixes Buddhist practice with family custom rather than a single doctrine; families without graves or temple ties mark it very little, and observance also shifts between generations and regions."]}]},"context":{"countries":["JP"],"region":"Japan (nationwide)","continent":"asia","languages":["ja"],"period":"contemporary"},"tags":["traditions","Japan (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Obon","de":"Obon","en":"Obon"},"url":"https://en.wikipedia.org/wiki/Obon","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Japanese funeral","de":"Japanese funeral","en":"Japanese funeral"},"url":"https://en.wikipedia.org/wiki/Japanese_funeral","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في بلدة صغيرة تنصب جمعية الحي منصة ياغورا في ساحة المدرسة، وتعود عائلات انتقلت إلى طوكيو لثلاثة أيام لترقص وتنظف قبر العائلة.","de":"In einer Kleinstadt baut der Nachbarschaftsverein ein Yagura im Schulhof auf, und Familien, die nach Tokio gezogen sind, kommen für drei Tage zurück, um zu tanzen und das Familiengrab zu jäten.","en":"In a small town the neighbourhood association sets up a yagura in the schoolyard, and families who moved to Tokyo come back for three days to dance and weed the family grave."},"misunderstanding":{"ar":"يُظن أن أوبون عطلة واحدة موحّدة، لكن مواعيده ورقصاته وعاداته تختلف بين المناطق والمذاهب البوذية.","de":"Obon gilt oft als einheitlicher Feiertag, doch Termine, Tänze und Grabbräuche unterscheiden sich regional und je nach Schule.","en":"Obon is often treated as one uniform holiday, yet its dates, dances and grave customs differ by region and Buddhist school."},"comparison":{"ar":"يشبه أوبون زيارات الأضرحة العائلية في ثقافات أخرى، لكنه يجمع التنظيف والرقص والسفر في أسبوع واحد.","de":"Ähnlich wie Totengedenktage anderswo verbindet Obon Erinnerung und Familie, bündelt aber Pflege, Tanz und Reisen in einer Woche.","en":"Like remembrance days elsewhere it links the living and the dead, but Obon packs grave-tending, dancing and travel into a single week."}},{"id":"tra-015","version":2,"slug":"the-reunion-dinner-and-the-first-sweep-of-the-year","contentType":"note","category":"traditions","title":{"ar":"عشاء اللمة وأول كنس في العام","de":"Das Wiedersehensessen und der erste Besen","en":"The reunion dinner and the first sweep"},"deck":{"ar":"كيف تحوّل عائلة صينية ليلة رأس السنة إلى طقس من الامتلاء والأمل، ثم تترك المكنسة جانباً في الصباح.","de":"Wie eine chinesische Familie die Neujahrsnacht zu einem Ritual des Überflusses macht und am Morgen den Besen stehen lässt.","en":"How one Chinese family turns New Year's Eve into a ritual of abundance, then leaves the broom alone on the first morning."},"teaser":{"ar":"عشاء اللمة في رأس السنة الصينية ليس مجرد وجبة، بل قلب احتفال يمتد من يناير إلى فبراير، حيث يلتقي الملايين ويُترك السمك رمزاً للوفرة.","de":"Das Wiedersehensessen zu Chinesisch Neujahr ist mehr als eine Mahlzeit: Es ist das Herz eines Festes, das Millionen zusammenbringt und den Fisch als Zeichen des Überflusses stehen lässt.","en":"The reunion dinner is the heart of Chinese New Year, a feast where fish is left partly uneaten to invite surplus, and the first day's sweeping is avoided to keep good fortune."},"readingMinutes":1,"sections":{"ar":[{"heading":"ليلة اللمة: سمك يبقى على الطاولة","paragraphs":["تبدأ احتفالات السنة الصينية الجديدة مع القمر الجديد الثاني بعد الانقلاب الشتوي، وتنتهي بمهرجان الفوانيس في اليوم الخامس عشر، لذا يتغير موعدها بين أواخر يناير وأواخر فبراير. وفي ليلة رأس السنة، يجتمع أفراد العائلة حول مائدة عشاء اللمة، حيث يُقدَّم السمك وغالباً ما يُترك جزء منه دون تناول، لأن كلمة سمك تُشبه كلمة فائض ووفرة."]},{"heading":"مكنسة مؤجلة وأظرف حمراء","paragraphs":["تُنظَّف البيوت قبل العيد لطرد بقايا العام القديم، لكن الكنس في اليوم الأول يُتجنَّب تقليدياً حتى لا تُكنس الحظوظ السعيدة. وتنتشر الألوان الحمراء من القصاصات الورقية إلى أظرف هونغباو المالية، وقد يرفض الطفل بأدب الظرف مرتين قبل قبوله.","يشكّل موسم السفر المعروف بـ«تشونيون» أكبر حركة بشرية سنوية في العالم، إذ يعود المهاجرون إلى مدنهم الأصلية، ما يؤثر على ازدحام القطارات والطرق لأسابيع. وتختلف الأطعمة والمحظورات والتحيات بشكل واضح بين شمال الصين وجنوبها وبين الأسر الريفية والحضرية، وكثير من هذه القواعد معتقدات شعبية وليست فرائض دينية."]}],"de":[{"heading":"Die Nacht des Wiedersehens: Fisch bleibt übrig","paragraphs":["Das chinesische Neujahrsfest, das Frühlingsfest, beginnt mit dem zweiten Neumond nach der Wintersonnenwende und endet mit dem Laternenfest am fünfzehnten Tag, daher schwankt sein Datum zwischen Ende Januar und Ende Februar. Am Neujahrsabend versammelt sich die Familie zum Wiedersehensessen, bei dem Fisch serviert und oft absichtlich teilweise übrig gelassen wird, denn das Wort für Fisch klingt wie Überfluss und Fülle."]},{"heading":"Aufgeschobener Besen und rote Umschläge","paragraphs":["Vor dem Fest werden die Häuser gereinigt, um das alte Jahr wegzukehren, doch am ersten Tag wird das Fegen traditionell vermieden, damit kein Glück weggefegt wird. Rot ist allgegenwärtig, von Papierschnitten bis zu Hongbao-Geldumschlägen, und ein Kind darf einen roten Umschlag höflich zweimal ablehnen, bevor es ihn annimmt.","Der Reiseverkehr namens Chunyun ist die größte jährliche Völkerwanderung der Welt, wenn Migranten in ihre Heimatstädte zurückkehren, was wochenlang Bahn- und Straßenverkehr prägt. Speisen, Tabus und Grüße unterscheiden sich stark zwischen Nord- und Südchina sowie zwischen ländlichen und städtischen Familien, und viele dieser Regeln sind Volksglauben, keine religiösen Pflichten."]}],"en":[{"heading":"The night of reunion: fish left over","paragraphs":["Chinese New Year, the Spring Festival, begins on the second new moon after the winter solstice and ends with the Lantern Festival on the fifteenth day, so its date moves between late January and late February. On New Year's Eve, the family gathers for the reunion dinner, where fish is served and often deliberately left partly uneaten, since the word for fish sounds like surplus and abundance."]},{"heading":"A broom postponed and red envelopes","paragraphs":["Homes are cleaned before the festival to sweep away the old year, but sweeping on the first day is traditionally avoided so as not to sweep away good fortune. Red is everywhere, from paper cuts to hongbao envelopes of money, and a child may politely refuse a red envelope twice before accepting it.","The travel rush known as chunyun is the largest annual movement of people in the world, as migrants return to hometowns, and it shapes train and road congestion for weeks. Foods, taboos and greetings differ sharply between north and south China and between rural and urban families, and many of the rules are folk beliefs rather than observances."]}]},"context":{"countries":["CN"],"region":"China (nationwide)","continent":"asia","languages":["zh"],"period":"contemporary"},"tags":["traditions","China (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Chinese New Year","de":"Chinese New Year","en":"Chinese New Year"},"url":"https://en.wikipedia.org/wiki/Chinese_New_Year","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Red envelope","de":"Red envelope","en":"Red envelope"},"url":"https://en.wikipedia.org/wiki/Red_envelope","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في ليلة رأس السنة، تأكل عائلة في قوانغدونغ السمك والزلابية وكعك الأرز، ثم تترك عملة تحت الطبق ويبقى الضوء مشتعلاً قبل أول صباح في العام.","de":"Am Neujahrsabend isst eine Familie in Guangdong Fisch, Teigtaschen und Reiskuchen, legt dann eine Münze unter den Teller und lässt vor dem ersten Morgen des Jahres ein Licht brennen.","en":"On New Year's Eve a family in Guangdong eats fish, dumplings and rice cakes, then leaves a coin under the plate and a light on before the first morning of the year."},"misunderstanding":{"ar":"يظن البعض أن ترك السمك دون تناول يعني عدم التقدير، لكنه في الواقع تعبير رمزي عن الوفرة واستمرار الخير.","de":"Manche halten übrig gelassenen Fisch für Verschwendung, doch er symbolisiert Überfluss und den Wunsch, dass der Wohlstand anhält.","en":"Some think leaving fish uneaten is wasteful, but it is a symbolic gesture to invite surplus and ensure prosperity continues."},"comparison":{"ar":"بينما يحرص الشمال على الزلابية، يفضل الجنوب كعك الأرز، لكن كليهما يجتمع على مائدة اللمة وروح العائلة.","de":"Während der Norden Teigtaschen bevorzugt, wählt der Süden Reiskuchen, doch beide treffen sich am Tisch des Wiedersehens und im Geist der Familie.","en":"While the north favors dumplings, the south prefers rice cakes, yet both meet at the reunion table and in the spirit of family."}},{"id":"tra-016","version":2,"slug":"qingming-the-spring-ritual-of-tending-graves","contentType":"note","category":"traditions","title":{"ar":"تشينغ مينغ: طقس الربيع لزيارة القبور","de":"Qingming: das Frühlingsritual der Grabpflege","en":"Qingming: the spring ritual of tending graves"},"deck":{"ar":"عيد تشينغ مينغ، أو 'الصفاء والإشراق'، يحل في أوائل أبريل ويجمع بين تكريم الأجداد والنزهات الربيعية، مع تحولات حديثة في الممارسة.","de":"Qingming, das 'klare und helle' Fest, fällt auf Anfang April und verbindet Ahnenverehrung mit Frühlingsausflügen – mit modernen Veränderungen.","en":"Qingming, or 'clear and bright', falls in early April and blends ancestor veneration with spring outings, with modern shifts in practice."},"teaser":{"ar":"زيارة القبور في الصين ليست مجرد طقس ديني، بل مناسبة عائلية تمتزج فيها العناية بالأجداد بمتعة الربيع.","de":"Der Grabbesuch in China ist nicht nur ein religiöses Ritual, sondern ein Familienanlass, bei dem Ahnenpflege und Frühlingsfreude zusammenkommen.","en":"Grave-visiting in China is not just a religious rite but a family occasion where caring for ancestors meets the joy of spring."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقس عائلي في الهواء الطلق","paragraphs":["يحل عيد تشينغ مينغ في الرابع أو الخامس من أبريل، وهو من الأعياد الصينية القليلة التي تتبع التقويم الشمسي بدلاً من القمري. تزور العائلات القبور لتنظيفها وإزالة الأعشاب وإعادة طلاء النقوش، وتترك القرابين. يحرقون النقود الورقية والبيوت الورقية وحتى الهواتف الورقية للأجداد.","يمتزج تكريم الأجداد بنزهات الربيع: رفع الطائرات الورقية تقليد عريق، وفي منطقة جيانغنان يأكل الناس كوينغتوان، وهي كرات أرز دبقة خضراء ملونة بالشيبة. تختلف هذه الممارسات حسب المنطقة والجيل، فبعض العائلات تكتفي بالزيارة الرمزية."]},{"heading":"عطلة عامة وتحديات حديثة","paragraphs":["أصبح تشينغ مينغ عطلة عامة في الصين القارية عام 2008، وهو الآن فترة سفر كبرى ومركز تحذيرات المرور والسلامة من الحرائق. كما تنمو ممارسة زيارة القبور عبر الإنترنت والقرابين الافتراضية، وتقيد مدن كثيرة حرق القرابين الورقية في الهواء الطلق لأسباب بيئية."]}],"de":[{"heading":"Ein Familienritual im Freien","paragraphs":["Qingming fällt auf den 4. oder 5. April und ist eines der wenigen chinesischen Feste, die sich nach dem Sonnenkalender richten. Familien besuchen die Gräber, jäten Unkraut, erneuern die Inschriften und legen Opfergaben nieder. Sie verbrennen Papiergeld, Papierhäuser und sogar Papierhandys für die Vorfahren.","Die Ahnenverehrung vermischt sich mit Frühlingsausflügen: Drachensteigen ist Tradition, und in der Jiangnan-Region isst man Qingtuan, grüne Klebreisbällchen, die mit Beifuß gefärbt sind. Diese Bräuche variieren je nach Region und Generation; manche Familien besuchen die Gräber nur symbolisch."]},{"heading":"Feiertag und moderne Herausforderungen","paragraphs":["2008 wurde Qingming in Festlandchina zum gesetzlichen Feiertag. Heute ist es eine Hauptreisezeit und ein Schwerpunkt für Verkehrs- und Brandsicherheitswarnungen. Auch das Online-Grabritual und virtuelle Opfergaben nehmen zu, und viele Städte schränken das offene Verbrennen von Papieropfern aus Umweltgründen ein."]}],"en":[{"heading":"A family ritual in the open air","paragraphs":["Qingming falls around 4 or 5 April and is one of the few Chinese festivals fixed by the solar calendar rather than the moon. Families visit graves to sweep, weed, repaint inscriptions and leave offerings. They burn paper money, paper houses and even paper phones for the ancestors.","Ancestor veneration mixes with spring outings: kite flying is traditional, and in the Jiangnan region people eat qingtuan, green glutinous rice balls coloured with mugwort. These practices vary by region and generation, and some families visit graves only symbolically."]},{"heading":"Public holiday and modern challenges","paragraphs":["Qingming became a public holiday in mainland China in 2008. It is now a major travel period and a focus of traffic and fire-safety warnings. Online tomb-sweeping and virtual offerings have grown, and many cities restrict open burning of paper offerings for air quality reasons."]}]},"context":{"countries":["CN"],"region":"China (nationwide)","continent":"asia","languages":["zh"],"period":"contemporary"},"tags":["traditions","China (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Qingming Festival","de":"Qingming Festival","en":"Qingming Festival"},"url":"https://en.wikipedia.org/wiki/Qingming_Festival","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Ancestor veneration in China","de":"Ancestor veneration in China","en":"Ancestor veneration in China"},"url":"https://en.wikipedia.org/wiki/Ancestor_veneration_in_China","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تسافر عائلة إلى مقبرة على تلة، وتقص العشب حول شاهد قبر الجد، وتضع البرتقال وزجاجة بايجيو، وتحرق حزمة من النقود الورقية قبل العودة لتناول الغداء.","de":"Eine Familie fährt zu einem Friedhof am Hang, schneidet das Gras um den Grabstein des Großvaters, legt Orangen und eine Flasche Baijiu nieder und verbrennt ein Bündel Papiergeld, bevor sie zum Mittagessen nach Hause fährt.","en":"A family drives to a hillside cemetery, cuts the grass around a grandfather's stone, lays out oranges and a bottle of baijiu, and burns a bundle of paper money before heading home for lunch."},"misunderstanding":{"ar":"يعتقد البعض أن زيارة القبور واجب ديني صارم، لكنها في الواقع مناسبة عائلية مرنة تختلف حسب المنطقة والظروف.","de":"Manche halten den Grabbesuch für eine strenge religiöse Pflicht, doch er ist ein flexibler Familienanlass, der je nach Region und Umständen unterschiedlich gestaltet wird.","en":"Some assume grave-visiting is a strict religious duty, but it is a flexible family occasion that varies by region and circumstances."},"comparison":{"ar":"في حين تركز العديد من الثقافات على إحياء ذكرى الموتى في مناسبات ثابتة، يجمع تشينغ مينغ بين الحداد والاحتفال بالحياة الربيعية.","de":"Während viele Kulturen das Gedenken an die Toten an festen Terminen begehen, verbindet Qingming Trauer mit der Feier des Frühlingslebens.","en":"While many cultures commemorate the dead on fixed occasions, Qingming combines mourning with a celebration of spring life."}},{"id":"tra-018","version":2,"slug":"holi-a-day-when-the-usual-courtesies-are-suspended","contentType":"note","category":"traditions","title":{"ar":"هولي: يوم تتعطل فيه آداب التعامل المعتادة","de":"Holi: Ein Tag, an dem die üblichen Höflichkeiten aussetzen","en":"Holi: a day when the usual courtesies are suspended"},"deck":{"ar":"في شمال الهند ووسطها، يقلب هولي الأدوار الاجتماعية رأساً على عقب، ويسمح للغرباء بالاقتراب وللخلافات بأن تُحل.","de":"In Nord- und Zentralindien stellt Holi soziale Rollen auf den Kopf, erlaubt Fremden Nähe und lässt alte Streitigkeiten enden.","en":"In north and central India, Holi upends social roles, allows strangers to come close and lets old grudges end."},"teaser":{"ar":"يبدأ هولي ليلة اكتمال القمر في شهر فالغونا، حيث تشتعل نيران هوليكا، وفي اليوم التالي يتناثر الغولال والماء، وتُعلّق قواعد اللباس والتسلسل الهرمي مؤقتاً.","de":"Holi beginnt am Vollmondabend des Monats Phalguna mit den Holika-Feuern; am nächsten Tag fliegen Gulal und Wasser, und Kleiderordnungen sowie Hierarchien sind vorübergehend außer Kraft.","en":"Holi begins on the full-moon night of Phalguna with Holika bonfires; the next day gulal and water fly, and dress codes and hierarchies are temporarily loosened."},"readingMinutes":1,"sections":{"ar":[{"heading":"ليلة النار ونهار الألوان","paragraphs":["يقع هولي في ليلة اكتمال القمر من شهر فالغونا، عادة في مارس، ويبدأ الليلة السابقة بنيران هوليكا داهان، التي ترمز إلى إحراق الشيطانة هوليكا.","في اليوم التالي، يرش الناس الغولال، وهو مسحوق ملون، والماء على الجيران والغرباء، وتُخفف قواعد اللباس والتسلسل الهرمي مؤقتاً."]},{"heading":"عبارة تفتح الأبواب المغلقة","paragraphs":["عبارة شائعة، 'بورا نا مانو، هولي هاي' ('لا تمانع، إنه هولي')، تبيح سلوكاً كان سيكون وقحاً في غير هذا اليوم، ويُستخدم اليوم أيضاً لتسوية الخلافات.","في أحد شوارع جايبور، يلطخ الجيران الذين لم يتحدثوا منذ شهور وجوه بعضهم باللون، ويضحكون ويتشاركون الحلويات، ويُعتبر الخلاف منتهياً. ومع ذلك، يختلف الاحتفال بهولي اختلافاً كبيراً حسب المنطقة والطبقة والمجتمع، وهو حدث أصغر بكثير في أجزاء من جنوب الهند مقارنة بنسخة الشارع الشمالية."]}],"de":[{"heading":"Die Nacht des Feuers, der Tag der Farben","paragraphs":["Holi fällt auf den Vollmond des Monats Phalguna, meist im März, und beginnt am Vorabend mit Holika Dahan, Feuern, die die Verbrennung der Dämonin Holika markieren.","Am nächsten Tag bewerfen Menschen Nachbarn und Fremde mit farbigem Pulver, Gulal, und Wasser; die üblichen Regeln von Kleidung und Hierarchie werden vorübergehend gelockert."]},{"heading":"Ein Satz, der Türen öffnet","paragraphs":["Der häufige Satz „bura na mano, Holi hai“ („Nimm es nicht übel, es ist Holi“) erlaubt Verhalten, das sonst unhöflich wäre, und der Tag wird auch genutzt, um Streitigkeiten beizulegen.","In einer Straße in Jaipur beschmieren Nachbarn, die monatelang nicht miteinander gesprochen haben, ihre Gesichter mit Farbe, lachen, teilen Süßigkeiten, und der Streit gilt als beendet. Allerdings wird Holi je nach Region, Kaste und Gemeinschaft sehr unterschiedlich gefeiert und ist in Teilen Südindiens ein viel kleineres Ereignis als die nordindische Straßenversion."]}],"en":[{"heading":"The night of fire, the day of colour","paragraphs":["Holi falls on the full moon of the month of Phalguna, usually in March, and begins the night before with Holika Dahan, bonfires that mark the burning of the demoness Holika.","The next day people throw coloured powder, gulal, and water at neighbours and strangers, and the usual rules of dress and hierarchy are temporarily loosened."]},{"heading":"A phrase that opens closed doors","paragraphs":["A common phrase, 'bura na mano, Holi hai' ('do not mind, it is Holi'), licenses behaviour that would otherwise be rude, and the day is also used to settle grudges.","In a Jaipur street, neighbours who have not spoken for months smear colour on each other's faces, laugh and share sweets, and the argument is treated as over. Yet Holi is celebrated very differently by region, caste and community, and it is a much smaller event in parts of South India than the northern street version."]}]},"context":{"countries":["IN"],"region":"north and central India","continent":"asia","languages":["hi","en"],"period":"contemporary"},"tags":["traditions","north and central India"],"sources":[{"organization":"Wikipedia","title":{"ar":"Holi","de":"Holi","en":"Holi"},"url":"https://en.wikipedia.org/wiki/Holi","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of India","de":"Culture of India","en":"Culture of India"},"url":"https://en.wikipedia.org/wiki/Culture_of_India","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في أحد شوارع جايبور، يلطخ الجيران الذين لم يتحدثوا منذ شهور وجوه بعضهم باللون، ويضحكون ويتشاركون الحلويات، ويُعتبر الخلاف منتهياً.","de":"In einer Straße in Jaipur beschmieren Nachbarn, die monatelang nicht miteinander gesprochen haben, ihre Gesichter mit Farbe, lachen, teilen Süßigkeiten, und der Streit gilt als beendet.","en":"In a Jaipur street, neighbours who have not spoken for months smear colour on each other's faces, laugh and share sweets, and the argument is treated as over."},"misunderstanding":{"ar":"يعتقد بعض الزوار أن هولي مجرد فوضى عشوائية، لكن العبارة 'بورا نا مانو، هولي هاي' تمنح السلوك المتهور سياقاً واضحاً ومحدوداً.","de":"Manche Besucher halten Holi für bloßes Chaos, doch der Satz „bura na mano, Holi hai“ gibt dem ausgelassenen Verhalten einen klaren und begrenzten Rahmen.","en":"Some visitors think Holi is just random mess, but the phrase 'bura na mano, Holi hai' gives the wild behaviour a clear and limited frame."},"comparison":{"ar":"بينما يُعرف هولي في الشمال برشق الألوان في الشوارع، فإنه في أجزاء من الجنوب يُحتفل به بشكل أكثر هدوءاً وبتركيز أكبر على الطقوس المنزلية.","de":"Während Holi im Norden für Straßenschlachten mit Farben bekannt ist, wird es in Teilen des Südens ruhiger und mit stärkerem Fokus auf häusliche Rituale gefeiert.","en":"While Holi in the north is known for street colour fights, in parts of the south it is celebrated more quietly and with a stronger focus on household rituals."}},{"id":"tra-019","version":2,"slug":"how-families-investigate-a-match-in-india","contentType":"note","category":"family-and-friendship","title":{"ar":"كيف تبحث العائلات الهندية عن شريك","de":"Wie indische Familien Partner prüfen","en":"How Indian Families Investigate a Match"},"deck":{"ar":"زواج مدبر، لقاءات عائلية، ومواقع زواج تغير قواعد اللعبة.","de":"Arrangierte Ehen, Familientreffen und Heiratsportale verändern die Regeln.","en":"Arranged marriages, family meetings, and matrimonial sites are changing the rules."},"teaser":{"ar":"في الهند، لا يزال الزواج المدبر شائعًا، لكن العائلات والأزواج يدمجون التقاليد مع الأدوات الحديثة للعثور على شريك.","de":"In Indien ist die arrangierte Ehe noch weit verbreitet, doch Familien und Paare verbinden Tradition mit modernen Werkzeugen bei der Partnersuche.","en":"In India, arranged marriage remains common, but families and couples are blending tradition with modern tools to find a partner."},"readingMinutes":1,"sections":{"ar":[{"heading":"ملف العريس والعروس","paragraphs":["تُعدّ معظم الزيجات في الهند مدبرة عائليًا، من الترتيب الكامل إلى نصف الترتيب حيث تقدم العائلات الشريك ويقرر الزوجان. يُعدّ الملف الشخصي، أو السيرة الذاتية، وثيقة أساسية تسرد التعليم والوظيفة والخلفية العائلية والطائفة والدخل وأحيانًا برجًا للتوافق.","غالبًا ما يحدث اللقاء الأول في المنزل أو مكان عام بحضور العائلات، وقد يلتقي الزوجان بضع مرات فقط قبل اتخاذ القرار. تبقى الطائفة والدين والمنطقة واللغة مرشحات قوية، رغم أن مواقع الزواج والتطبيقات وسّعت البحث."]},{"heading":"بين العرف والقانون","paragraphs":["المهر غير قانوني بموجب قانون حظر المهر لعام 1961، لكنه يستمر بأشكال مختلفة، وتكاليف الزفاف ومظاهر المكانة قضايا اجتماعية ساخنة. يختلف الزواج المدبر بشكل حاد بين المدن والأرياف، وبين الأجيال، حيث يطالب الشباب بمزيد من الاستقلالية."]}],"de":[{"heading":"Das Profil und das erste Treffen","paragraphs":["Die Mehrheit der indischen Ehen wird familiär vermittelt, von vollständig arrangiert bis halb arrangiert, wo Familien einen möglichen Partner vorstellen und das Paar entscheidet. Ein Heiratsprofil, oder Bio-Data, listet Bildung, Beruf, Familienhintergrund, Kaste, Einkommen und manchmal ein Horoskop für das Kundali-Matching auf.","Das erste Treffen findet oft zu Hause oder an einem öffentlichen Ort mit Familien statt, und das Paar hat vielleicht nur wenige Treffen vor der Entscheidung. Kaste, Religion, Region und Sprache bleiben starke Filter, obwohl Online-Portale und Dating-Apps die Suche erweitert haben."]},{"heading":"Tradition, Recht und Wandel","paragraphs":["Die Mitgift ist nach dem Dowry Prohibition Act von 1961 illegal, aber die Praxis besteht in verschiedenen Formen fort, und Hochzeitskosten und Statusdemonstrationen sind viel diskutierte soziale Themen. Arrangierte Ehen unterscheiden sich stark zwischen städtischen Berufen, dörflichen Allianzen und überregionalen Verbindungen, und Zwang ist ein separates und umstrittenes Thema."]}],"en":[{"heading":"The Bio-Data and the First Meeting","paragraphs":["A majority of Indian marriages still involve family matchmaking, ranging from fully arranged to semi-arranged, where families introduce a possible partner and the couple decides. A matrimonial profile, or bio-data, typically lists education, occupation, family background, caste or subcaste, income and sometimes a horoscope for kundali matching.","The first meeting often happens at home or in a public place with families present, and the couple may have only a few meetings before deciding. Caste, religion, region and language remain strong filters, although online matrimonial sites and dating apps have widened the search and changed how introductions happen."]},{"heading":"Custom, Law, and Generational Shift","paragraphs":["Dowry is illegal under the Dowry Prohibition Act of 1961, but the practice persists in various forms, and wedding costs and status displays are widely discussed social issues. Arranged marriage is not one thing: urban professional matches, village alliances and cross-region marriages differ sharply, and coercion is a separate and contested issue."]}]},"context":{"countries":["IN"],"region":"India (nationwide)","continent":"asia","languages":["hi","en"],"period":"contemporary"},"tags":["family-and-friendship","India (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Arranged marriage in the Indian subcontinent","de":"Arranged marriage in the Indian subcontinent","en":"Arranged marriage in the Indian subcontinent"},"url":"https://en.wikipedia.org/wiki/Arranged_marriage_in_the_Indian_subcontinent","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Indian wedding","de":"Indian wedding","en":"Indian wedding"},"url":"https://en.wikipedia.org/wiki/Indian_wedding","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تتلقى عائلة في بونه عرضًا عبر قريب، وتتحقق من البرج، وتلتقي بعائلة العروس المحتملة على الشاي، ثم يتحدث الشابان على الهاتف لأسابيع قبل الموافقة.","de":"Eine Familie in Pune erhält einen Vorschlag über einen Verwandten, prüft das Horoskop, trifft die Familie der möglichen Braut zum Tee, und die beiden jungen Leute telefonieren dann mehrere Wochen, bevor sie zustimmen.","en":"A family in Pune receives a proposal through a relative, checks the horoscope, meets the prospective bride's family over tea, and the two young people then talk on the phone for several weeks before agreeing."},"misunderstanding":{"ar":"الزواج المدبر ليس شيئًا واحدًا: الزيجات المهنية الحضرية والتحالفات القروية والزيجات عبر المناطق تختلف بشكل حاد، والإكراه قضية منفصلة ومثيرة للجدل.","de":"Arrangierte Ehe ist nicht eins: Städtische Berufsheiraten, Dorfallianzen und überregionale Ehen unterscheiden sich scharf, und Zwang ist ein separates und umstrittenes Thema.","en":"Arranged marriage is not one thing: urban professional matches, village alliances and cross-region marriages differ sharply, and coercion is a separate and contested issue."},"comparison":{"ar":"في حين أن الزواج المدبر في الهند يشبه الترتيبات العائلية في مجتمعات أخرى، فإن الاعتماد على السيرة الذاتية ومرشحات الطائفة يجعله أكثر منهجية.","de":"Während arrangierte Ehen in Indien familiären Arrangements in anderen Gesellschaften ähneln, macht die Betonung von Bio-Data und Kastenfiltern sie systematischer.","en":"While arranged marriage in India resembles family matchmaking in other societies, the reliance on bio-data and caste filters makes it more systematic."}},{"id":"tra-020","version":2,"slug":"dashain-tika-jamara-and-the-long-walk-home","contentType":"note","category":"traditions","title":{"ar":"داشاين: تيكا وجامارا والعودة إلى الديار","de":"Dashain: Tika, Jamara und die Heimreise","en":"Dashain: Tika, Jamara and the Long Walk Home"},"deck":{"ar":"عيد لم شمل وبركة، يجمع العائلات النيبالية على مدى خمسة عشر يومًا في احتفال طويل بالانتصار والخير.","de":"Ein Fest der Familienzusammenführung und des Segens, das nepalesische Familien fünfzehn Tage lang feiert – ein langer Sieg des Guten.","en":"A festival of reunion and blessing, Dashain brings Nepali families together for fifteen days of celebration and the triumph of good."},"teaser":{"ar":"في نيبال، يحمل داشاين الناس من المدن والمنافي إلى بيوت الأجداد، حيث تيكا وجامارا ونقود داكشينا تنتظر الأصغر من الأكبر.","de":"In Nepal bringt Dashain die Menschen aus Städten und dem Ausland zurück zu den Häusern ihrer Vorfahren, wo Tika, Jamara und Dakshina auf die Jüngeren warten.","en":"In Nepal, Dashain draws people from cities and abroad back to ancestral homes, where tika, jamara and dakshina await the younger generation."},"readingMinutes":1,"sections":{"ar":[{"heading":"تيكا وجامارا: بركة تنتقل بين الأجيال","paragraphs":["في اليوم العاشر من داشاين، يضع الكبار مزيجًا من الأرز واللبن واللون القرمزي على جباه الأصغر، ويقدمون براعم الشعير التي نمت في الظلام، مع نقود داكشينا. هذه اللحظة هي قلب العيد، حيث تنتقل البركة من جيل إلى جيل.","يختلف شكل الاحتفال من منطقة إلى أخرى، ومن جيل إلى جيل؛ فبعض العائلات تحافظ على الطقوس القديمة بدقة، بينما يبتكر الشباب طرقًا جديدة للاحتفال."]},{"heading":"العودة إلى البيت: رحلة العيد الكبرى","paragraphs":["داشاين هو أكبر لقاء عائلي في السنة، إذ يسافر الناس من كاتماندو ومن الخارج إلى منازل أجدادهم. إنها أيضًا موسم تسوق رئيسي، حيث تزدحم الأسواق استعدادًا للعيد.","تحتفل الدولة أيضًا بهذا العيد، فتقام مراسم رسمية في مقر الرئاسة، بينما تملأ الطائرات الورقية والأرجوحات الخيزرانية السماء."]}],"de":[{"heading":"Tika und Jamara: Segen von Generation zu Generation","paragraphs":["Am zehnten Tag von Dashain tragen die Älteren eine Mischung aus Reis, Joghurt und Zinnober auf die Stirn der Jüngeren auf und überreichen Gerstensprossen, die im Dunkeln gewachsen sind, zusammen mit dem Geldgeschenk Dakshina. Dieser Moment ist das Herz des Festes, in dem Segen von Generation zu Generation weitergegeben wird.","Die Art der Feier unterscheidet sich je nach Region und Generation; manche Familien halten die alten Rituale genau ein, während junge Menschen neue Wege finden, das Fest zu begehen."]},{"heading":"Heimkehr: Die große Reise des Festes","paragraphs":["Dashain ist das größte Familientreffen des Jahres, wenn Menschen aus Kathmandu und dem Ausland zu ihren angestammten Häusern reisen. Es ist auch eine wichtige Einkaufszeit, in der die Märkte voller Vorbereitungen sind.","Auch der Staat feiert mit: Es gibt offizielle Zeremonien im Präsidentenpalast, während Drachen und Bambusschaukeln den Himmel füllen."]}],"en":[{"heading":"Tika and Jamara: Blessings Across Generations","paragraphs":["On the tenth day of Dashain, elders apply a mixture of rice, yoghurt and vermilion to younger relatives' foreheads and give barley sprouts grown in the dark, along with a gift of money called dakshina. This moment is the heart of the festival, where blessings pass from one generation to the next.","The way the festival is celebrated varies by region and generation; some families keep the old rituals exactly, while young people find new ways to mark the occasion."]},{"heading":"Coming Home: The Great Journey of the Festival","paragraphs":["Dashain is the biggest family reunion of the year, as people travel from Kathmandu and abroad to their ancestral homes. It is also a major shopping season, with markets bustling with preparations.","The state celebrates too, with official rituals at the presidential residence, while kites and bamboo swings fill the sky."]}]},"context":{"countries":["NP"],"region":"Nepal (nationwide)","continent":"asia","languages":["ne"],"period":"contemporary"},"tags":["traditions","Nepal (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Dashain","de":"Dashain","en":"Dashain"},"url":"https://en.wikipedia.org/wiki/Dashain","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Nepal","de":"Culture of Nepal","en":"Culture of Nepal"},"url":"https://en.wikipedia.org/wiki/Culture_of_Nepal","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عامل مهاجر يعود إلى قريته في حافلة مزدحمة، يتلقى التيكا من جدته، يربط براعم الشعير خلف أذنه، ويأكل الكاري مع أبناء عمومته الذين لم يرهم طوال العام.","de":"Ein Wanderarbeiter kehrt in einem überfüllten Bus in sein Dorf zurück, empfängt Tika von seiner Großmutter, bindet Gerstensprossen hinter sein Ohr und isst Ziegencurry mit Cousins, die er ein Jahr lang nicht gesehen hat.","en":"A migrant worker takes a crowded bus home, receives tika from his grandmother, ties barley sprouts behind his ear and eats goat curry with cousins he has not seen all year."},"misunderstanding":{"ar":"يعتقد البعض أن داشاين مهرجان ديني فقط، لكنه في الواقع مناسبة اجتماعية واقتصادية كبرى تجمع العائلات وتنعش الأسواق.","de":"Manche glauben, Dashain sei nur ein religiöses Fest, doch tatsächlich ist es ein großes soziales und wirtschaftliches Ereignis, das Familien zusammenbringt und die Märkte belebt.","en":"Some think Dashain is only a religious festival, but it is actually a major social and economic event that brings families together and boosts markets."},"comparison":{"ar":"يشبه داشاين في كونه لقاء عائليًا كبيرًا أعياد الشكر في ثقافات أخرى، لكنه يتميز بطقوس التيكا والجامارا التي ترمز إلى البركة والانتصار.","de":"Dashain ähnelt in seiner Funktion als großes Familientreffen Erntedankfesten anderer Kulturen, zeichnet sich aber durch die Tika- und Jamara-Rituale aus, die Segen und Sieg symbolisieren.","en":"Dashain is similar to thanksgiving festivals in other cultures as a big family reunion, but it is distinguished by tika and jamara rituals symbolizing blessing and victory."}},{"id":"tra-021","version":2,"slug":"pohela-boishakh-new-year-under-the-banyan-tree","contentType":"note","category":"traditions","title":{"ar":"بويلا بويشاخ: العام الجديد تحت شجرة البانيان","de":"Pohela Boishakh: Neujahr unter dem Banyanbaum","en":"Pohela Boishakh: New Year under the banyan tree"},"deck":{"ar":"كيف تحتفل بنغلاديش برأس السنة البنغالية في 14 أبريل","de":"Wie Bangladesch am 14. April das bengalische Neujahr feiert","en":"How Bangladesh celebrates the Bengali New Year on 14 April"},"teaser":{"ar":"من الأغاني الجماعية تحت شجرة البانيان إلى موكب ماسك العملاقة، تعرف على تقاليد بويلا بويشاخ في دكا والبنغال.","de":"Von Chorgesängen unter dem Banyanbaum bis zur Prozession mit riesigen Masken: Entdecken Sie die Traditionen von Pohela Boishakh in Dhaka und Bengalen.","en":"From choral songs under the banyan tree to a procession of giant masks, discover the traditions of Pohela Boishakh in Dhaka and Bengal."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقوس الصباح والموكب","paragraphs":["يبدأ يوم بويلا بويشاخ في دكا بالأغاني الجماعية تحت شجرة البانيان في رامنا باتامول، حيث يجتمع الناس في الصباح الباكر.","ثم يمر موكب مانغال شوباجاترا بماسكه العملاقة وزخارفه، والذي أُدرج في قائمة اليونسكو للتراث غير المادي في 2016.","تختلف الاحتفالات بين المناطق والأجيال؛ فبعض العائلات تكتفي بالاجتماع العائلي، بينما يحرص الشباب على حضور الفعاليات العامة."]},{"heading":"حلخاتا: دفتر حسابات جديد","paragraphs":["يحتفظ التجار وأصحاب المتاجر بعادة الحلخاتا، فيغلقون دفاتر الحسابات القديمة ويدعون الزبائن لتناول الحلويات وفتح دفتر جديد في أول يوم من العام.","وتشمل الأطعمة التقليدية بانطا بهات، وهو أرز منقوع ليلة كاملة، ويُقدم مع سمك الهيلسا المقلي، ويرتدي الناس الأبيض والأحمر.","تشكلت هذه الاحتفالات العامة الحديثة بفعل الحركة الثقافية في ستينيات القرن الماضي في شرق باكستان، وأصبحت رمزًا للهوية البنغالية العلمانية بعد الاستقلال."]}],"de":[{"heading":"Morgenrituale und die Prozession","paragraphs":["In Dhaka beginnt der Tag von Pohela Boishakh mit Chorgesängen unter dem Banyanbaum am Ramna Batamul, wo die Menschen früh am Morgen zusammenkommen.","Dann zieht die Mangal Shobhajatra-Prozession mit ihren riesigen Masken und Motiven vorbei, die 2016 in die UNESCO-Liste des immateriellen Kulturerbes aufgenommen wurde.","Die Feierlichkeiten variieren je nach Region und Generation; manche Familien bleiben unter sich, während junge Leute die öffentlichen Veranstaltungen besuchen."]},{"heading":"Halkhata: ein frisches Rechnungsbuch","paragraphs":["Händler und Geschäftsleute pflegen den Halkhata-Brauch: Sie schließen die alten Kontobücher und laden Kunden zu Süßigkeiten und einem neuen Ledger am ersten Tag des Jahres ein.","Zum traditionellen Essen gehört Panta Bhat, über Nacht eingeweichter fermentierter Reis, serviert mit gebratenem Hilsa-Fisch; die Menschen kleiden sich in Weiß und Rot.","Die moderne öffentliche Form wurde durch die kulturelle Bewegung der 1960er Jahre in Ostpakistan geprägt und wurde nach der Unabhängigkeit zu einem Symbol säkularer bengalischer Identität."]}],"en":[{"heading":"Morning rituals and the procession","paragraphs":["In Dhaka, Pohela Boishakh opens with choral songs under the banyan tree at Ramna Batamul, where people gather early in the morning.","Then the Mangal Shobhajatra procession of giant masks and motifs passes by; it was inscribed on UNESCO's intangible heritage list in 2016.","Celebrations vary by region and generation: some families keep to themselves, while younger people attend public events."]},{"heading":"Halkhata: a fresh ledger","paragraphs":["Shops and traders keep the halkhata custom, closing old account books and inviting customers for sweets and a fresh ledger on the first day of the year.","Traditional food includes panta bhat, fermented rice soaked overnight, served with fried hilsa fish, and people dress in white and red.","The modern public form was shaped by the 1960s cultural movement in East Pakistan and became a symbol of secular Bengali identity after independence."]}]},"context":{"countries":["BD"],"region":"Dhaka and Bengal","continent":"asia","languages":["bn"],"period":"contemporary"},"tags":["traditions","Dhaka and Bengal"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pohela Boishakh","de":"Pohela Boishakh","en":"Pohela Boishakh"},"url":"https://en.wikipedia.org/wiki/Pohela_Boishakh","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Bangladesh","de":"Culture of Bangladesh","en":"Culture of Bangladesh"},"url":"https://en.wikipedia.org/wiki/Culture_of_Bangladesh","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"تستيقظ عائلة في دكا مبكرًا، وتمشي إلى حديقة رامنا بالملابس البيضاء والحمراء، وتشاهد ماسك مانغال شوباجاترا وهي تمر، ثم تأكل بانطا بهات مع الهيلسا المقلي في منزل أحد الأقارب.","de":"Eine Familie in Dhaka steht früh auf, geht in Weiß und Rot zum Ramna-Park, sieht die Masken der Mangal Shobhajatra vorbeiziehen und isst dann bei Verwandten Panta Bhat mit gebratenem Hilsa.","en":"A Dhaka family rises early, walks to Ramna Park in white and red, watches the masks of Mangal Shobhajatra pass, then eats panta bhat with fried hilsa at a relative's house."},"misunderstanding":{"ar":"ليس كل البنغال يحتفلون بنفس الطريقة؛ فالتقاليد الريفية وعادة الحلخاتا والنسخة الغربية البنغالية تختلف جميعها.","de":"Nicht ganz Bengalen feiert gleich: Ländliche Bräuche, die Halkhata-Praxis und die westbengalische Version unterscheiden sich.","en":"Not all of Bengal celebrates the same way: rural customs, halkhata practice and the West Bengal version all differ."},"comparison":{"ar":"بينما تحتفل دكا بالموكب والأغاني الجماعية، تحتفل كلكتا بالعام الجديد في 14 أو 15 أبريل حسب التقويم التقليدي.","de":"Während Dhaka mit Prozession und Chorgesängen feiert, begeht Kolkata das Neujahr je nach traditionellem Kalender am 14. oder 15. April.","en":"While Dhaka celebrates with processions and choral songs, Kolkata marks the new year on 14 or 15 April depending on the traditional calendar."}},{"id":"tra-022","version":2,"slug":"a-pakistani-wedding-is-a-week-of-separate-events","contentType":"note","category":"family-and-friendship","title":{"ar":"زفاف باكستاني: أسبوع من الاحتفالات المنفصلة","de":"Eine pakistanische Hochzeit dauert eine Woche","en":"A Pakistani wedding runs a week of separate events"},"deck":{"ar":"من الحنّاء إلى الوليمة، تُقسَّم الأعراس الباكستانية إلى مناسبات متتابعة، وتتفاوت بين الأسر في الحجم والترتيب.","de":"Von der Henna-Nacht bis zum Empfang: Pakistanische Hochzeiten bestehen aus mehreren Feiern, die Familien unterschiedlich zusammenlegen oder trennen.","en":"From the henna night to the reception, Pakistani weddings unfold as a sequence of functions that families combine or split in their own way."},"teaser":{"ar":"في باكستان لا يكون الزفاف ليلة واحدة، بل سلسلة مناسبات تتوزع على أيام، وتختلف بين أسرة وأخرى في الجمع والفصل.","de":"In Pakistan ist die Hochzeit selten ein Abend. Mehndi, Baraat, Nikah und Valima folgen aufeinander, und jede Familie ordnet sie anders.","en":"In Pakistan the wedding is rarely one evening. Mehndi, baraat, nikah and valima follow one another, and each family arranges them differently."},"readingMinutes":1,"sections":{"ar":[{"heading":"مناسبات متتابعة لا ليلة واحدة","paragraphs":["يشمل الزفاف الباكستاني عادةً عدة مناسبات: الحنّاء، والبَرَات، والنكاح، والوليمة، وأحياناً الرحيل، وتدمج الأسر هذه المناسبات أو تفصلها بطرق مختلفة.","الحنّاء ليلة غناء ورقص تستضيفها أسرة العروس عادةً، والبَرَات موكب العريس عند وصوله إلى الحفل، والوليمة استقبال تقيمه أسرة العريس."]},{"heading":"العقد وحجم الاحتفال","paragraphs":["النكاح هو عقد الزواج الإسلامي، ويشترط رضا العروس وشاهدين ومهراً يُوعد به للعروس، ويُسجَّل في وثيقة النكاح.","حجم الزفاف موضوع عام: تتفاوض الأسر على القاعات وقوائم المدعوين والملابس، وقد تخلق كلفة الاستعراض ديوناً.","وتختلف الممارسة اختلافاً حاداً بين الأسر البنجابية والسندية والبشتونية والبلوشية، وبين البيوت المتدينة والعلمانية والمختلطة."]}],"de":[{"heading":"Mehrere Feste statt einer Nacht","paragraphs":["Eine pakistanische Hochzeit umfasst meist mehrere Feiern: Mehndi, Baraat, Nikah, Valima und manchmal Rukhsati; Familien verbinden oder trennen sie auf verschiedene Weise.","Das Mehndi ist eine Henna-Nacht mit Liedern und Tanz, meist vom Haus der Braut ausgerichtet, während der Baraat der Festzug des Bräutigams zur Zeremonie ist."]},{"heading":"Der Vertrag und der Aufwand","paragraphs":["Der Nikah ist der islamische Ehevertrag; er verlangt die Zustimmung der Braut, zwei Zeugen und eine Brautgabe, die im Nikah nama festgehalten wird.","Der Umfang der Hochzeit ist ein öffentliches Thema: Familien verhandeln Orte, Gästelisten und Kleidung, und die Kosten der Selbstdarstellung können Schulden verursachen.","Die Praxis unterscheidet sich stark zwischen punjabi-, sindhi-, paschtunischen und belutschischen Familien sowie zwischen frommen, säkularen und gemischten Haushalten."]}],"en":[{"heading":"Several functions, not one night","paragraphs":["A Pakistani wedding commonly spans several functions: mehndi, baraat, nikah, valima and sometimes rukhsati, and different families combine or separate them in different ways.","The mehndi is a henna night with songs and dancing, usually hosted by the bride's family, while the baraat is the groom's procession arriving for the ceremony."]},{"heading":"The contract and the cost of display","paragraphs":["The nikah is the Islamic marriage contract; it requires the bride's consent, two witnesses and a mahr, the dower promised to the bride, and it is recorded in a nikah nama.","The scale of weddings is a public topic: families negotiate venues, guest lists and clothing, and the cost of display can create debt.","Practice differs sharply between Punjabi, Sindhi, Pashtun and Baloch families, and between devout, secular and mixed households, so the big wedding is not universal."]}]},"context":{"countries":["PK"],"region":"Pakistan (nationwide)","continent":"asia","languages":["ur","en"],"period":"contemporary"},"tags":["family-and-friendship","Pakistan (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Pakistani wedding","de":"Pakistani wedding","en":"Pakistani wedding"},"url":"https://en.wikipedia.org/wiki/Pakistani_wedding","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Pakistan","de":"Culture of Pakistan","en":"Culture of Pakistan"},"url":"https://en.wikipedia.org/wiki/Culture_of_Pakistan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في لاهور تغني قريبات العروس حول الطبل في ليلة الحنّاء، ويصل العريس في المساء التالي بسيارة مزينة بالزهور، ويُوقَّع النكاح أمام الأسرتين.","de":"In Lahore singen die Cousinen der Braut beim Mehndi zum Dhol, am nächsten Abend kommt der Bräutigam mit einem blumengeschmückten Auto, und der Nikah wird vor beiden Familien unterschrieben.","en":"In Lahore, the bride's cousins sing around a dhol at the mehndi, the groom arrives the next evening with a flower-decorated car, and the nikah is signed in front of both families."},"misunderstanding":{"ar":"يظن كثيرون أن الزفاف الباكستاني ليلة واحدة، والحال أنه سلسلة مناسبات قد تجمعها الأسرة في يومين أو تفرّقها على أسبوع.","de":"Viele halten die pakistanische Hochzeit für einen einzigen Abend, doch sie ist eine Reihe von Feiern, die man auf zwei Tage raffen oder über eine Woche verteilen kann.","en":"Many assume a Pakistani wedding is a single evening, but it is a chain of functions that a family may compress into two days or stretch across a week."},"comparison":{"ar":"يقارن كثيرون هذا الترتيب بحفلات الزفاف في بلدان أخرى حيث تُجمع المراسم في يوم واحد، فيبدو التوزيع الباكستاني أكثر تفصيلاً.","de":"Im Vergleich zu Ländern, die alle Zeremonien an einem Tag bündeln, wirkt die pakistanische Aufteilung ausführlicher und stärker auf einzelne Familien abgestimmt.","en":"Set beside countries that bundle every rite into one day, the Pakistani arrangement looks more drawn out and more closely negotiated by each family."}},{"id":"tra-023","version":2,"slug":"shinbyu-a-burmese-boy-s-season-as-a-novice","contentType":"note","category":"traditions","title":{"ar":"شينبيو: موسم صبي بورمي كراهب مبتدئ","de":"Shinbyu: Die Novizenzeit eines burmesischen Jungen","en":"Shinbyu: A Burmese Boy's Season as a Novice"},"deck":{"ar":"طقس يتحول فيه الصبي إلى أمير ثم إلى راهب، في رحلة مؤقتة نحو النضج الروحي.","de":"Ein Ritual, das einen Jungen erst zum Prinzen und dann zum Novizen macht – eine zeitweilige Reise zum spirituellen Erwachsenwerden.","en":"A ritual that turns a boy into a prince and then a monk, a temporary journey toward spiritual maturity."},"teaser":{"ar":"في ميانمار، يرتدي الصبي ملابس الأمير قبل أن يحلق رأسه ويرتدي ثوب الراهب، في تقليد عائلي يربط بين الطفولة والرهبنة.","de":"In Myanmar trägt ein Junge Prinzenkleidung, bevor er kahlgeschoren wird und die Robe eines Novizen anlegt – ein Familientradition, die Kindheit und Klosterleben verbindet.","en":"In Myanmar, a boy dresses as a prince before shaving his head and donning a novice's robes—a family tradition linking childhood and monastic life."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الأمير إلى المبتدئ","paragraphs":["شينبيو هو طقس رسامة مبتدئ في البوذية التيرافادية، حيث يصبح الصبي، غالبًا بين السابعة والخامسة عشرة، راهبًا مبتدئًا مؤقتًا. يُقام عادة في العطلات المدرسية أو قبل الصوم البوذي، ويُعد عملاً من أعمال الكسب الروحي للعائلة بأكملها.","يرتدي الصبي ملابس الأمير، في إشارة إلى تخلي الأمير سيدهارتا عن حياته الدنيوية، ويُطاف به في موكب على ظهر حصان أو في سيارة، ثم يُحلق رأسه ويرتدي الثوب الرهباني."]},{"heading":"مدة التكريس وتنوع الممارسة","paragraphs":["تتفاوت مدة الإقامة من بضعة أيام إلى فترة الصوم الكامل، وبعض الرجال يعيدون الرسامة لاحقًا كبالغين. في المناطق الحضرية قد تقتصر الاحتفالات على وقت أقصر، وتختلف الممارسة حسب المنطقة والدخل والإرشاد الرهباني.","كما تقيم بعض العائلات التي لديها بنات طقس ثقب الأذن (ناhtwin) كطقس موازٍ للبلوغ بدلاً من الرسامة."]}],"de":[{"heading":"Vom Prinzen zum Novizen","paragraphs":["Shinbyu ist eine Noviziationszeremonie im Theravada-Buddhismus, bei der ein Junge, oft zwischen sieben und fünfzehn Jahren, vorübergehend als Novize ordiniert wird. Sie wird meist in den Schulferien oder vor der buddhistischen Fastenzeit arrangiert und gilt als verdienstvolles Werk für die ganze Familie.","Der Junge wird wie ein Prinz gekleidet, in Anspielung auf die Entsagung von Prinz Siddhartha, in einer Prozession zu Pferd oder im Auto durch die Straßen geführt, dann wird sein Kopf rasiert und er legt die Roben an."]},{"heading":"Dauer und regionale Unterschiede","paragraphs":["Die Aufenthaltsdauer variiert von wenigen Tagen bis zur gesamten Fastenzeit; manche Männer wiederholen die Ordination später als Erwachsene. In städtischen Familien kann die Zeremonie kürzer ausfallen, und die Praxis unterscheidet sich je nach Region, Einkommen und klösterlicher Anleitung.","Familien mit Töchtern veranstalten manchmal eine Ohrlochungszeremonie, nahtwin, als paralleles Initiationsritual anstelle der Noviziation."]}],"en":[{"heading":"From Prince to Novice","paragraphs":["Shinbyu is a novitiation ceremony in Theravada Buddhism in which a boy, often between seven and fifteen, is temporarily ordained as a novice monk. It is usually arranged during school holidays or before Buddhist Lent and is a merit-making act for the whole family.","The boy is dressed as a prince, referencing Prince Siddhartha's renunciation, paraded in a procession on horseback or in a car, then has his head shaved and puts on robes."]},{"heading":"Length of Stay and Variation","paragraphs":["The length of stay varies from a few days to a whole Lent period, and some men repeat the ordination later as adults. Urban families may keep the ceremony short, and practice differs by region, income and monastic guidance.","Families with daughters sometimes hold an ear-boring ceremony, nahtwin, as a parallel coming-of-age rite rather than a novitiation."]}]},"context":{"countries":["MM"],"region":"Myanmar (nationwide)","continent":"asia","languages":["my"],"period":"contemporary"},"tags":["traditions","Myanmar (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Shinbyu","de":"Shinbyu","en":"Shinbyu"},"url":"https://en.wikipedia.org/wiki/Shinbyu","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Myanmar","de":"Culture of Myanmar","en":"Culture of Myanmar"},"url":"https://en.wikipedia.org/wiki/Culture_of_Myanmar","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة في ماندالاي تستأجر فرقة موسيقية، وتلبس ابنها الحرير والذهب، وتطوف به في الحي، وفي صباح اليوم التالي يجلس في فناء الدير برأس محلوق ووعاء.","de":"Eine Familie in Mandalay engagiert eine Band, kleidet den Sohn in Seide und Gold, führt ihn durch das Viertel, und am nächsten Morgen sitzt er mit kahlgeschorenem Kopf und Bettelschale im Klosterhof.","en":"A family in Mandalay hires a band, dresses their son in silk and gold, parades him through the ward, and the next morning he sits in the monastery courtyard with a shaved head and a bowl."},"misunderstanding":{"ar":"قد يُفهم أن شينبيو هو قرار دائم بالرهبنة، لكنه في الواقع فترة مؤقتة تهدف إلى تعلم التأمل والانضباط، ويعود الصبي بعدها إلى حياته العادية.","de":"Shinbyu wird oft als dauerhafte Entscheidung für das Klosterleben missverstanden, ist aber eine zeitlich begrenzte Phase, die der Schulung in Meditation und Disziplin dient; danach kehrt der Junge in sein normales Leben zurück.","en":"Shinbyu is often mistaken for a permanent commitment to monastic life, but it is a temporary period for learning meditation and discipline, after which the boy returns to ordinary life."},"comparison":{"ar":"يشبه شينبيو طقوس البلوغ في ثقافات أخرى، لكنه يتميز بطابعه البوذي وجمعه بين الاحتفال العائلي والتدريب الروحي.","de":"Shinbyu ähnelt Initiationsriten in anderen Kulturen, ist aber durch seinen buddhistischen Charakter und die Verbindung von Familienfeier und spiritueller Ausbildung geprägt.","en":"Shinbyu resembles coming-of-age rites in other cultures but is distinct in its Buddhist framing and its combination of family celebration and spiritual training."}},{"id":"tra-024","version":2,"slug":"songkran-water-as-blessing-water-as-play","contentType":"scene","category":"traditions","title":{"ar":"سونغكران: الماء بركة ولعب","de":"Songkran: Wasser als Segen, Wasser als Spiel","en":"Songkran: water as blessing, water as play"},"deck":{"ar":"في تايلاند، يحيي الناس رأس السنة بالماء: سكب على الأيدي للبركة، ورشّ في الشوارع للاحتفال.","de":"In Thailand feiern die Menschen das neue Jahr mit Wasser: gegossen als Segen, verspritzt als ausgelassene Straßenfeier.","en":"In Thailand, people mark the new year with water: poured as a blessing, splashed as a street celebration."},"teaser":{"ar":"من سكب الماء على أيدي كبار السن إلى معارك الماء في الشوارع، يحمل سونغكران معنيين متشابكين: البركة والمرح.","de":"Vom Wasserguss über die Hände der Ältesten bis zur Wasserchlacht auf der Straße vereint Songkran zwei Seiten: Segen und Ausgelassenheit.","en":"From pouring water over elders' hands to street water fights, Songkran holds two intertwined meanings: blessing and play."},"readingMinutes":1,"sections":{"ar":[{"heading":"طقوس البركة","paragraphs":["يمثل سونغكران رأس السنة التايلاندية من 13 إلى 15 أبريل، حيث يُسكب الماء على صور بوذا وعلى أيدي كبار السن كبركة للعام القادم.","الطقس الأصلي هو روت نام دام هوا، سكب ماء معطر على أيدي كبار السن لطلب المغفرة وتلقي البركات؛ أما معركة الماء في الشوارع فهي ظاهرة لاحقة وأكبر.","تعود العائلات إلى منازلها، وتنظف البيوت، وتؤدي الأعمال الخيرة في المعابد، وأحيانًا تحضر الرمل لبناء أبراج صغيرة في ساحات المعابد."]},{"heading":"بين العائلة والمهرجان","paragraphs":["أصبح المهرجان وجهة سياحية مع حفلات الرغوة والحفلات الموسيقية، كما تشتهر فترة العطلة بوفيات الطرق، مما يدفع إلى حملات سلامة سنوية.","تختلف الممارسة حسب المنطقة: تشيانغ ماي تستضيف مهرجانًا كبيرًا في الشوارع، بينما تحافظ许多 المجتمعات الجنوبية والريفية على تركيز عائلي ومعبدي أهدأ.","يختلف الاحتفال أيضًا بين الأجيال: فالشباب ينجذبون إلى الفعاليات العامة، بينما يتمسك كبار السن بالطقوس المنزلية."]}],"de":[{"heading":"Das Ritual des Segens","paragraphs":["Songkran markiert das thailändische Neujahr vom 13. bis 15. April, wenn Wasser über Buddha-Statuen und über die Hände der Ältesten gegossen wird – als Segen für das kommende Jahr.","Der ursprüngliche Ritus ist rot nam dam hua, das Gießen von duftendem Wasser über die Hände der Ältesten, um Vergebung zu bitten und Segen zu empfangen; die öffentliche Wasserschlacht ist ein späteres, größeres Phänomen.","Familien kehren nach Hause zurück, reinigen die Häuser und machen Verdienste in den Tempeln, manchmal bringen sie Sand mit, um kleine Pagoden auf dem Tempelgelände zu bauen."]},{"heading":"Zwischen Familie und Festival","paragraphs":["Das Fest ist zu einer Touristenattraktion mit Schaumpartys und Konzerten geworden, und die Feiertage sind auch für Verkehrstote berüchtigt, was jährliche Sicherheitskampagnen auslöst.","Die Praxis variiert regional: Chiang Mai veranstaltet ein großes Straßenfest, während viele südliche und ländliche Gemeinden einen ruhigeren Familien- und Tempelfokus bewahren.","Auch zwischen den Generationen gibt es Unterschiede: Jüngere fühlen sich von öffentlichen Events angezogen, während Ältere an den häuslichen Ritualen festhalten."]}],"en":[{"heading":"The rite of blessing","paragraphs":["Songkran marks the Thai new year from 13 to 15 April, when water is poured over Buddha images and over elders' hands as a blessing for the coming year.","The original rite is rot nam dam hua, pouring scented water on elders' hands to ask forgiveness and receive blessings; the public street water fight is a later, larger phenomenon.","Families return home, clean houses and make merit at temples, sometimes bringing sand to build small pagodas in the temple grounds."]},{"heading":"Between family and festival","paragraphs":["The festival has become a tourism draw with foam parties and concerts, and the holiday period is also notorious for road deaths, prompting annual safety campaigns.","Regional practice differs: Chiang Mai hosts a major street festival, while many southern and rural communities keep a quieter family and temple focus.","Generational differences also shape the celebration: younger people are drawn to public events, while older generations hold to the domestic rites."]}]},"context":{"countries":["TH"],"region":"Thailand (nationwide)","continent":"asia","languages":["th"],"period":"contemporary"},"tags":["traditions","Thailand (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Songkran (Thailand)","de":"Songkran (Thailand)","en":"Songkran (Thailand)"},"url":"https://en.wikipedia.org/wiki/Songkran_(Thailand)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Thailand","de":"Culture of Thailand","en":"Culture of Thailand"},"url":"https://en.wikipedia.org/wiki/Culture_of_Thailand","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في الصباح الأول، تسكب موظفة في بانكوك ماءً معطرًا على يدي جدتها، وتتلقى بركة، وبعد ذلك فقط تنضم إلى معركة الماء في شارع سيلوم.","de":"Am ersten Morgen gießt eine Büroangestellte aus Bangkok duftendes Wasser über die Hände ihrer Großmutter, empfängt einen Segen und schließt sich erst später der Wasserschlacht auf der Silom Road an.","en":"On the first morning, a Bangkok office worker pours scented water over her grandmother's hands, receives a blessing, and only later joins the water fight on Silom Road."},"misunderstanding":{"ar":"الصورة السياحية طغت على الطقس المحلي، وليس الجميع يرحب برشّ الماء، لذا ينبغي وصف البركة والحفلة كمرتبطتين لكنهما متميزتان.","de":"Das Touristenbild hat den häuslichen Ritus überschattet, und nicht jeder mag es, bespritzt zu werden; daher sollten Segen und Party als verwandt, aber getrennt beschrieben werden.","en":"The tourist image has overshadowed the domestic rite, and not everyone welcomes being splashed, so the blessing and the party should be described as related but distinct."},"comparison":{"ar":"بينما يركز سونغكران على الماء كبركة، تحتفل многие الثقافات برأس السنة بالنار أو الضوء؛ هنا الماء وسيلة للتطهير والتجديد.","de":"Während Songkran Wasser als Segen betont, feiern viele Kulturen Neujahr mit Feuer oder Licht; hier ist Wasser Mittel der Reinigung und Erneuerung.","en":"While Songkran emphasizes water as a blessing, many cultures celebrate the new year with fire or light; here water is a medium of purification and renewal."}},{"id":"tra-025","version":2,"slug":"tet-the-first-visitor-decides-the-year","contentType":"note","category":"traditions","title":{"ar":"تيت: أول زائر يحدد السنة","de":"Tết: Der erste Besucher bestimmt das Jahr","en":"Tết: the first visitor decides the year"},"deck":{"ar":"في رأس السنة القمرية الفيتنامية، يستقبل الناس ضيفًا مختارًا بعناية، ويودّعون آلهة المطبخ، ويتجنبون الكنس في الأيام الأولى.","de":"Zum vietnamesischen Mondneujahr wählen Familien ihren ersten Gast mit Bedacht, verabschieden den Küchengott und vermeiden am ersten Tag den Besen.","en":"At Vietnamese lunar new year, families choose their first guest carefully, send off the Kitchen God, and avoid sweeping on the first days."},"teaser":{"ar":"عيد تيت أكبر مناسبة في فيتنام، حيث تتوقف المتاجر وتنتقل العائلات لأسابيع، ويُعتقد أن أول داخل إلى البيت يصوغ حظ أهله.","de":"Tết ist Vietnams größtes Fest, wochenlang reisen Menschen und Geschäfte schließen; der erste Besucher im Haus soll das Glück der Familie prägen.","en":"Tết is Vietnam's biggest holiday, with weeks of travel and closed shops, and the first visitor to a home is believed to shape the household's luck."},"readingMinutes":1,"sections":{"ar":[{"heading":"من يطرق الباب أولًا","paragraphs":["يبدأ تيت نغوين دان بين أواخر يناير ومنتصف فبراير، وهو أكبر عيد في السنة، تصحبه أسابيع من السفر وإغلاق المتاجر. ويُعتقد أن أول زائر يدخل البيت في العام الجديد، ويسمى سوونغ دات، يصوغ حظ الأسرة، فتدعو العائلات شخصًا مناسبًا عن قصد وتتجنب الضيوف المشؤومين.","في اليوم الثالث والعشرين من الشهر القمري الثاني عشر تودّع الأسر إله المطبخ، أونغ تاو، الذي يُقال إنه يركب سمكة مبروكة إلى السماء ليقدم تقريرًا عن أهل البيت."]},{"heading":"تقاليد تختلف بين الشمال والجنوب","paragraphs":["تُزيَّن البيوت بزهور الخوخ في الشمال وزهور المشمش في الجنوب، وتُعدّ كعكات الأرز الدبق، بان تشانغ في الشمال وبان تيت في الجنوب، أطعمة محورية. وتشمل المحظورات الشائعة عدم الكنس في الأيام الأولى وتجنب كسر الأشياء وتجنب الملابس السوداء والبيضاء، وإن كان الجيل الأصغر يتعامل معها بخفة.","تختلف العادات بين شمال فيتنام وجنوبها وبين الأسر البوذية والمسيحية والعلمانية، وكثير من المحظورات يُراعى اجتماعيًا أكثر مما يُعتقد به حرفيًا."]}],"de":[{"heading":"Wer zuerst an die Tür klopft","paragraphs":["Tết Nguyên Đán fällt zwischen Ende Januar und Mitte Februar und ist der größte Feiertag des Jahres, begleitet von wochenlangen Reisen und geschlossenen Geschäften. Der erste Besucher im neuen Jahr, der xông đất, soll das Glück des Haushalts prägen, deshalb laden Familien gezielt geeignete Personen ein und meiden Unglücksbringer.","Am dreiundzwanzigsten Tag des zwölften Mondmonats verabschieden Familien den Küchengott Ông Táo, der der Überlieferung nach auf einem Karpfen in den Himmel reitet, um über den Haushalt zu berichten."]},{"heading":"Bräuche zwischen Norden und Süden","paragraphs":["Häuser werden im Norden mit Pfirsichblüten, im Süden mit Aprikosenblüten geschmückt; Klebreiskuchen, bánh chưng im Norden und bánh tét im Süden, stehen im Mittelpunkt. Zu den Tabus zählen das Fegen an den ersten Tagen, das Zerbrechen von Dingen sowie schwarze und weiße Kleidung, doch jüngere Generationen nehmen sie oft locker.","Die Bräuche unterscheiden sich zwischen Nord- und Südvietnam sowie zwischen buddhistischen, christlichen und säkularen Haushalten, und viele Tabus werden sozial beachtet statt wörtlich geglaubt."]}],"en":[{"heading":"Who knocks first","paragraphs":["Tết Nguyên Đán falls between late January and mid-February and is the biggest holiday of the year, with weeks of travel and closed shops. The first visitor to enter a home in the new year, the xông đất, is believed to shape the household's luck, so families may invite a suitable person deliberately and avoid unlucky guests.","On the twenty-third day of the twelfth lunar month, families send off the Kitchen God, Ông Táo, who is said to ride a carp to heaven to report on the household."]},{"heading":"Customs that split north and south","paragraphs":["Homes are decorated with peach blossom in the north and apricot blossom in the south, and sticky-rice cakes, bánh chưng in the north and bánh tét in the south, are central foods. Common taboos include not sweeping on the first days, avoiding breaking things and avoiding black or white clothing, though younger generations often treat them lightly.","Customs differ between north and south Vietnam and between Buddhist, Christian and secular households, and many taboos are observed socially rather than literally believed."]}]},"context":{"countries":["VN"],"region":"Vietnam (nationwide)","continent":"asia","languages":["vi"],"period":"contemporary"},"tags":["traditions","Vietnam (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Tết","de":"Tết","en":"Tết"},"url":"https://en.wikipedia.org/wiki/T%E1%BA%BFt","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Vietnam","de":"Culture of Vietnam","en":"Culture of Vietnam"},"url":"https://en.wikipedia.org/wiki/Culture_of_Vietnam","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"أسرة في هانوي تنظف البيت وتطلق سمكة مبروكة في البحيرة لإله المطبخ، وفي الصباح الأول تستقبل زائرًا مختارًا بعناية يحمل الحظ ومظروفًا أحمر.","de":"Eine Familie in Hanoi putzt das Haus, setzt einen Karpfen für den Küchengott in den See und empfängt am ersten Morgen einen sorgfältig gewählten Besucher mit Glück und einem roten Umschlag.","en":"A family in Hanoi cleans the house, releases a carp into the lake for the Kitchen God, and on the first morning welcomes a carefully chosen visitor who brings luck and a red envelope."},"misunderstanding":{"ar":"الاعتقاد الشائع أن تيت مجرد عطلة طويلة، لكنه في الحقيقة تنظيم اجتماعي دقيق للزيارات والعلاقات يبدأ قبل العيد بأيام.","de":"Viele halten Tết für bloß freie Tage, doch es ist eine fein geregelte soziale Ordnung von Besuchen und Beziehungen, die Tage vorher beginnt.","en":"Many assume Tết is simply a long break, but it is a precise social arrangement of visits and obligations that begins days before the holiday."},"comparison":{"ar":"يشبه تيت في وظيفته الاجتماعية زيارات رأس السنة في مجتمعات أخرى، حيث يُعاد ترتيب العلاقات ويُختبر حسن النية عبر أبواب تُفتح وتُغلق بعناية.","de":"Wie Neujahrsbesuche in anderen Gesellschaften ordnet Tết Beziehungen neu und prüft guten Willen über Türen, die bewusst geöffnet und geschlossen werden.","en":"Like new-year visiting in other societies, Tết reorders relationships and tests goodwill through doors that are opened and closed with care."}},{"id":"tra-026","version":2,"slug":"slametan-the-javanese-meal-that-sets-things-right","contentType":"note","category":"food-and-hospitality","title":{"ar":"سلامتان: الوجبة الجماعية التي تعيد الأمور إلى نصابها","de":"Slametan: Die javanische Mahlzeit, die Dinge in Ordnung bringt","en":"Slametan: The Javanese Meal That Sets Things Right"},"deck":{"ar":"في جاوة، يجتمع الجيران حول طعام مقدس لتحقيق الانسجام وإظهار التضامن.","de":"In Java versammeln sich Nachbarn zu einem rituellen Essen, um Harmonie und Gemeinschaft zu stärken.","en":"In Java, neighbours gather for a ritual meal to create harmony and show solidarity."},"teaser":{"ar":"طقس غذائي جاوي يجمع المجتمع لتكريم مراحل الحياة وتعزيز التضامن الاجتماعي.","de":"Ein javanisches Ritualessen, das die Gemeinschaft zusammenbringt und Lebensübergänge feiert.","en":"A Javanese ritual meal that brings the community together to mark life transitions and foster social harmony."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما هو السلامتان؟","paragraphs":["السلامتان، ويسمى أيضًا سيلاماتان، هو وجبة طقسية جماعية في جاوة تُقام عند الولادة والختان والزواج والانتقال إلى منزل جديد والحصاد والوفاة.","يُدعى الجيران، ويُقدَّم الطعام في أوراق الموز، ويلقي المضيف كلمة قصيرة باللغة الجاوية، تتبعها صلوات عربية ووجبة مشتركة.","الهدف هو خلق حالة من السلامة والرفاهية والانسجام الاجتماعي، ومشاركة الثواب مع الأسلاف والمجتمع."]},{"heading":"الطعام والمعنى","paragraphs":["التومبينج، وهو مخروط من الأرز الأصفر المحاط بأطباق جانبية، هو قطعة المركز الشائعة، وتوزيع الطعام بعد ذلك جزء من الالتزام.","تختلف الممارسة حسب المنطقة والجيل؛ فبعض المجتمعات تدمج الصلاة الإسلامية مع الممارسات الجاوية قبل الإسلامية، وهو ما انتقده المسلمون الإصلاحيون.","تظهر وجبات جماعية مماثلة تحت أسماء أخرى، مثل الكندوري، في جميع أنحاء الأرخبيل."]}],"de":[{"heading":"Was ist Slametan?","paragraphs":["Slametan, auch Selamatan genannt, ist ein gemeinschaftliches Ritualessen in Java, das Geburten, Beschneidungen, Hochzeiten, Hausumzüge, Ernten und Todesfälle markiert.","Nachbarn werden eingeladen, das Essen wird in Bananenblättern serviert, und der Gastgeber hält eine kurze Rede auf Javanisch, gefolgt von arabischen Gebeten und einem gemeinsamen Essen.","Das Ziel ist, slamet zu schaffen – einen Zustand von Sicherheit, Wohlbefinden und sozialer Harmonie – und Verdienste mit Vorfahren und der Gemeinschaft zu teilen."]},{"heading":"Essen und Bedeutung","paragraphs":["Tumpeng, ein Kegel aus gelbem Reis, umgeben von Beilagen, ist ein häufiges Herzstück, und die Verteilung des Essens danach ist Teil der Verpflichtung.","Die Praxis variiert je nach Region und Generation; einige Gemeinschaften verbinden islamische Gebete mit vorislamischen javanischen Praktiken, was reformistische Muslime kritisiert haben.","Ähnliche gemeinschaftliche Mahlzeiten erscheinen unter anderen Namen, wie kenduri, im gesamten Archipel."]}],"en":[{"heading":"What Is Slametan?","paragraphs":["Slametan, also called selamatan, is a communal ritual meal in Java that marks births, circumcisions, marriages, house moves, harvests and deaths.","Neighbours are invited, food is served in banana leaves, and the host gives a short speech in Javanese, followed by Arabic prayers and a shared meal.","The aim is to create slamet, a state of safety, well-being and social harmony, and to share merit with ancestors and the community."]},{"heading":"Food and Meaning","paragraphs":["Tumpeng, a cone of yellow rice surrounded by side dishes, is a common centrepiece, and distributing food afterwards is part of the obligation.","The practice varies by region and generation; some communities blend Islamic prayer with pre-Islamic Javanese practice, which reformist Muslims have criticised.","Similar communal meals appear under other names, such as kenduri, across the archipelago."]}]},"context":{"countries":["ID"],"region":"Java, Indonesia","continent":"asia","languages":["jv","id"],"period":"contemporary"},"tags":["food-and-hospitality","Java, Indonesia"],"sources":[{"organization":"Wikipedia","title":{"ar":"Slametan","de":"Slametan","en":"Slametan"},"url":"https://en.wikipedia.org/wiki/Slametan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Indonesia","de":"Culture of Indonesia","en":"Culture of Indonesia"},"url":"https://en.wikipedia.org/wiki/Culture_of_Indonesia","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عندما تنتقل عائلة إلى منزل جديد، تدعو كل الجيران إلى سلامتان، وتقدم التومبينج والدجاج، وحضور الجيران يشير إلى أن الأسرة أصبحت جزءًا من المجتمع.","de":"Eine Familie, die in ein neues Haus zieht, lädt die ganze Gasse zu einem Slametan ein, serviert Tumpeng und Hähnchen, und die Anwesenheit der Nachbarn signalisiert, dass der Haushalt nun dazugehört.","en":"A family moving into a new house invites the whole lane for a slametan, serves tumpeng and chicken, and the neighbours' attendance signals that the household now belongs."},"misunderstanding":{"ar":"يُفهم السلامتان أحيانًا خطأً على أنه عادة إندونيسية واحدة، لكنه في الواقع طقس جاوي يختلف حسب المنطقة والدين والبيئة الحضرية.","de":"Das Slametan wird manchmal fälschlicherweise als ein einziger indonesischer Brauch angesehen, ist aber ein javanisches Ritual, das je nach Region, Religion und städtischem Umfeld variiert.","en":"Slametan is sometimes mistaken for a single Indonesian custom, but it is a Javanese-centred ritual that varies by region, religion and urban setting."},"comparison":{"ar":"يشبه السلامتان وجبات جماعية أخرى في إندونيسيا مثل الكندوري، لكنه يتميز بتركيزه الجاوي وتقاليده الخاصة.","de":"Das Slametan ähnelt anderen gemeinschaftlichen Mahlzeiten in Indonesien wie dem Kenduri, zeichnet sich aber durch seine javanischen Traditionen aus.","en":"Slametan is similar to other communal meals in Indonesia like kenduri, but it is distinguished by its Javanese focus and traditions."}},{"id":"tra-027","version":2,"slug":"bayanihan-the-promise-that-neighbours-can-move-a-house","contentType":"note","category":"cities-and-community","title":{"ar":"باينيهان: وعد الجيران بحمل بيت","de":"Bayanihan: das Versprechen der Nachbarn","en":"Bayanihan: the promise that neighbours can move a house"},"deck":{"ar":"قيمة فلبينية تقوم على كلمة «باين» أي البلدة، وتختصر فكرة أن العمل المشترك أخف من العمل الفردي.","de":"Ein philippinischer Wert gemeinsamer Hilfe, gebaut auf dem Wort bayan für Stadt oder Gemeinschaft.","en":"A Filipino value of communal mutual aid, built on the word bayan, meaning town or community."},"teaser":{"ar":"من حمل أكواخ القرى على أعمدة الخيزران إلى أيام التطوع بعد الأعاصير، يحكي باينيهان كيف يعيد الجيران تعريف التضامن.","de":"Vom Tragen der Hütten auf Bambusstangen bis zu Freiwilligentagen nach Taifunen zeigt Bayanihan, wie Nachbarn Solidarität neu erfinden.","en":"From carrying village huts on bamboo poles to volunteer days after typhoons, bayanihan shows how neighbours keep reinventing solidarity."},"readingMinutes":1,"sections":{"ar":[{"heading":"البلدة التي تحمل بيتاً","paragraphs":["باينيهان قيمة فلبينية للتعاون الجماعي، جذرها كلمة «باين» أي البلدة أو المجتمع. الصورة الوطنية المرتبطة بها رجال يحملون كوخاً من القش على أعمدة خيزران إلى موقع جديد.","في الريف تعني عملاً مشتركاً في الحصاد وبناء البيوت والأعراس، يقدّم فيه المضيف الطعام ويقدّم المجتمع الأيدي. ويختلف شكلها بين الأجيال والمناطق، إذ يغلب التبادل الريفي في القرى ويغلب التطوع الحضري في المدن."]},{"heading":"من الرمز إلى المبادرة","paragraphs":["أُحييت العادة كاسم لاستجابة المتطوعين للكوارث وشبكات العمال الفلبينيين في الخارج وحملات الأحياء بعد الأعاصير. ويقول الأنثروبولوجيون إن نظام العمل التبادلي القديم يختلف عن العلامة الحديثة، وإن التحويلات المالية والعمل المأجور حلّا محل كثير من المشاركة الجسدية. تبقى صورة حمل بيت كامل رمزية اليوم، لكنها الاختصار المعتاد للتضامن الفلبيني."]}],"de":[{"heading":"Die Gemeinde, die ein Haus trägt","paragraphs":["Bayanihan ist ein philippinischer Wert gemeinsamer Nachbarschaftshilfe, gebaut auf dem Wort bayan, Stadt oder Gemeinschaft. Das nationale Bild zeigt Männer, die eine Nipa-Hütte auf Bambusstangen an einen neuen Ort tragen.","Auf dem Land bedeutet es geteilte Arbeit bei Ernte, Hausbau und Hochzeiten, wobei der Gastgeber Essen und die Gemeinschaft Hände stellt. Je nach Region und Generation unterscheidet sich die Form: auf dem Land überwiegt ländliche Gegenseitigkeit, in den Städten freiwilliges Engagement."]},{"heading":"Vom Symbol zur Initiative","paragraphs":["Der Brauch wurde als Etikett für freiwillige Katastrophenhilfe, Netzwerke philippinischer Arbeitsmigranten und Nachbarschaftsaktionen nach Taifunen wiederbelebt. Anthropologen unterscheiden das ältere System gegenseitiger Arbeit vom modernen Markenzeichen und merken an, dass Geldüberweisungen und bezahlte Arbeit viel der körperlichen Teilung ersetzt haben. Das Bild vom getragenen Haus ist heute weitgehend symbolisch, bleibt aber die übliche Kurzformel für philippinische Solidarität."]}],"en":[{"heading":"The town that carries a house","paragraphs":["Bayanihan is a Filipino value of communal mutual aid, built on the word bayan, town or community. The national image is of men carrying a nipa hut on bamboo poles to a new site.","In rural practice it means shared labour at harvest, house-building and weddings, with the host providing food and the community providing hands. The shape of it shifts between regions and generations, with rural reciprocity dominating villages and urban volunteering more common in cities."]},{"heading":"From symbol to initiative","paragraphs":["The custom has been revived as a label for volunteer disaster response, overseas Filipino worker networks and neighbourhood drives after typhoons. Anthropologists distinguish the older reciprocal labour system from the modern brand, and note that remittances and paid labour have replaced much of the physical sharing. The image of carrying a whole house is largely symbolic today, but it remains the standard shorthand for Filipino solidarity."]}]},"context":{"countries":["PH"],"region":"Philippines (nationwide)","continent":"asia","languages":["tl","en"],"period":"contemporary"},"tags":["cities-and-community","Philippines (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Bayanihan","de":"Bayanihan","en":"Bayanihan"},"url":"https://en.wikipedia.org/wiki/Bayanihan","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of the Philippines","de":"Culture of the Philippines","en":"Culture of the Philippines"},"url":"https://en.wikipedia.org/wiki/Culture_of_the_Philippines","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بعد إعصار، ينظّم الحي يوم باينيهان: يزيل الجيران سقفاً ساقطاً معاً، وتطبخ أسرة واحدة للجميع، وينتهي العمل قبل الظهر.","de":"Nach einem Taifun organisiert ein Barangay einen Bayanihan-Tag: Nachbarn räumen gemeinsam ein eingestürztes Dach ab, eine Familie kocht für alle, und die Arbeit ist vor Mittag fertig.","en":"After a typhoon, a barangay organises a bayanihan day: neighbours clear a fallen roof together, one family cooks for everyone, and the work finishes before noon."},"misunderstanding":{"ar":"يظن البعض أن حمل الكوخ ممارسة يومية، والحقيقة أن الصورة رمز، والواقع يتنوع بين تبادل ريفي وتطوع حضري وحملات حكومية.","de":"Manche halten das Hüttentragen für Alltagspraxis; tatsächlich ist es ein Symbol, und die Realität schwankt zwischen ländlicher Gegenseitigkeit, städtischer Freiwilligenarbeit und staatlichen Kampagnen.","en":"Some assume hut-carrying is everyday practice; in fact the image is a symbol, and reality varies between rural reciprocity, urban volunteering and state campaigns."},"comparison":{"ar":"يشبه باينيهان أنظمة العمل التبادلي في قرى كثيرة، لكنه يمتلك صورة رمزية قوية جعلته اسماً للتضامن في الكوارث.","de":"Bayanihan ähnelt Systemen gegenseitiger Arbeit in vielen Dörfern, besitzt aber ein starkes Symbolbild, das es zum Namen für Solidarität in Krisen machte.","en":"Bayanihan resembles reciprocal labour systems in many villages, but it carries a powerful symbolic image that made it the name for solidarity in disasters."}},{"id":"tra-028","version":2,"slug":"nowruz-seven-things-starting-with-sin","contentType":"note","category":"traditions","title":{"ar":"نوروز: سبعة أشياء تبدأ بحرف السين","de":"Nowruz: Sieben Dinge mit Sin","en":"Nowruz: Seven Things Starting with Sin"},"deck":{"ar":"كيف تحتفل الأسر الإيرانية بالاعتدال الربيعي: من مائدة السين إلى نار الأربعاء وسيزده بدر.","de":"Wie iranische Familien die Frühlings-Tagundnachtgleiche feiern: vom Haft-sin über das Feuer bis Sizdah Bedar.","en":"How Iranian families mark the spring equinox, from the haft-sin table to fire rituals and Sizdah Bedar."},"teaser":{"ar":"من مائدة السين إلى قفز النار، نوروز يجمع الأسر الإيرانية في طقوس متجددة عبر الأجيال.","de":"Vom Haft-sin bis zum Sprung über das Feuer: Nowruz verbindet iranische Familien mit Ritualen, die von Generation zu Generation weitergegeben werden.","en":"From the haft-sin table to leaping over bonfires, Nowruz brings Iranian families together in rituals passed down through generations."},"readingMinutes":1,"sections":{"ar":[{"heading":"مائدة السين: رمزية البدايات","paragraphs":["نوروز هو رأس السنة الفارسية في الاعتدال الربيعي، في 20 أو 21 مارس، ويُحتفل به في إيران والدول المجاورة، وتدرجه اليونسكو تراثًا غير مادي. تجمع الأسر سبعة عناصر تبدأ بحرف السين: سبزه (براعم)، سمنو (بودنغ القمح)، سنجد (خولنجان)، سير (ثوم)، سيب (تفاح)، سماق (سماق)، وسركة (خل).","تضاف مرآة وبيض ملون وحوض سمك ذهبي ونسخة من القرآن أو ديوان حافظ، لكن التكوين يختلف من عائلة لأخرى. وتختلف هذه التفاصيل أيضًا حسب المنطقة والجيل، إذ تضيف بعض الأسر عناصر محلية أو تستغني عن أخرى."]},{"heading":"النار والطبيعة: طقوس التطهير","paragraphs":["في ليلة الثلاثاء الأخيرة قبل نوروز، يُحتفل بأربعاء سوري بالقفز فوق النيران وهتاف «أعطني حمرتك وخذ صفرتي». وفي اليوم الثالث عشر، سيزده بدر، تخرج العائلات للتنزه وتلقي البراعم الخضراء في الماء الجاري لطرد الحظ السيئ. تبقى هذه الطقوس حية رغم تغير أشكالها بين الأجيال."]}],"de":[{"heading":"Der Haft-sin-Tisch: Symbolik des Neubeginns","paragraphs":["Nowruz ist das persische Neujahr zur Frühlings-Tagundnachtgleiche am 20. oder 21. März und wird in Iran und den Nachbarländern gefeiert; die UNESCO listet es als immaterielles Kulturerbe. Familien stellen sieben Gegenstände mit dem Buchstaben Sin zusammen: Sabzeh (Sprossen), Samanu (Weizenpudding), Senjed (Ölweide), Seer (Knoblauch), Sib (Apfel), Somaq (Sumach) und Serkeh (Essig).","Oft kommen ein Spiegel, bemalte Eier, eine Goldfischschale und ein Exemplar des Korans oder des Divan-e Hafez hinzu, doch die Zusammenstellung variiert von Familie zu Familie. Auch regional und generationell gibt es Unterschiede: Manche Familien ergänzen lokale Elemente oder lassen andere weg."]},{"heading":"Feuer und Natur: Reinigungsrituale","paragraphs":["Am letzten Dienstagabend vor Nowruz wird Chaharshanbe Suri mit Sprüngen über Freudenfeuer und dem Ruf „Gib mir deine Röte, nimm meine Gelbheit“ begangen. Am dreizehnten Tag, Sizdah Bedar, gehen Familien ins Freie, picknicken und werfen die grünen Sprossen in fließendes Wasser, um Unglück fortzuspülen. Diese Rituale bleiben lebendig, auch wenn sich ihre Formen zwischen den Generationen wandeln."]}],"en":[{"heading":"The Haft-Sin Table: Symbols of Renewal","paragraphs":["Nowruz is the Persian new year at the spring equinox, on 20 or 21 March, celebrated across Iran and neighbouring countries and listed by UNESCO as intangible heritage. Families assemble seven items beginning with the letter sin: sabzeh (sprouts), samanu (wheat pudding), senjed (oleaster), seer (garlic), sib (apple), somaq (sumac) and serkeh (vinegar).","A mirror, painted eggs, a goldfish bowl and a copy of the Quran or Divan-e Hafez are often added, though the composition varies by family. It also shifts by region and generation, with some households adding local elements or leaving others out."]},{"heading":"Fire and Nature: Rituals of Cleansing","paragraphs":["On the last Tuesday night before Nowruz, Chaharshanbe Suri is marked by jumping over bonfires and shouting “give me your redness, take my yellowness.” On the thirteenth day, Sizdah Bedar, families picnic outdoors and throw the sprouted greens into running water to send away bad luck. These customs remain alive even as their forms change between generations."]}]},"context":{"countries":["IR"],"region":"Iran (nationwide)","continent":"asia","languages":["fa"],"period":"contemporary"},"tags":["traditions","Iran (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Nowruz","de":"Nowruz","en":"Nowruz"},"url":"https://en.wikipedia.org/wiki/Nowruz","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Haft-sin","de":"Haft-sin","en":"Haft-sin"},"url":"https://en.wikipedia.org/wiki/Haft-sin","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"عائلة في طهران تضع مائدة السين على طاولة بجانب النافذة، وتضع سمكة ذهبية في حوض، وفي اليوم الثالث عشر تقود إلى سفوح الجبال لنزهة بجانب جدول.","de":"Eine Familie in Teheran stellt den Haft-sin auf einen Tisch am Fenster, setzt einen Goldfisch in eine Schale und fährt am dreizehnten Tag zu einem Picknick an einem Bach in die Vorberge.","en":"A Tehran family sets the haft-sin on a table by the window, places a goldfish in a bowl, and on the thirteenth day drives to the foothills for a picnic by a stream."},"misunderstanding":{"ar":"يُفترض أحيانًا أن مائدة السين واحدة لجميع الإيرانيين، لكن عناصرها وطقوسها تختلف حسب العائلة والمنطقة، ونوروز ليس ممارسة إيرانية واحدة.","de":"Manchmal wird angenommen, der Haft-sin sei für alle Iraner gleich, doch seine Elemente und Rituale unterscheiden sich je nach Familie und Region – Nowruz ist keine einheitliche iranische Praxis.","en":"It is sometimes assumed that the haft-sin is the same for all Iranians, but its items and rituals differ by family and region, and Nowruz is not a single Iranian practice."},"comparison":{"ar":"بينما تشترك دول المنطقة في الاحتفال بالاعتدال الربيعي، فإن طقوس النار ومائدة السين تحمل خصوصية إيرانية واضحة.","de":"Zwar feiern viele Länder der Region die Frühlings-Tagundnachtgleiche, doch die Feuerrituale und der Haft-sin tragen eine deutlich iranische Prägung.","en":"While many countries in the region celebrate the spring equinox, the fire rituals and the haft-sin carry a distinctly Iranian character."}},{"id":"tra-029","version":2,"slug":"the-georgian-supra-a-table-with-a-conductor","contentType":"note","category":"food-and-hospitality","title":{"ar":"السوبـرا الجورجية: مائدة لها قائد","de":"Die georgische Supra: ein Tisch mit Dirigent","en":"The Georgian supra: a table with a conductor"},"deck":{"ar":"في جورجيا، الطعام وال wine والتوasts تتبع نظامًا يقوده التامادا، فيجعل من العشاء حوارًا جماعيًا.","de":"In Georgien verbinden Essen, Wein und eine feste Reihenfolge von Trinksprüchen sich zu einem gemeinsamen Gespräch unter der Leitung des Tamada.","en":"In Georgia, food, wine and a formal sequence of toasts come together as a group conversation led by the tamada."},"teaser":{"ar":"السوبرا ليست مجرد طعام؛ إنها ترتيب اجتماعي يحدد من يتحدث ومتى يُشرب، ويحوّل المائدة إلى ذاكرة جماعية.","de":"Eine Supra ist mehr als ein Festmahl: Sie regelt, wer spricht und wann getrunken wird, und macht den Tisch zu einem kollektiven Gedächtnis.","en":"A supra is more than a feast: it decides who speaks and when anyone drinks, turning the table into a shared memory."},"readingMinutes":1,"sections":{"ar":[{"heading":"من يقود المائدة","paragraphs":["السوبرا مأدبة جورجية تجمع الطعام والنبيذ وسلسلة رسمية من الأنخاب، ويقودها التامادا، أي رئيس الأنخاب.","يقرر التامادا من يتكلم وبأي ترتيب ومتى يشرب الجميع؛ والتامادا الجيد يوازن بين الذاكرة والفكاهة ومزاج الغرفة.","تتناول الأنخاب عادة السلام والوطن والوالدين والراحلين والصداقة والحب والضيوف؛ وقد يُدعى الزائر ليقول نخبه، ورفض ذلك زلة اجتماعية."]},{"heading":"أطباق ومواقف","paragraphs":["تمتلئ المائدة بالخينكالي والكخاتشابوري وأطباق الجوز والباذنجان والأعشاب الطازجة والنبيذ، وغالبًا ما يكون منزليًا.","تُقام السوبرا في الأعراس وأعياد الميلاد والجنازات؛ وسوبرا الجنازة ذات نبرة مضبوطة وترتيب أنخاب خاص بها.","تختلف الأساليب بين كارتلي وكاخيتي والجبال والمهجر، وقد يُتوقع الشرب الكثير في بعض السوبرات لا في كلها."]}],"de":[{"heading":"Wer den Tisch führt","paragraphs":["Eine Supra ist ein georgisches Festessen aus Speisen, Wein und einer festen Folge von Trinksprüchen, geleitet vom Tamada, dem Toastmeister.","Der Tamada bestimmt, wer spricht, in welcher Reihenfolge und wann getrunken wird; ein guter Tamada verbindet Erinnerung, Humor und die Stimmung des Raums.","Die Trinksprüche gelten meist Frieden, Heimat, Eltern, Verstorbenen, Freundschaft, Liebe und Gästen; ein Gast kann gebeten werden, einen zu halten, und eine Ablehnung gilt als sozialer Fehltritt."]},{"heading":"Gerichte und Anlässe","paragraphs":["Der Tisch füllt sich mit Chinkali, Chatschapuri, Gerichten mit Walnuss und Aubergine, frischen Kräutern und oft hausgemachtem Wein.","Supras begleiten Hochzeiten, Geburtstage und Begräbnisse; die Trauersupra hat einen zurückhaltenden Ton und eine eigene Reihenfolge der Trinksprüche.","Der Stil unterscheidet sich zwischen Kartlien, Kachetien, den Bergen und der Diaspora, und starker Alkoholkonsum wird bei manchen Supras erwartet, bei anderen nicht."]}],"en":[{"heading":"Who runs the table","paragraphs":["A supra is a Georgian feast combining food, wine and a formal sequence of toasts, presided over by the tamada, the toastmaster.","The tamada decides who speaks, in what order and when anyone drinks; a good one balances memory, humour and the mood of the room.","Toasts usually cover peace, homeland, parents, the deceased, friendship, love and the guests; a visitor may be invited to give one, and refusing is a social misstep."]},{"heading":"Dishes and occasions","paragraphs":["The table fills with khinkali dumplings, khachapuri cheese bread, walnut and aubergine dishes, fresh herbs and wine, often homemade.","Supras mark weddings, birthdays and funerals; the funeral supra has a restrained tone and its own order of toasts.","Styles differ between Kartli, Kakheti, the mountains and the diaspora, and heavy drinking is expected at some supras but not all."]}]},"context":{"countries":["GE"],"region":"Georgia (nationwide)","continent":"asia","languages":["ka"],"period":"contemporary"},"tags":["food-and-hospitality","Georgia (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Supra (feast)","de":"Supra (feast)","en":"Supra (feast)"},"url":"https://en.wikipedia.org/wiki/Supra_(feast)","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Tamada","de":"Tamada","en":"Tamada"},"url":"https://en.wikipedia.org/wiki/Tamada","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في عيد ميلاد في تبليسي، يرفع التامادا النخب الأول للسلام، ثم للمضيفين، ثم يطلب من ضيفة أن تتحدث عن جدتها، فيسكت المائدة.","de":"Bei einem Geburtstag in Tiflis erhebt der Tamada den ersten Trinkspruch auf den Frieden, dann auf die Gastgeber, dann bittet er eine Gästin, über ihre Großmutter zu sprechen, und der Tisch wird still.","en":"At a birthday in Tbilisi, the tamada raises the first toast to peace, then to the hosts, then asks a guest to speak about her grandmother, and the table falls quiet."},"misunderstanding":{"ar":"يظن البعض أن السوبرا مجرد وليمة كبيرة، لكنها في الحقيقة نظام تواصل يحدد الكلام والشرب والاستماع.","de":"Manche halten die Supra für ein bloßes großes Essen, doch sie ist ein Kommunikationssystem, das Sprechen, Trinken und Zuhören ordnet.","en":"Some assume a supra is simply a large meal, but it is really a communication system that orders speaking, drinking and listening."},"comparison":{"ar":"تُقارن أحيانًا بمآدب عائلية طويلة في ثقافات أخرى، لكن ما يميزها هو وجود قائد صريح للأنخاب.","de":"Sie wird manchmal mit langen Familienessen anderer Kulturen verglichen, doch besonders ist der ausdrückliche Leiter der Trinksprüche.","en":"It is sometimes compared to long family dinners elsewhere, yet what sets it apart is the explicit conductor of the toasts."}},{"id":"tra-030","version":2,"slug":"hajj-five-days-that-reshape-a-life","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"الحج: خمسة أيام تعيد تشكيل الحياة","de":"Hadsch: fünf Tage, die ein Leben prägen","en":"Hajj: five days that reshape a life"},"deck":{"ar":"رحلة سنوية إلى مكة يقف فيها نحو مليوني حاج على جبل عرفات، فتختلط مشقة الجسد بصفاء الروح.","de":"Jedes Jahr reisen rund zwei Millionen Menschen nach Mekka; am Berg Arafat treffen körperliche Erschöpfung und spirituelle Intensität aufeinander.","en":"Every year around two million people travel to Mecca, where physical exhaustion and spiritual intensity meet on the plain of Arafat."},"teaser":{"ar":"من الإحرام إلى رمي الجمرات، يعيش الحجاج أياماً مكثفة تغيّر نظرتهم إلى أنفسهم وإلى الناس من حولهم.","de":"Vom Ihram bis zur Steinigung der Säulen erleben Pilger dichte Tage, die ihren Blick auf sich selbst und andere verändern.","en":"From entering ihram to stoning the pillars, pilgrims live through dense days that shift how they see themselves and others."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الإحرام إلى عرفات","paragraphs":["الحج هو الرحلة السنوية إلى مكة، واجبة مرة واحدة في العمر على من استطاع، ويقع في الشهر الثاني عشر من السنة الهجرية، وتجري مناسكه الرئيسية من اليوم الثامن إلى الثالث عشر.","يدخل الحاج في حالة الإحرام، وهي طهارة رمزية يلبس فيها الرجال ثياباً بيضاء بسيطة، ثم يطوف بالكعبة سبعاً ويسعى بين الصفا والمروة، ويقف بعرفة في اليوم التاسع.","الوقوف بعرفة هو الركن الأعظم؛ وبعد الغروب ينتقل الحجاج إلى مزدلفة، ثم يرمون الجمرات في منى ويذبحون هدياً لعيد الأضحى."]},{"heading":"مشقة وحشود وتنظيم","paragraphs":["يحضر نحو مليوني حاج في معظم الأعوام، ولكل دولة حصة محددة، وتدير السلطات السعودية تدفق الحشود والصحة والسلامة.","التجربة شاقة جسدياً، ويصف معظم الحجاج إرهاقاً يواكب كثافة روحانية عالية، وكثيرون يزورون المدينة قبل الرحلة أو بعدها.","تختلف تفاصيل المناسك قليلاً بين المذاهب، وكثير من المسلمين لا يؤدون الحج أبداً، والعمرة رحلة مختلفة أقصر.","ويتباين الحجاج بين الأجيال وفي المناطق المختلفة في عادات السفر والتحضير، إذ يسافر كبار السن عادة في مجموعات منظمة بينما يخطط الشباب لأنفسهم عبر التطبيقات."]}],"de":[{"heading":"Vom Ihram nach Arafat","paragraphs":["Der Hadsch ist die jährliche Pilgerfahrt nach Mekka, einmal im Leben verpflichtend für alle, die dazu fähig sind; er findet im zwölften islamischen Monat statt, die Hauptriten laufen vom achten bis dreizehnten Tag.","Pilger treten in den Ihram ein, einen Zustand ritueller Reinheit, den Männer an einfacher weißer Kleidung erkennen; dann umkreisen sie die Kaaba siebenmal, gehen zwischen Safa und Marwa und stehen am neunten Tag in Arafat.","Das Stehen in Arafat ist der zentrale Ritus; nach Sonnenuntergang ziehen die Pilger nach Muzdalifa, bewerfen in Mina die Säulen und opfern ein Tier zum Opferfest."]},{"heading":"Menschenmassen und ihre Ordnung","paragraphs":["In den meisten Jahren kommen etwa zwei Millionen Pilger, jedes Land erhält eine Quote; saudische Behörden regeln den Andrang, die Gesundheit und die Sicherheit.","Die Erfahrung ist körperlich fordernd, und die meisten Pilger beschreiben Erschöpfung neben spiritueller Wucht; viele besuchen auch Medina vor oder nach der Pilgerfahrt.","Details der Riten unterscheiden sich leicht zwischen Rechtsschulen, und die meisten Muslime vollziehen den Hadsch nie; die kürzere Umra ist eine andere Reise.","Auch zwischen Generationen und Regionen unterscheidet sich das Reisen, denn ältere Pilger reisen oft in organisierten Gruppen, während jüngere mit Apps selbst planen."]}],"en":[{"heading":"From ihram to Arafat","paragraphs":["Hajj is the annual pilgrimage to Mecca, obligatory once in a lifetime for Muslims who are able; it takes place in the twelfth Islamic month, with the main rites from the eighth to the thirteenth day.","Pilgrims enter ihram, a state of ritual purity marked by simple white clothing for men, then circle the Kaaba seven times, walk between Safa and Marwa and stand at Arafat on the ninth day.","The standing at Arafat is the central rite; after sunset pilgrims move to Muzdalifah, then stone the pillars at Mina and sacrifice an animal for Eid al-Adha."]},{"heading":"Crowds, fatigue and care","paragraphs":["Roughly two million pilgrims attend in most years, and each country receives a quota; Saudi authorities manage crowd flow, health and safety.","The experience is physically demanding, and most pilgrims describe exhaustion alongside spiritual intensity; many also visit Medina before or after.","Rite details differ slightly between schools of law, and most Muslims never perform Hajj; the shorter Umrah is a different pilgrimage.","Preparation also varies between generations and regions, with older pilgrims often travelling in organised groups while younger ones plan on apps."]}]},"context":{"countries":["SA"],"region":"Mecca and its surroundings","community":"Muslim pilgrims","continent":"asia","languages":["ar"],"period":"contemporary"},"tags":["beliefs-and-folklore","Mecca and its surroundings"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hajj","de":"Hajj","en":"Hajj"},"url":"https://en.wikipedia.org/wiki/Hajj","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Eid al-Adha","de":"Eid al-Adha","en":"Eid al-Adha"},"url":"https://en.wikipedia.org/wiki/Eid_al-Adha","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"حاج من إندونيسيا يلبس الإحرام الأبيض، وينضم إلى الحشود في سهل عرفات تحت شمس الظهيرة، ثم يحلق رأسه لاحقاً كأول علامة على قرب انتهاء الرحلة.","de":"Ein Pilger aus Indonesien trägt den weißen Ihram, steht am Nachmittag in der Hitze der Ebene von Arafat in der Menge und rasiert sich später den Kopf als erstes Zeichen, dass die Pilgerfahrt fast vollendet ist.","en":"A pilgrim from Indonesia wears the white ihram, joins the crowd on the plain of Arafat in the afternoon heat, and later shaves his head as the first sign that the pilgrimage is nearly complete."},"misunderstanding":{"ar":"يظن بعضهم أن الحج رحلة سياحية أو واجب على كل مسلم، لكنه فريضة مرة واحدة على المستطيع فقط، والعمرة ليست حجاً.","de":"Manche halten den Hadsch für Tourismus oder für eine Pflicht aller Muslime; er ist aber einmal im Leben für die Fähigen verpflichtend, und die Umra ist kein Hadsch.","en":"Some assume Hajj is tourism or a duty for every Muslim; it is required only once for those who are able, and Umrah is not Hajj."},"comparison":{"ar":"يشبه الحج مؤتمرات عالمية ضخمة في التنظيم والاختناق، لكنه يختلف عنها في أن كل تفصيل فيه ذو معنى روحي.","de":"Der Hadsch ähnelt großen globalen Konferenzen in Organisation und Gedränge, unterscheidet sich aber darin, dass hier jedes Detail einen geistlichen Sinn trägt.","en":"Hajj resembles huge global conferences in logistics and crowding, but differs in that every detail carries spiritual meaning."}},{"id":"tra-031","version":2,"slug":"shabbat-the-weekly-stopping-of-the-week","contentType":"note","category":"traditions","title":{"ar":"السبت: توقّف الأسبوع الأسبوعي","de":"Schabbat: das wöchentliche Innehalten","en":"Shabbat: the weekly stopping of the week"},"deck":{"ar":"من غروب الجمعة إلى حلول الليل يوم السبت، تُعيد عائلات كثيرة ترتيب وقتها حول وجبة وهدوء ووقفة عن العمل.","de":"Vom Sonnenuntergang am Freitag bis zur Dunkelheit am Samstag ordnen viele Familien ihre Zeit um Kerzen, ein gemeinsames Essen und das Ruhen von der Arbeit.","en":"From sunset on Friday to nightfall on Saturday, many families rearrange their time around candles, a shared meal and a pause from work."},"teaser":{"ar":"في إسرائيل لا يقتصر السبت على البيوت الملتزمة، بل يعيد تشكيل الشوارع والمواصلات والإيقاع اليومي لكل من يعيش هناك.","de":"In Israel bleibt der Schabbat nicht in den Wohnungen: Er verändert Straßen, Verkehr und den Rhythmus des Alltags für alle, die dort leben.","en":"In Israel, Shabbat does not stay indoors: it reshapes streets, transport and the daily rhythm for everyone living there."},"readingMinutes":1,"sections":{"ar":[{"heading":"من الشموع إلى الهدلة","paragraphs":["يبدأ السبت عند غروب شمس الجمعة بإشعال الشموع والكيدوش على النبيذ، وينتهي عند حلول الليل يوم السبت بصلاة الهدلة. وبين الطرفين تمتنع الأسر الملتزمة عن تسع وثلاثين فئة من الأعمال، بينها إشعال النار والقيادة والتعامل بالمال، وهي قواعد يفسّرها الحاخامات وتختلف من جماعة إلى أخرى.","عشاء الجمعة هو الوجبة العائلية المركزية، مع خبز الحلّة والأغاني والبركات، وفي بيوت كثيرة يكون هذا اللقاء هو التجمع الأساسي في الأسبوع.","يختلف الالتزام بين الأرثوذكس المتشددين والعلمانيين، ويتباين الطابع العام للسبت بشدة بين المدن والأحياء، كما تختلف العادات بين الأجيال داخل الأسرة الواحدة."]},{"heading":"سبتٌ في الشارع","paragraphs":["يشكّل السبت الحياة العامة في إسرائيل أيضًا: تتوقف الحافلات والقطارات إلى حد كبير، وتُغلق متاجر كثيرة، وتصمت الشوارع في الأحياء الدينية.","وللحياة الحديثة حلولها، مثل حدود العيروف والمصاعد التي تعمل تلقائيًا في السبت وصواني التسخين، بما يسمح بحياة ملتزمة داخل الأبنية المعاصرة."]}],"de":[{"heading":"Von den Kerzen bis zur Hawdala","paragraphs":["Der Schabbat beginnt am Freitagabend mit dem Entzünden der Kerzen und dem Kiddusch über Wein und endet am Samstag mit der Hawdala. Dazwischen verzichten observante Jüdinnen und Juden auf neununddreißig Kategorien von Arbeit, darunter Feuer anzünden, Autofahren und Geld anfassen; Rabbiner legen diese Regeln aus, und sie unterscheiden sich zwischen Gemeinden.","Das Freitagabendessen ist die zentrale Familienmahlzeit mit Challah, Liedern und Segenssprüchen; in vielen observanten Häusern ist es die wichtigste Zusammenkunft der Woche.","Die Praxis reicht von streng orthodox bis säkular, und der öffentliche Charakter des Schabbats unterscheidet sich stark zwischen Städten und Vierteln; auch zwischen den Generationen einer Familie variieren die Gewohnheiten."]},{"heading":"Ein Schabbat auf der Straße","paragraphs":["Der Schabbat prägt auch das öffentliche Leben in Israel: Busse und Züge fahren weitgehend nicht, viele Geschäfte schließen, und in religiösen Vierteln werden die Straßen still.","Für das Leben in modernen Gebäuden gibt es Anpassungen wie Eruv-Grenzen, Schabbat-Aufzüge und Warmhalteplatten, die einen observanten Alltag ermöglichen."]}],"en":[{"heading":"From candles to Havdalah","paragraphs":["Shabbat begins at sunset on Friday with candle-lighting and Kiddush over wine, and ends at nightfall on Saturday with Havdalah. In between, observant Jews refrain from thirty-nine categories of work, including lighting fires, driving and handling money; rabbinic authorities interpret these rules, and they differ between communities.","Friday dinner is the central family meal, with challah bread, songs and blessings; in many observant homes it is the main gathering of the week.","Observance ranges from strictly Orthodox to secular, and the public character of Shabbat varies sharply between cities and neighbourhoods; habits also shift between generations within one family."]},{"heading":"Shabbat in the street","paragraphs":["Shabbat also shapes public life in Israel: buses and trains largely stop, many shops close and streets in religious neighbourhoods become quiet.","Urban adaptations include eruv boundaries, Shabbat elevators and hotplates, which allow observant life inside modern buildings."]}]},"context":{"countries":["IL"],"region":"Israel","continent":"asia","languages":["he"],"period":"contemporary"},"tags":["traditions","Israel"],"sources":[{"organization":"Wikipedia","title":{"ar":"Shabbat","de":"Shabbat","en":"Shabbat"},"url":"https://en.wikipedia.org/wiki/Shabbat","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Israel","de":"Culture of Israel","en":"Culture of Israel"},"url":"https://en.wikipedia.org/wiki/Culture_of_Israel","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في القدس، تُشعل أسرة الشموع قبل الغروب، وتتناول العشاء مع الأجداد، ثم تمشي إلى الكنيس في الصباح بينما يبقى الشارع الرئيسي خاليًا.","de":"In Jerusalem zündet eine Familie vor Sonnenuntergang die Kerzen an, isst mit den Großeltern zu Abend und geht am Morgen zu Fuß zur Synagoge, während die Hauptstraße leer bleibt.","en":"In Jerusalem, a family lights candles before sunset, eats dinner with grandparents, and walks to synagogue in the morning while the main road stays empty."},"misunderstanding":{"ar":"يُفهم السبت أحيانًا كيوم صمت قسري على الجميع، لكنه في الواقع مجموعة عادات متنوعة تتراوح بين الصرامة الدينية والعلمانية الكاملة.","de":"Manchmal gilt der Schabbat als erzwungene Stille für alle, doch tatsächlich ist er ein Spektrum von Gewohnheiten zwischen strenger Religiosität und völliger Säkularität.","en":"Shabbat is sometimes seen as enforced silence for everyone, but it is really a range of habits, from strict religious practice to complete secularity."},"comparison":{"ar":"يشبه السبت إلى حد ما أي يوم راحة أسبوعي في ثقافات أخرى، لكنه يتميّز بحدود واضحة للعمل وبطابع عام يغيّر إيقاع المدينة كلها.","de":"Der Schabbat ähnelt einem wöchentlichen Ruhetag anderer Kulturen, doch die klaren Grenzen der Arbeit und der öffentliche Charakter verändern den Rhythmus der ganzen Stadt.","en":"Shabbat resembles a weekly rest day in other cultures, yet its clear limits on work and its public character change the rhythm of the whole city."}},{"id":"tra-032","version":2,"slug":"h-d-rellez-wishes-tied-to-trees-in-early-may","contentType":"scene","category":"nature-and-seasons","title":{"ar":"أمنيات معلّقة على الأشجار في أيار","de":"Wünsche an Bäumen im frühen Mai","en":"Wishes tied to trees in early May"},"deck":{"ar":"ليلة هيدريلّيز تجمع الجيران حول النار والأشجار، حيث تُربط الأمنيات بخيوط صغيرة وتُترك للربيع.","de":"In der Hıdırellez-Nacht treffen sich Nachbarn am Feuer und an Bäumen, binden kleine Wünsche fest und begrüßen den Frühling.","en":"On the Hıdırellez night, neighbours gather around fires and trees, tying small wishes to branches to welcome spring."},"teaser":{"ar":"في ليلة الخامس إلى السادس من أيار يلتقي الجيران حول النار ويعلّقون أمنياتهم على الأشجار احتفاءً بقدوم الربيع.","de":"In der Nacht vom 5. auf den 6. Mai versammeln sich Nachbarn um Feuer und Bäume, hängen Wünsche auf und feiern den Beginn des Frühlings.","en":"On the night of 5 to 6 May, neighbours gather around fires and trees, tying small wishes to branches and welcoming the fertile season."},"readingMinutes":1,"sections":{"ar":[{"heading":"ليلة النار والأمنيات","paragraphs":["تقع ليلة هيدريلّيز في الخامس إلى السادس من أيار، وتُفهم بوصفها لقاء النبيين حِزْر وإلياس، أي قدوم الربيع وبداية الموسم الخصيب. يقفز الناس فوق النيران ويتمنّون أمنياتهم، ويربطون قطعاً قماشية صغيرة أو أوراقاً تحمل أمنيات على الأشجار، ولا سيّما شجرة الأمنيات، وقد يرمي بعضهم أمنياتهم المكتوبة في الماء الجاري.","يُقضى النهار تقليدياً في الهواء الطلق مع النزهات والموسيقى وأطعمة خاصة، ويستغلّه الشباب لقراءة الفأل حول الزواج وشركاء المستقبل. والتاريخ ينتمي إلى التقويم الرومي القديم ويُعرف أيضاً باسم روزِ حِزْر، وهو احتفال ثقافي شعبي لا عطلة رسمية."]},{"heading":"تقاليد تتباين بين المناطق","paragraphs":["تختلف الطقوس اختلافاً واسعاً بين مناطق تركيا ومجتمعات البلقان والاحتفالات الحضرية، وكثيرون يتعاملون معها ببساطة كعيد للربيع. أدرجت اليونسكو احتفال هيدريلّيز الربيعي، بالاشتراك مع مقدونيا الشمالية، على قائمة التراث غير المادي عام 2017."]}],"de":[{"heading":"Eine Nacht voller Feuer und Wünsche","paragraphs":["Hıdırellez fällt auf die Nacht vom 5. auf den 6. Mai und gilt als Begegnung der Propheten Hızır und İlyas, verstanden als Ankunft des Frühlings und Beginn der fruchtbaren Jahreszeit. Menschen springen über Feuer, äußern Wünsche und binden kleine Stoffstücke oder Wunschzettel an Bäume, besonders an einen Wunschbaum; manche werfen aufgeschriebene Wünsche in fließendes Wasser.","Der Tag wird traditionell draußen mit Picknicks, Musik und besonderen Speisen verbracht, und junge Leute nutzen ihn für Vorzeichen zu Ehe und künftigen Partnern. Das Datum gehört zum alten Rumi-Kalender und heißt auch Ruz-ı Hızır; es ist ein kulturelles Volksfest und kein offizieller Feiertag."]},{"heading":"Regionale Unterschiede im Brauchtum","paragraphs":["Die Rituale unterscheiden sich stark zwischen türkischen Regionen, Balkan-Gemeinschaften und städtischen Feiern, und viele verstehen den Tag einfach als Frühlingsfest. 2017 nahm die UNESCO das Frühlingsfest Hıdırellez gemeinsam mit Nordmazedonien in die Liste des immateriellen Kulturerbes auf."]}],"en":[{"heading":"A night of fire and wishes","paragraphs":["Hıdırellez falls on the night of 5 to 6 May and marks the meeting of the prophets Hızır and İlyas, understood as the arrival of spring and the start of the fertile season. People jump over fires, make wishes and tie small cloths or paper wishes to trees, especially a wish tree, and some throw written wishes into running water.","The day is traditionally spent outdoors with picnics, music and special foods, and young people use it for omens about marriage and future partners. The date belongs to the old Rumi calendar and is also called Ruz-ı Hızır; it is a cultural folk celebration rather than an official public holiday."]},{"heading":"Customs that shift by region","paragraphs":["Rituals vary widely between Turkish regions, Balkan communities and urban celebrations, and many people treat it simply as a spring festival. UNESCO inscribed the spring celebration Hıdırellez, jointly with North Macedonia, on its intangible heritage list in 2017."]}]},"context":{"countries":["TR"],"region":"Anatolia and the Balkans","continent":"asia","languages":["tr"],"period":"contemporary"},"tags":["nature-and-seasons","Anatolia and the Balkans"],"sources":[{"organization":"Wikipedia","title":{"ar":"Hıdırellez","de":"Hıdırellez","en":"Hıdırellez"},"url":"https://en.wikipedia.org/wiki/H%C4%B1d%C4%B1rellez","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Turkey","de":"Culture of Turkey","en":"Culture of Turkey"},"url":"https://en.wikipedia.org/wiki/Culture_of_Turkey","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في مساء الخامس من أيار، تشعل عائلة في إزمير ناراً صغيرة في الحديقة، تقفز فوقها، وتربط شريطاً على شجرة تين مع أمنية، ثم تتقاسم نزهة في اليوم التالي.","de":"Am Abend des 5. Mai entzündet eine Familie in Izmir ein kleines Feuer im Garten, springt darüber, bindet ein Band mit einem Wunsch an einen Feigenbaum und teilt am nächsten Tag ein Picknick.","en":"On the evening of 5 May, a family in Izmir lights a small fire in the garden, jumps over it, ties a ribbon to a fig tree with a wish and shares a picnic the next day."},"misunderstanding":{"ar":"يظنّ بعض الخارجيين أنّ الأمر مناسبة دينية رسمية، لكنه في الواقع احتفال ثقافي شعبي لا عطلة عامة.","de":"Manche Außenstehende halten es für einen offiziellen religiösen Feiertag, doch es ist ein kulturelles Volksfest ohne gesetzlichen Feiertagsstatus.","en":"Outsiders sometimes assume it is an official religious holiday, but it is a cultural folk celebration without public holiday status."},"comparison":{"ar":"يشبه هذا التقليد عادات الربيع في كثير من المجتمعات الريفية حيث تُعلَّق الأمنيات على النباتات والمياه، لكن توقيته ورمزية النار تخصّ هذه المنطقة.","de":"Ähnliche Frühlingsbräuche mit Wünschen an Pflanzen und Wasser gibt es vielerorts, doch Zeitpunkt und Feuersymbolik sind typisch für diese Region.","en":"Spring customs that attach wishes to plants and water appear in many rural societies, yet the timing and fire symbolism are particular to this region."}},{"id":"tra-033","version":2,"slug":"sobremesa-the-hour-after-the-plates-are-cleared","contentType":"detail","category":"food-and-hospitality","title":{"ar":"السوبريميسا: ساعة بعد رفع الأطباق","de":"Sobremesa: die Stunde nach dem Abräumen","en":"Sobremesa: the hour after the plates are cleared"},"deck":{"ar":"في إسبانيا، لا تنتهي الوليمة مع الطعام، بل تبدأ بعدها: وقت للحديث والقهوة يسمى «سوبريميسا».","de":"In Spanien endet das Essen nicht mit dem letzten Bissen, sondern beginnt danach: die Sobremesa, Zeit für Gespräche und Kaffee.","en":"In Spain, the meal doesn't end when the food is gone; that's when the sobremesa begins—time for talk and coffee."},"teaser":{"ar":"بعد أن ترفع الأطباق، يبقى الناس على الطاولة يتحدثون. هذه العادة الإسبانية تعكس نمط حياة متوسطي يقدس العلاقات على حساب الكفاءة.","de":"Nach dem Abräumen bleiben die Menschen sitzen und reden. Diese spanische Gewohnheit spiegelt einen mediterranen Lebensstil wider, der Beziehungen über Effizienz stellt.","en":"After the plates are cleared, people stay at the table and keep talking. This Spanish habit reflects a Mediterranean way of life that values relationships over efficiency."},"readingMinutes":1,"sections":{"ar":[{"heading":"ما بعد الطعام: وقت للكلام لا للحلوى","paragraphs":["كلمة «سوبريميسا» تعني حرفياً «فوق الطاولة»: الفترة التي تلي انتهاء الطعام حين يبقى الناس جالسين يواصلون الحديث، غالباً مع القهوة أو مشروب مهضم. وهي ليست الحلوى، بل جوهرها المحادثة؛ ورفع الطاولة فوراً يُفسَّر على أنه استعجال للضيوف.","تزدهر هذه العادة في وجبات الغداء الطويلة في عطلة نهاية الأسبوع مع العائلة والأصدقاء، وفي المطاعم عادة لا يجلب النادل الفاتورة حتى تُطلب منه. وتختلف الممارسة بحسب المنطقة والجيل، فبعض العائلات الشابة تختصرها إلى فنجان قهوة سريع."]},{"heading":"ضغط الحياة الحديثة","paragraphs":["تعكس السوبريميسا نمطاً اجتماعياً متوسطياً يقوم على وجبات غداء طويلة وعشاء متأخر، لا على جدول مبني حول الكفاءة. لكن ساعات العمل الممتدة والتنقل يضغطان عليها.","ومع ذلك، تبقى علامة معترف بها على الحياة الاجتماعية الإسبانية، وتستخدم الكلمة في الإعلانات والسياحة."]}],"de":[{"heading":"Nach dem Essen: Zeit für Worte, nicht für Nachtisch","paragraphs":["Sobremesa bedeutet wörtlich „über dem Tisch“: die Zeit nach dem Essen, in der die Menschen sitzen bleiben und weiterreden, oft bei Kaffee oder einem Digestif. Sie ist nicht der Nachtisch; der Kern ist das Gespräch, und sofort abzuräumen wird als Drängen der Gäste zum Gehen verstanden.","Am stärksten ist sie bei langen Wochenendmittagessen mit Familie und Freunden, und in Restaurants bringt das Personal die Rechnung im Allgemeinen erst auf Nachfrage. Die Praxis variiert je nach Region und Generation – manche jüngere Familien kürzen sie auf einen schnellen Kaffee ab."]},{"heading":"Druck durch den modernen Alltag","paragraphs":["Die Sobremesa spiegelt ein mediterranes soziales Muster langer Mittagessen und später Abendessen wider, nicht einen auf Effizienz ausgerichteten Zeitplan. Doch längere Arbeitszeiten und Pendeln setzen sie unter Druck.","Dennoch bleibt sie ein anerkanntes Merkmal des spanischen Soziallebens, und das Wort wird in Werbung und Tourismus verwendet."]}],"en":[{"heading":"After the food: time for talk, not dessert","paragraphs":["Sobremesa literally means 'over the table': the time after the food is finished when people stay seated and keep talking, often over coffee or a digestif. It is distinct from dessert; the point is the conversation, and clearing the table immediately is read as hurrying guests out.","It is strongest at long weekend lunches with family and friends, and restaurant staff generally do not bring the bill until asked. The practice varies by region and generation—some younger families shorten it to a quick coffee."]},{"heading":"Pressure from modern schedules","paragraphs":["Sobremesa reflects a Mediterranean social pattern of long mid-day meals and late dinners rather than a schedule built around efficiency. But longer working hours and commuting put it under pressure.","Still, it remains a recognised marker of Spanish social life, with the word used in advertising and tourism."]}]},"context":{"countries":["ES"],"region":"Spain (nationwide)","continent":"europe","languages":["es"],"period":"contemporary"},"tags":["food-and-hospitality","Spain (nationwide)"],"sources":[{"organization":"Wikipedia","title":{"ar":"Sobremesa","de":"Sobremesa","en":"Sobremesa"},"url":"https://en.wikipedia.org/wiki/Sobremesa","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Spain","de":"Culture of Spain","en":"Culture of Spain"},"url":"https://en.wikipedia.org/wiki/Culture_of_Spain","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"بعد بايلا يوم أحد في فالنسيا، تُرفع الأطباق لكن لا أحد يتحرك؛ قهوة وزجاجة أوروخو وحديث عن وظيفة ابن العم الجديدة تمتد لتسعين دقيقة أخرى.","de":"Nach einer Sonntagspaella in Valencia werden die Teller abgeräumt, aber niemand bewegt sich; Kaffee, eine Flasche Orujo und ein Gespräch über den neuen Job eines Cousins ziehen sich weitere neunzig Minuten hin.","en":"After a Sunday paella in Valencia, the plates are cleared but nobody moves; coffee, a bottle of orujo and a conversation about a cousin's new job stretch for another ninety minutes."},"misunderstanding":{"ar":"يظن البعض أن السوبريميسا مجرد حلوى، لكنها في الحقيقة وقت للحديث؛ ورفع الأطباق فوراً قد يُفهم كطرد للضيوف.","de":"Manche halten Sobremesa für Nachtisch, doch sie ist Zeit für Gespräche; sofort abzuräumen kann als Hinausdrängen der Gäste verstanden werden.","en":"Some think sobremesa is just dessert, but it's really time for conversation; clearing the table immediately can feel like rushing guests out."},"comparison":{"ar":"في ثقافات أخرى، غالباً ما يُغادر المطعم فور الانتهاء من الطعام؛ أما هنا، فالبقاء على الطاولة هو المتعة الحقيقية.","de":"In anderen Kulturen verlässt man das Restaurant oft direkt nach dem Essen; hier ist das Sitzenbleiben der eigentliche Genuss.","en":"In other cultures, people often leave the restaurant right after eating; here, staying at the table is the real pleasure."}},{"id":"tra-034","version":2,"slug":"the-palio-a-horse-race-that-organises-a-city","contentType":"note","category":"cities-and-community","title":{"ar":"الباليو: سباق يوحّد مدينة سيينا","de":"Der Palio: ein Rennen ordnet die Stadt","en":"The Palio: a race that organises Siena"},"deck":{"ar":"في سيينا، سباق خيل سنوي يعيد ترتيب حياة الأحياء والعلاقات بين الجيران","de":"In Siena bestimmt ein Pferderennen den Rhythmus der Stadtviertel und ihrer Beziehungen","en":"In Siena, a twice-yearly horse race sets the rhythm of neighbourhood life and rivalry"},"teaser":{"ar":"سباق لا يدوم دقيقتين، لكنه ينظّم سنة كاملة من الانتماء والتحالفات والمنافسات بين سكان سيينا.","de":"Ein Rennen von unter zwei Minuten prägt ein ganzes Jahr voller Zugehörigkeit, Bündnisse und Rivalitäten in Siena.","en":"A race lasting under two minutes shapes a whole year of belonging, alliances and rivalries among Siena's neighbourhoods."},"readingMinutes":1,"sections":{"ar":[{"heading":"حياة الأحياء قبل السباق","paragraphs":["يُقام سباق باليو دي سيينا مرتين سنويًا، في الثاني من يوليو والسادس عشر من أغسطس، في ساحة ديل كامبو المنحدرة الشبيهة بالصدفة. تتنافس عشر من أحياء سيينا السبعة عشر، ولكل حي ألوانه وكنيسته وخصومه.","قبل السباق يستعرض أهالي الأحياء بأزياء عصر النهضة في موكب تاريخي، ويُبارك الحصان في كنيسة الحي. ينتمي الناس إلى أحيائهم عادة بالميراث العائلي والجيرة، فتتشكّل التحالفات والمنافسات داخل الحياة الاجتماعية اليومية."]},{"heading":"دقيقتان تعيدان ترتيب السنة","paragraphs":["لا يستغرق السباق دقيقتين، ومع ذلك يحمل ثقله طوال العام. حتى الحصان الذي يصل بلا فارس يمكن أن يفوز لحيّه، فيحصل الحي على راية الباليو المرسومة.","يختلف الاهتمام بالسباق بين الأجيال والمناطق، لكنه يبقى شأنًا محليًا خاصًا بسيينا وأحيائها، لا عادة إيطالية عامة.","يمنح هذا التقليد المدينة إيقاعًا مشتركًا: مواعيد ولقاءات وانتماءات تُروى وتُورَّث من جيل إلى جيل."]}],"de":[{"heading":"Das Leben der Contraden vor dem Rennen","paragraphs":["Der Palio di Siena wird zweimal jährlich ausgetragen, am 2. Juli und am 16. August, auf der schrägen, muschelförmigen Piazza del Campo. Zehn der siebzehn Contraden Sienas treten an, jede mit eigenen Farben, Kirchen und Rivalen.","Vor dem Rennen ziehen die Contradaioli im historischen Kostüm durch die Stadt, und das Pferd wird in der Kirche seiner Contrada gesegnet. Die Mitgliedschaft wird meist über Familie und Nachbarschaft vererbt, und Bündnisse wie Rivalitäten prägen das soziale Leben."]},{"heading":"Zwei Minuten, die das Jahr bestimmen","paragraphs":["Das Rennen dauert weit unter zwei Minuten, trägt aber das ganze Jahr. Sogar ein Pferd, das ohne Reiter ins Ziel kommt, kann für seine Contrada gewinnen, die dann das bemalte Palio-Banner erhält.","Das Interesse am Rennen variiert je nach Generation und Wohnort, doch es bleibt eine tief lokale Angelegenheit Sienas und seiner Contraden, kein allgemeiner italienischer Brauch.","So gibt der Palio der Stadt einen gemeinsamen Takt: Termine, Treffen und Zugehörigkeiten, die erzählt und weitergegeben werden."]}],"en":[{"heading":"Neighbourhood life before the race","paragraphs":["The Palio di Siena is run twice a year, on 2 July and 16 August, in the sloping shell-shaped Piazza del Campo. Ten of Siena's seventeen contrade compete, each with its own colours, church and rivals.","Before the race, contradaioli parade in Renaissance costume in the corteo storico, and the horse is blessed in its contrada church. Membership usually passes down through family and neighbourhood, and alliances and rivalries shape local social life."]},{"heading":"Two minutes that set the year","paragraphs":["The race lasts well under two minutes, yet it carries the whole year. Even a horse that finishes riderless can win for its contrada, which receives the painted palio banner.","Interest in the race varies between generations and parts of town, but it remains deeply local to Siena and its contrade, not a general Italian custom.","The Palio gives the city a shared rhythm: dates, gatherings and loyalties that are told and inherited."]}]},"context":{"countries":["IT"],"region":"Tuscany","continent":"europe","languages":["it"],"period":"contemporary"},"tags":["cities-and-community","Tuscany"],"sources":[{"organization":"Wikipedia","title":{"ar":"Palio di Siena","de":"Palio di Siena","en":"Palio di Siena"},"url":"https://en.wikipedia.org/wiki/Palio_di_Siena","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Italy","de":"Culture of Italy","en":"Culture of Italy"},"url":"https://en.wikipedia.org/wiki/Culture_of_Italy","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في السادس عشر من أغسطس، تمشي عائلة سيينية إلى كنيسة حيّها لتبارك الحصان، ثم تتدافع إلى الساحة بينما يجازف فارسها بخط قريب من الجدار الخارجي.","de":"Am 16. August geht eine Sieneser Familie zur Kirche ihrer Contrada zur Pferdesegnung und drängt sich danach auf der Piazza, während ihr Jockey eine riskante Linie an der Außenmauer fährt.","en":"On 16 August, a Sienese family walks to its contrada's church for the horse blessing, then crowds onto the piazza while their jockey rides a risky line along the outer wall."},"misunderstanding":{"ar":"يظن بعض الزوار أن الباليو عرض سياحي مفتوح للجميع، لكنه شأن محلي عميق، والدخول إلى الساحة الداخلية منظم.","de":"Manche Besucher halten den Palio für eine offene Touristenattraktion, doch er ist zutiefst lokal, und der Zugang zum inneren Platz ist geregelt.","en":"Some visitors assume the Palio is an open tourist spectacle, but it is a deeply local affair, and access to the inner square is controlled."},"comparison":{"ar":"يشبه الباليو مهرجانات الأحياء في مدن أخرى من حيث الانتماء، لكنه أكثر ارتباطًا بالهوية العائلية والجيرة.","de":"Der Palio ähnelt Stadtteilfesten anderswo durch seine Zugehörigkeit, ist aber stärker an Familie und Nachbarschaft gebunden.","en":"The Palio resembles neighbourhood festivals elsewhere in its sense of belonging, but it is more tightly bound to family and street."}},{"id":"tra-037","version":2,"slug":"krampus-the-frightening-half-of-december","contentType":"note","category":"beliefs-and-folklore","title":{"ar":"كرامبوس: النصف المخيف من ديسمبر","de":"Krampus: die schaurige Hälfte des Dezembers","en":"Krampus: the frightening half of December"},"deck":{"ar":"في جبال الألب، يجوب كرامبوس ذو القرون والفراء الشوارع في 5 ديسمبر، حاملاً السلاسل، بينما يوزع القديس نيكولاس الهدايا.","de":"In den Alpen zieht der gehörnte, pelzige Krampus am 5. Dezember mit Ketten durch die Straßen, während der heilige Nikolaus Gaben verteilt.","en":"In the Alps, the horned, fur-covered Krampus roams the streets on 5 December with chains, while Saint Nicholas hands out gifts."},"teaser":{"ar":"شخصية فولكلورية في النمسا وبافاريا وسويسرا تهدد الأطفال المشاغبين، وتجمع بين الخوف والاحتفال في ليلة واحدة.","de":"Eine volkstümliche Gestalt in Österreich, Bayern und der Schweiz, die böse Kinder bedroht und Angst und Feier in einer Nacht vereint.","en":"A folkloric figure in Austria, Bavaria and Switzerland who threatens naughty children, blending fear and celebration into one night."},"readingMinutes":1,"sections":{"ar":[{"heading":"من هو كرامبوس؟","paragraphs":["كرامبوس شخصية قرنية مغطاة بالفراء في الفولكلور الألبي، ترافق القديس نيكولاس مساء 5 ديسمبر، في النمسا وبافاريا وسويسرا والمناطق المجاورة. بينما يكافئ نيكولاس الأطفال الصالحين، يحمل كرامبوس السلاسل وأغصان البتولا ويهدد تقليدياً بأخذ الأطفال السيئين في كيس.","يرتدي الشباب أقنعة خشبية منحوتة يدوياً وجلود حيوانات في مواكب كرامبوسلاوف، وغالباً ما تُنحت الأقنعة محلياً وتُورَّث. للشخصية جذور ما قبل المسيحية، ربما مرتبطة ببيرشتن ومواكب أرواح الشتاء، لكن اقترانها بالقديس نيكولاس موثق من العصور الوسطى."]},{"heading":"المواكب والمعنى المحلي","paragraphs":["في القرن العشرين، قمعت السلطات الكنسية والمدنية كرامبوس في بعض المناطق، لكن المواكب اليوم أصبحت علامة هوية محلية وجاذبية سياحية. تختلف الممارسة إقليمياً وجيلياً: بعض العائلات تحتفظ بالشخصية لطيفة أو تتجنبها مع الأطفال الصغار، بينما يشارك آخرون بحماس في المواكب."]}],"de":[{"heading":"Wer ist Krampus?","paragraphs":["Krampus ist eine gehörnte, pelzbedeckte Figur der Alpenfolklore, die den heiligen Nikolaus am Abend des 5. Dezember, der Krampusnacht, in Österreich, Bayern, der Schweiz und angrenzenden Regionen begleitet. Während Nikolaus brave Kinder belohnt, trägt Krampus Ketten und Birkenruten und droht traditionell, böse Kinder im Sack fortzutragen.","Junge Männer tragen handgeschnitzte Holzmasken und Tierfelle bei Krampuslauf-Umzügen, und die Masken werden oft lokal geschnitzt und weitervererbt. Die Figur hat vorchristliche Wurzeln, möglicherweise verbunden mit Perchten und Winterspukzügen, doch die Paarung mit dem heiligen Nikolaus ist seit dem Mittelalter belegt."]},{"heading":"Umzüge und lokale Bedeutung","paragraphs":["Im 20. Jahrhundert wurde Krampus in Teilen von Kirche und Staat unterdrückt, heute sind die Umzüge sowohl lokales Identitätsmerkmal als auch Touristenattraktion. Die Praxis variiert regional und generationell: Manche Familien halten die Figur harmlos oder meiden sie für kleine Kinder, während andere begeistert an den Läufen teilnehmen."]}],"en":[{"heading":"Who is Krampus?","paragraphs":["Krampus is a horned, fur-covered figure in Alpine folklore who accompanies Saint Nicholas on the evening of 5 December, Krampusnacht, in Austria, Bavaria, Switzerland and neighbouring regions. While Nicholas rewards good children, Krampus carries chains and birch branches and traditionally threatens to carry bad children away in a sack.","Young men wear hand-carved wooden masks and animal skins for Krampuslauf processions, and masks are often carved locally and passed down. The figure has pre-Christian roots, possibly linked to Perchten and winter spirit processions, but its pairing with Saint Nicholas is documented from the Middle Ages."]},{"heading":"Processions and local meaning","paragraphs":["In parts of the twentieth century Krampus was suppressed by church and state authorities, and today the processions are both a local identity marker and a tourist attraction. Practice varies regionally and generationally: some families keep the figure mild or avoid it for small children, while others join the runs enthusiastically."]}]},"context":{"countries":["AT"],"region":"the Alps","continent":"europe","languages":["de"],"period":"contemporary"},"tags":["beliefs-and-folklore","the Alps"],"sources":[{"organization":"Wikipedia","title":{"ar":"Krampus","de":"Krampus","en":"Krampus"},"url":"https://en.wikipedia.org/wiki/Krampus","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}},{"organization":"Wikipedia","title":{"ar":"Culture of Austria","de":"Culture of Austria","en":"Culture of Austria"},"url":"https://en.wikipedia.org/wiki/Culture_of_Austria","accessed":"2026-11-17","supports":{"ar":"Background facts for this article.","de":"Hintergrundfakten für diesen Artikel.","en":"Background facts for this article."}}],"status":{"verification":"source-linked","editorial":"machine-drafted","translation":"machine-drafted","revision":1,"published":true},"related":[],"publishedAt":"2026-11-17","example":{"ar":"في قرية قرب سالزبورغ يوم 5 ديسمبر، تجوب شخصيات كرامبوس المقنعة الشوارع وهي تطلق خشخشة السلاسل بينما يختبئ الأطفال خلف والديهم، ويوزع القديس نيكولاس الجوز والبرتقال.","de":"In einem Salzburger Dorf am 5. Dezember rasseln maskierte Krampusse mit Ketten durch die Straße, während Kinder sich hinter ihren Eltern verstecken, und der heilige Nikolaus verteilt Nüsse und Orangen.","en":"In a Salzburg village on 5 December, masked Krampus figures rattle chains through the street while children hide behind their parents, and Saint Nicholas hands out nuts and oranges."},"misunderstanding":{"ar":"كرامبوس ليس عادة عيد ميلاد نمساوية عامة، بل هو تقليد إقليمي، وكثير من العائلات تجعله لطيفاً أو تتجنبه مع الصغار.","de":"Krampus ist kein allgemeiner österreichischer Weihnachtsbrauch, sondern regional, und viele Familien halten die Figur mild oder vermeiden sie für kleine Kinder.","en":"Krampus is regional, not a general Austrian Christmas custom, and many families keep the figure mild or avoid it for small children."},"comparison":{"ar":"بينما يرتبط القديس نيكولاس بالعطاء، يجسد كرامبوس الجانب التأديبي، مما يعكس توازناً بين المكافأة والعقاب في التقاليد الشعبية.","de":"Während der heilige Nikolaus das Geben verkörpert, steht Krampus für die disziplinierende Seite, was ein Gleichgewicht von Belohnung und Strafe in der Volkstradition zeigt.","en":"While Saint Nicholas embodies giving, Krampus represents the disciplining side, reflecting a balance of reward and punishment in folk tradition."}}];

